quests[12637] = { id = 12637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Um ein Haar", description = "Entweder war es Weisheit oder Glück, das Euch davon abgehalten hat, diesen Halsreif zu tragen, {race}.\n\nWie dem auch sei, dass Ihr ihn bekommen habt, war kein Zufall. Jemand oder etwas hat es auf Euch abgesehen...\n\nBringt Euren Halsreif zu Blutrose. Sie soll Euch zeigen, welches Schicksal Euch um ein Haar ereilt hätte.", sourceObjective = "Stefan in der Schwarzen Wacht möchte, dass Ihr den untoten Halsreif zu Datura Blutrose bringt.", progress = "Ja, {race}?", completion = "Nun habt Ihr gesehen, was Euch beinahe zugestoßen wäre.\n\nWie ich schon zuvor erwähnt habe, war dies kein Zufall. Ein solches Gerät herzustellen, erfordert viel Aufmerksamkeit, und die benötigten Ressourcen würden nicht auf ein zufälliges Ziel verschwendet werden.\n\nIm Grunde genommen ist es so: Die Geißel hat es auf Euch abgesehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[12638] = { id = 12638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine knappe Sache", description = "Entweder war es Weisheit oder Glück, das Euch davon abgehalten hat, diesen Halsreif zu tragen, {race}.\n\nWie dem auch sei, dass Ihr ihn bekommen habt, war kein Zufall. Jemand oder etwas hat es auf Euch abgesehen...\n\nBringt Euren Halsreif zu Blutrose. Sie soll Euch zeigen, welches Schicksal Euch um ein Haar ereilt hätte.", sourceObjective = "Stefan in der Schwarzen Wacht möchte, dass Ihr den zuckenden Halsreif zu Datura Blutrose bringt.", completion = "Nun habt Ihr also gesehen, welches Schicksal Euch gedroht hätte.\n\nWie ich schon erwähnte, war dies kein Zufall. Die Erschaffung eines solchen Apparates ist sehr umständlich. Ihr habt es geschafft, irgendwie die Aufmerksamkeit der Führung der Geißel auf Euch zu ziehen.\n\nDie Frage ist nicht wie, warum oder gar wer,... sondern was wir deswegen tun können?", sourceObjectiveStatus = "unverified-source-field" }
quests[12639] = { id = 12639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gefrorene Erde", description = "Diese Elementare haben wir in der Nähe gefunden und dann eingefangen - nun stehen mir zahlreiche Verteidiger zur Verfügung. Man muss jedoch über erhebliche Kräfte verfügen, um sie stark genug zu machen, damit sie auch gegen unsere Feinde standhalten können.\n\nDie gefrorene Erde bei Drak'Mabwa gen Nordwesten hat genau das, was ich brauche, um unsere Verteidigungen aufrechtzuerhalten. Ich werde noch mehr von ihrer Essenz benötigen, um meine Arbeit weiterhin machen zu können.", sourceObjective = "Elementzähmerin Dagoda in Zim'Torga möchte, dass Ihr 7 Essenzen der gefrorenen Erde beschafft.", progress = "Ich hoffe, dass Ihr genug zurückgebracht habt. Die Angriffe aus den Teichen von Jin'Alai sind verzweifelter geworden, nach dem, was Ihr dort angerichtet habt", completion = "Habt Dank, {class}. Mit diesen Essenzen sollte ich recht lange Zauber wirken können.", sourceObjectiveStatus = "unverified-source-field" }
quests[12640] = { id = 12640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Risse versiegeln", description = "Dagoda wird dich nach Nordwesten in Richtung Drak'Mabwa schicken, Mann, damit du dort mehr Zeug für ihre Verteidiger beschaffen kanns', falls sie das nich' schon gemacht hat.\n\nWenn du schon mal da oben bis', dann sollst du für Ahunae die Risse zerstören, aus denen die Elementare strömen. Das Letzte, was wir brauchen können, is', dass sie uns angreifen!\n\nPass bloß auf: Wenn du nämlich versuchst, die Risse zu schließen, dann wird noch mehr dieser gefror'nen Erde auftauchen.", sourceObjective = "Skalpierer Ahunae in Zim'Torga möchte, dass Ihr 7 Elementarrisse verschließt.", completion = "Ahunae hofft, dass Dagoda alle Verteidiger, die sie haben wollte, bekommen hat. Nun, da die Risse verschlossen sind, wird sie wahrscheinlich keine mehr bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12641] = { id = 12641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod kommt von ganz oben", description = "Hoch über dieser Plattform ist das Auge von Acherus. Dort werdet Ihr eine Sonde herbeirufen, mit der Ihr dann die Befestigungsanlagen des Scharlachroten Kreuzzugs bei Neu-Avalon analysieren könnt. Das Auge hat jede Menge Kräfte, welche die Beschaffung dieser Informationen einfach gestalten sollten.\n\nAnalysiert mithilfe der magischen Kräfte des Auges die Schmiede, Wacht, Kapelle und das Rathaus. Die Kontrollmechanismen für das Auge befinden sich auf jeder Seite dieser Plattform. Verliert nun keine Zeit mehr, {name}.\n\nDie Geißel wird diesen Ort einnehmen. Der Lichkönig befiehlt es!", sourceObjective = "Der Lichkönig befiehlt Euch, mithilfe des Auges von Acherus die Scharlachrote Festung, die Schmiede von Neu-Avalon, das Rathaus von Neu-Avalon und die Kapelle der Scharlachroten Flamme zu analysieren.\n\nDas Auge von Acherus lässt sich mithilfe der Steuerung für das Auge von Acherus kontrollieren.", progress = "Unser Angriff auf den Scharlachroten Kreuzzug wird zur Legende werden.", completion = "Sie bereiten sich wie erwartet auf den Kampf vor, doch da ist noch etwas Anderes. Ich spüre die Anwesenheit eines alten Feindes. Ein Feind, den ich vor langer Zeit vernichtet habe...\n\nEs macht nichts. Wir werden sie mit der geballten Macht der Geißel konfrontieren, bevor sie überhaupt die Chance haben, ihre Häuser zu evakuieren und ihre Verteidigungen bereitzustellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12642] = { id = 12642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geist von Rhunok", description = "Mein Gefühl sagt mir, dass Rhunok nicht viel Zeit bleibt.\n\nIch kann sehen, dass der Geist des arktischen Bärengottes sich bereits von seinem geschwächten Körper gelöst hat. Und es ist sein Geist, mit dem Ihr in Kontakt treten müsst.\n\nSein Altar liegt im Nordwesten, jenseits von Drak'Mabwa.", sourceObjective = "Sprecht mit dem Geist von Rhunok am Altar von Rhunok.", completion = "Ich bin kurz davor, loszulassen. Ihr müsst Euch beeilen oder es wird alles verloren sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[12643] = { id = 12643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lichtblick", description = "Wenn die Geißel erst einmal ein Ziel ins Auge gefasst hat, dann wird sie vor nichts zurückschrecken, um dieses Ziel auch zu erreichen.\n\nIhr seid dazu verdammt, Euer Dasein als hirnlose wandelnde Leiche zu verbringen...\n\n<Stefans Gesicht verzieht sich zu einer fiesen grinsenden Grimasse.>\n\n... außer, wir können ihre eigenen Begierden gegen sie selbst verwenden.\n\nIch werde es später erklären. Ich muss einen komplexen Zauber vorbereiten, der gewisse materielle Komponenten benötigt.\n\nReist gen Osten ins Land unterhalb der Reliquie der Pein. Erschlagt die Ghule und Monstrositäten, die Ihr dort finden werdet, und bringt mir ihre Überreste.", sourceObjective = "Stefan in der Schwarzen Wacht möchte, dass Ihr zur Reliquie der Pein geht und dort 5 eitrige Monstrositäteninnereien von den eitrigen Monstrositäten und 5 Einheiten glibbrigen Ghulsabbers sammelt.", progress = "Habt Ihr die Komponenten gebracht, um die ich Euch gebeten habe, {name}?", completion = "<Stefan inspiziert die faulen Komponenten.>\n\nNun, sie sind zwar weit davon entfernt, perfekt zu sein, doch es muss reichen.\n\nHaltet Euch nun fest, {class}. Jetzt wird's erst richtig spannend...", sourceObjectiveStatus = "unverified-source-field" }
quests[12644] = { id = 12644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destille Wasser sind tief", description = "Nun, da wir über die Rohmaterialien verfügen, bereitet mein Assistent den Destillierapparat vor. Er wird den Prozess überwachen, aber ich möchte, dass Ihr dabei helft, alles unter Kontrolle zu behalten. Womöglich denkt Ihr, dass wir einfach alles in den Apparat werfen und gut, aber das stimmt nicht.\n\nZutaten und Hitze müssen immer zu bestimmten Zeiten zugeführt werden, der Druck wiederum zu anderen. Euch bleiben nicht mehr als 10 Sekunden, um rechtzeitig zu reagieren. Sprecht mit \"Schluckspecht\" McManus, sobald ihr bereit seid zu destillieren.", sourceObjective = "Schließt den Destillationsprozess erfolgreich ab und bringt Donnerbräus Dschungelpunsch, wenn er fertig ist, zu Schnapsbart Donnerbräu in Nesingwarys Basislager.", progress = "Und, wie ist es geworden?", completion = "<Schnapsbart schüttelt den Behälter.>\n\nEs ist etwas drin, aber die Millionen-Gold-Frage ist, ob man es auch trinken kann. Ihr geht nirgendwo hin! Ihr seid auch dafür verantwortlich, das Probieren des Produkts zu überwachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12645] = { id = 12645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geschmackstest", description = "Und nun der Moment der Wahrheit!\n\n<Schnapsbart kichert.>\n\nIch wollte das schon immer mal sagen. Normalerweise würde ich ein neues Getränk bei einem Bankett vorstellen, aber wir können mitten im Dschungel nun mal keins abhalten.\n\nBringt stattdessen Proben zu ein paar guten Freunden und berichtet mir von ihrer Reaktion. Lasst mal sehen, wir wollen auf jeden Fall Hemets Meinung und ebenso Hadrius Harlowes. Sie sind hier im Lager. Ihr solltet auch Tamara Wackelspross beim Landeplatz am See in der Nähe des Beckenzentrums eine Geschmacksprobe anbieten.", sourceObjective = "Bietet Hemet Nesingwary, Hadrius Harlowe und Tamara Wackelspross eine Probe von Donnerbräus Dschungelpunsch an. Kehrt anschließend zu Schnapsbart Donnerbräu in Nesingwarys Basislager zurück.", progress = "Lasst mich nicht warten, {name}. Was ist herausgekommen?", completion = "Zwei von drei Kostern sind also zufrieden, hm? Nicht schlecht für einen ersten Versuch. Ganz und gar nicht. Ich denke, ich muss für Tamara als Entschuldigung etwas anderes zusammenrühren.\n\nHm... wie sollten wir diese Kreation nennen?", sourceObjectiveStatus = "unverified-source-field" }
quests[12646] = { id = 12646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feind mein Prophet", description = "Mein Prophet hat zu viel von meiner Kraft zu schnell absorbiert und sich dadurch selbst getötet. Ihr könnt das Ergebnis in den mit Wasser gefüllten Kratern gen Süden in Drak'Mabwa sehen.\n\nMeine früheren Priester haben ihn schon wiedererweckt, damit er zu Ende bringen kann, was er angefangen hat. Sie speisen ihn mit meiner Kraft und es wird nicht mehr lange dauern, bis er wieder erwacht.\n\nIhr müsst ihm ein Ende bereiten und mein Mojo zurückbringen, bevor es zu spät ist.", sourceObjective = "Der Geist von Rhunok am Altar von Rhunok möchte, dass Ihr sein Mojo des arktischen Bärengottes wiederbeschafft.", progress = "Schnell, {race}, sagt mir, habt Ihr mein Mojo?", completion = "Ihr habt es geschafft.\n\nEs gibt jedoch noch eine andere Angelegenheit, die Ihr für mich erledigen müsst.", sourceObjectiveStatus = "unverified-source-field" }
quests[12647] = { id = 12647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Leid ein Ende bereiten", description = "Mein Körper ist jetzt zu weit entfernt, {name}. Es ist nur eine Frage der Zeit, bis ein neuer Prophet erkoren wird und das zu Ende bringt, was die anderen begonnen haben.\n\nIch werde Euch meine letzten Kräfte verleihen. Der Foltermeister im Inneren des Altargebäudes hat ein Rauchwerk bei sich, das meinen Körper erwecken und wieder verwundbar machen wird.\n\nMacht von dem Rauchwerk Gebrauch und seid so nett und bereitet meinem Leid ein Ende.\n\nIch entschuldige mich schon einmal im Voraus, falls ich mich wehren sollte. Der Wille zu überleben ist selbst bei mir stark ausgeprägt.", sourceObjective = "Der Geist von Rhunok möchte, dass Ihr das Rauchwerk des Foltermeisters dazu einsetzt, um seinen Körper zu erwecken. Danach sollt Ihr Rhunok mithilfe der Macht, die sein Geist Euch verliehen hat, töten.\n\nFalls aus irgendeinem Grund die Aura für das Mojo von Rhunok von Euch weichen sollte, dann könnt Ihr zum Geist von Rhunok zurückkehren und Euch wieder segnen lassen.", progress = "Wenn Ihr nicht schon bald meinem Leiden ein Ende bereitet, {name}, dann könnte alles zu spät und verloren sein.", completion = "Ihr habt getan, was getan werden musste, und mir damit gleichzeitig Ehre erwiesen.\n\nTiefsten Dank, {name}. Ich hoffe nur, dass Ihr und Har'koa in der Lage sein werdet, den anderen zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12648] = { id = 12648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leger kleiden", description = "Hier... ich habe eine Verkleidung hergestellt, mit der Ihr nicht von einem Diener der Geißel zu unterscheiden sein solltet.\n\nSolange die Verkleidung anhält, ist es Euch möglich, Euch ungestört unter ihnen zu bewegen. Nur die Seuchenwachen werden dazu imstande sein, meine Illusion zu durchschauen - nehmt Euch also vor ihnen in Acht!\n\nWas Ihr noch wissen müsst, ist, dass die Verkleidung instabil ist und ganz unerwartet verschwinden kann - bleibt also wachsam.\n\nTesten wir es einmal aus. Benutzt den Halsreif, besucht den Händler der Geißel gleich östlich von hier und bringt mir von dort eine Flasche bitteres Plasma mit.", sourceObjective = "Stefan in der Schwarzen Wacht möchte, dass Ihr mithilfe des bezauberten Halsreifs die Geißelverkleidung auf Euch anwendet.\n\nWährend Ihr in Geißelgestalt seid, sollt Ihr bitteres Plasma von Knorpelsack kaufen.\n\nKehrt zu Stefan in der Schwarzen Wacht zurück, falls Ihr Euren bezauberten Halsreif verlieren solltet, und Ihr werdet Ersatz bekommen.", progress = "Nun, {name}?\n\nHabt Ihr das Fläschchen gekauft?", completion = "Nun? Wie bekommt Euch das Geißelleben?\n\nGlaubt mir, es ist nicht so, wie alle immer sagen...", sourceObjectiveStatus = "unverified-source-field" }
quests[12649] = { id = 12649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anziehen!", description = "Hier... ich habe eine Verkleidung hergestellt, mit der Ihr nicht von einem Diener der Geißel zu unterscheiden sein solltet.\n\nSolange die Verkleidung anhält könnt Ihr Euch ungestört unter ihnen bewegen. Nur die Seuchenwachen werden dazu imstande sein, meine Illusion zu durchschauen. Nehmt Euch also vor ihnen in Acht!\n\nWas Ihr noch wissen müsst, ist, dass die Verkleidung instabil ist und ganz unerwartet verschwinden kann - bleibt also wachsam.\n\nTesten wir es einmal aus. Benutzt den Halsreif und besucht den Händler der Geißel gleich östlich von hier. Bringt mir von dort eine Flasche bitteres Plasma mit.", sourceObjective = "Stefan in der Schwarzen Wacht möchte, dass Ihr mithilfe des bezauberten Halsreifs die Geißelverkleidung auf Euch anwendet.\n\nWährend Ihr in Geißelgestalt seid, sollt Ihr bitteres Plasma von Knorpelsack kaufen.\n\nKehrt zu Stefan in der Schwarzen Wacht zurück, falls Ihr Euren bezauberten Halsreif verlieren solltet, und Ihr werdet Ersatz bekommen.", progress = "Nun, {name}?\n\nHabt Ihr das Fläschchen gekauft?", completion = "Nun? Wie bekommt Euch das Geißelleben?\n\nGlaubt mir, es ist nicht so, wie alle immer sagen...", sourceObjectiveStatus = "unverified-source-field" }
quests[12650] = { id = 12650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eigene Artefakte plündern", description = "Es gibt noch einen Altar in der Nähe, wo es Artefakte zu retten gibt.\n\nMan sagt, dass die Drakkari im Altar von Rhunok im Nordwesten jenseits der zerstörten Tundra von Drak'Mabwa schon so weit sind, dass sie ihre eigene heilige Stätte plündern.\n\n{class}, ich wäre Euch sehr dankbar, wenn Ihr diese Artefakte retten und sie ihren unwürdigen Händen entreißen könntet.", sourceObjective = "Chronist To'kini in Zim'Torga möchte, dass Ihr 7 Rhunokianartefakte beschafft.", progress = "Man kann die Drakkari einfach nicht verstehen. Sie sind nichts weiter als brutale Barbaren, die noch tiefer gesunken sind.", completion = "Lasst mich einen Blick auf sie werfen.\n\n<Der Chronist untersucht die Artefakte, die Ihr gebracht habt.>\n\nHmpf, ich würde einmal sagen, dass wir uns glücklich schätzen können, dass Ihr diese hier aus ihrem Besitz befreit habt, {class}.\n\nWie überaus interessant. Dieses Artefakt hier zeigt die Ereignisse während der Teilung. Es war einmal eine Zeit, als Nordend den nördlichsten Teil von Kalimdor darstellte.\n\nDoch nach der Teilung brach das Land vom Rest ab und wurde schließlich zu dem Kontinent, den wir heute Nordend nennen.\n\nDas ist natürlich der Grund dafür, wieso die Drakkari hier und auf den südlichen Kontinenten vorzufinden sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[12651] = { id = 12651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Landeplatz am See", description = "Als der Ärger mit der Venture Company begann, bat ich Marvin Wackelspross und seine Frau Tamara, ihre Flugmaschinen nach Osten an den Flussnabel zu verlegen. Außerdem sollten sie dort ein kleines Lager aufbauen, damit wir es als Stützpunkt zum Einfliegen von Vorräten und zur Beobachtung des Gebiets nutzen können.\n\nSie sollten inzwischen angekommen und mit dem Aufbau beschäftigt sein. Der Flussnabel ist in der Nähe der Beckenmitte, wo die Flüsse ineinanderfließen. Sucht nach dem Landeplatz am See am nordöstlichen Ufer. Marvin erwähnte, dass dies der beste Platz sei.", sourceObjective = "Sprecht mit Tamara Wackelspross am Landeplatz am See.", completion = "Hemet schickt Euch also? Wir wollten ihn gerade benachrichtigen, dass wir hier alles aufgebaut und zum Laufen gebracht haben. Bitte verzeiht Marvin, falls er Euch ignoriert, aber er ist immer sehr versunken in seine Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[12652] = { id = 12652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebt dem Ghul Zucker", description = "Komm ma' her, Ghuul! Jep, mit dir red ich.\n\nIs' jetzt Fudderzeit. Muss all das Zeuch all den Ghuul'n bring'n!\n\nIs' diesma' schpessial Fudder, jawoll, ja! 'Ne Schüssel voll sämigem Hirn mit Kuddeln… Mjam, mjam, mjam.\n\nEinfach Schüssel neben Ghuul fall'n lass'n. Gut, um Freunde zu find'n.\n\nHabt Ihr Ghuulfreunde? Ha, ha, ha?", sourceObjective = "Knorpelsack an der Reliquie der Pein möchte, dass Ihr die Schüssel voll sämigem Hirn mit Kutteln in der Nähe von 10 zerfallenden Ghulen benutzt.", progress = "Fertich mit Ghuuls füddern?", completion = "Mjam, mjam!", sourceObjectiveStatus = "unverified-source-field" }
quests[12653] = { id = 12653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zu Har'koa", description = "Und nun ist es für Euch an der Zeit, zur Leopardengöttin zurückzukehren. Irgendwie spüre ich, dass sie andere Pläne für Euch hat.\n\nSagt Ihr, was auch immer kommt, wir sind ewig.", sourceObjective = "Sprecht mit Har'koa am Altar von Har'koa.", completion = "<Die Katzengöttin heult auf vor Schmerzen.>\n\nMeine Seele ist erfüllt von Kummer über den Verlust eines weiteren Freundes. Aber fürchtet Euch nicht, er wird zurückkehren und sein Geist wird für immer leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12654] = { id = 12654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Teilzeitjäger", description = "Als Hemet mich bat, Marvin hierher zu begleiten, hoffte ich, dass ich Gelegenheit fände, zwischen dem Reparieren der Flugmaschinen und dem Aufbauen des Lagers meine Jagdfähigkeiten zu verbessern.\n\nIch wollte einen wilden Löwen namens Pech erlegen. Angeblich lebt er südlich von hier, nahe der Stelle, wo der Wildwuchsmangal auf die nördliche Seite der Himmelszeltsäule trifft. Wenn Ihr die Kreatur findet, könntet Ihr mir ihre Überreste bringen? Wenn die Gerüchte wahr sind, ergeben sie eine Trophäe, vor der selbst Hemet Respekt hätte!", sourceObjective = "Bringt Pechs Überreste zu Tamara Wackelspross am Landeplatz am See.", progress = "Habt Ihr Pech gefunden?", completion = "Ihr habt sie! Nun muss ich daraus nur noch eine Trophäe herstellen. Das wird der harte Teil - einen Weg zu finden, das Ganze so zu präparieren, dass Hemet sich nicht auf meine Kosten lustig macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[12655] = { id = 12655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen von Zim'Rhuk", description = "Es gibt noch einen vernachlässigten Gott in Zul'Drak.\n\nZim'Rhuks Statue befindet sich direkt im Norden. Er ist als \"der Weise\" bekannt und auch dafür, dass er sehr beschützerisch ist, wenn es um sein Reich geht. Er unterhält Wächter, die jeden die Rute spüren lassen, der nicht schlau genug ist, um ungesehen an ihnen vorbeizuschleichen.\n\nGeht den Wächtern aus dem Weg und gebt Zim'Rhuk die Drakkariopfergaben, damit Ihr Euch seinen Segen zunutze machen könnt.", sourceObjective = "Hexendoktor Khufu möchte, dass Ihr der Statue von Zim'Rhuk 10 Drakkariopfergaben darbringt.", progress = "<Ihr spürt, dass Zim'Rhuk Euch kein Vertrauen entgegenbringt. Er ist kurz davor, einen seiner Wächter herbeizurufen.>", completion = "<Zim'Rhuk akzeptiert die Opfergaben, die Ihr ihm zu Füßen legen möchtet, obwohl er weiß, dass Ihr sie den Leichen anderer abgenommen habt.>\n\n<Ihr reicht ihm die Opfergaben dar, worauf er kurz zögert, zustimmt und Euch dann schließlich seinen Segen erteilt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12656] = { id = 12656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen von Zim'Rhuk", progress = "<Zim'Rhuk ist beeindruckt und frustriert, dass Ihr anscheinend wieder einmal seinen Wächtern durch die Finger gegangen seid - zumindest für den Moment.>\n\n<Platziert die Gaben zu seinen Füßen und er wird Euch abermals seinen Segen gewähren.>", completion = "<Zim'Rhuk zwingt Euch eine Vision auf, in der einer seiner Wächter Euch unter seinen Füßen zerquetscht. Vielleicht solltet Ihr versuchen, Zim'Rhuk zu besänftigen und ihm noch mehr Opfergaben darzubringen.>" }
quests[12657] = { id = 12657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht der Geißel", description = "Hört gut zu, Todesritter, denn was ich Euch mitzuteilen habe, wird einen Krieg auslösen. Mein endgültiges Urteil ist gesprochen: Tod - Allen. Niemand, der die Unverschämtheit besitzt, sich gegen die Macht der Geißel zu stemmen, darf ungeschoren davonkommen!\n\nIhr habt mir bei Eurer ersten Aufgabe gut gedient, also sollt Ihr mir auch bei Eurer nächsten Aufgabe gut dienen. Bringt mein Urteil, meinen Befehl zu Hochlord Mograine. Er befindet sich auf der ersten Etage des Kommandopostens von Acherus. Sagt ihm, dass er den Angriff einleiten soll.\n\nUnd wenn der Scharlachrote Kreuzzug erst einmal beseitigt ist, werden wir uns um die Argentumdämmerung kümmern.", sourceObjective = "Der Lichkönig gebietet Euch, seine Befehle zu Hochlord Darion Mograine in der Schwarzen Festung zu bringen.\n\nBenutzt den leuchtenden Transporter, der sich hinter dem Lichkönig befindet, um zu Hochlord Darion Mograine in die Hallen des Befehls zu gelangen.", completion = "Die Hörner des Krieges werden schon bald über dieses Land erschallen, sie werden die Toten erwecken und die Kriegsmaschine der Geißel ins Rollen bringen. Leid komme über diejenigen, die sich uns in den Weg stellen!\n\nIhr und Eure Brüder werdet den Angriff leiten, {name}. Und wenn ich das nächste Mal einen Blick auf die Lande des Scharlachroten Kreuzzuges werfen werde, so werden mir die Legionen von Acherus die Sicht nehmen. Der Marsch auf Neu-Avalon beginnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12658] = { id = 12658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein Kuschelroc", description = "Dorian ließ mich die von ihm gefangenen Drachenjungen ausbilden und füttern und das hat mich ins Grübeln gebracht. Ich möchte einen eigenen Begleiter!\n\nNein, keinen jungen Drachen. Ich möchte keinen Begleiter, der mir die Hand abbeißen kann!\n\nAllerdings gibt es in den Knochenfeldern nordöstlich des Lagers jenseits des von Drachen dominierten Gebiets eine große Menge Blutklauenrocs. Die ausgewachsenen lassen sich wohl nicht mehr zähmen, aber wenn Ihr mir die Eier aus ihren Nestern bringt, kann ich sie vom Moment des Schlüpfens an großziehen.", sourceObjective = "Bringt Spleenix bei Dorians Außenposten 7 Eier eines Rocs.", progress = "Habt Ihr diese Eier?", completion = "Oh, die sind wirklich schön! Ich bin die Gesellschaft mechanischer Eichhörnchen und Hühner so leid. Es wird wundervoll sein, einen Begleiter zu haben, dessen Gelenke nicht geölt werden müssen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12659] = { id = 12659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skalpe!", description = "Ich glaub', es is' an der Zeit, ein wenig zu skalpieren, Mann!\n\nDie Trolle von Heb'Drakkar eignen sich gut für so was. Mit ihren schicken Knüppeln und ihren Angriffen wollnse's ja gar nich' anders!\n\nUnd Ahunae gibt dir sogar sein Messer, damit du den Job richtig gut machen kannst.", sourceObjective = "Skalpierer Ahunae in Zim'Torga möchte, dass Ihr Ahunaes Messer benutzt, um 10 Heb'Drakkartrolle zu skalpieren.\n\nDer Skalpierer erinnert Euch daran, sie zuerst auszuplündern.", completion = "Oh, das is' zu komisch.\n\n{name} is' ein {race} ganz nach mei'm Geschmack!\n\nHast du noch mein Messer?", sourceObjectiveStatus = "unverified-source-field" }
quests[12660] = { id = 12660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtungswaffen", description = "Die Lakaien des Lichkönigs haben es gewagt, Vernichtungswaffen in meine Lande zu bringen. Dies werde ich nicht tolerieren.\n\nGeht zu ihrem Außenposten im Norden und zerstört die Waffen, die sie gegen das Land einsetzen wollen. Wir dürfen nicht zulassen, dass die Geißel auch nur einen Zoll dieser heiligen Länder besudelt.", sourceObjective = "Der Avatar von Freya möchte, dass Ihr zum Lager der Todeshand in den Nordwesten geht und 4 Stück des instabilen Sprengstoffs zerstört.", completion = "Ich danke Euch, {race}. Es ist gut, in Euch einen Verbündeten zu wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12661] = { id = 12661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Als Spion nach Voltarus", description = "Ihr habt die Einzelheiten meines Plans sicher bereits erraten.\n\nWir setzen das Interesse, das die Geißel an Euch hat, gegen sie ein. Ihr schleicht Euch verdeckt hinein. Ich weiß, dass dies vermutlich den Tod bedeutet, aber wenn wir nichts tun, so ist Euer Tod ganz gewiss.\n\nReist nach Nordosten zum Reliquiar des Schmerzes und stellt Euch auf die Plattform, nachdem Ihr Euch verkleidet habt. Einmal in Voltarus, müsst Ihr das Vertrauen des Geißelkommandanten erlangen.\n\nBlast dieses Horn, wenn Ihr Eure Mission abgeschlossen habt, und ich werde zu Euch fliegen, um den Bericht entgegenzunehmen.", sourceObjective = "Stefan möchte, dass Ihr Euren bezauberten Halsreif benutzt, um Euch in Voltarus einzuschleichen und dort alles zu tun, was der Anführer der Geißel von Euch verlangt.\n\nKehrt zu Stefan in der Schwarzen Wacht zurück, falls Ihr Euren bezauberten Halsreif verlieren solltet, und besorgt Euch einen neuen.", completion = "Nun gut… Ich muss zugeben, ich bin schon etwas überrascht, Euch zu sehen, {name}.\n\nSagt, was habt Ihr in Erfahrung bringen können?", sourceObjectiveStatus = "unverified-source-field" }
quests[12662] = { id = 12662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heb'Jin erledigen", description = "<Dagoda sieht Ahunae an und seufzt.>\n\nIhr wollt Euch wirklich um Heb'Drakkar kümmern? Einfach nur Skalps zu sammeln, wird nicht genug sein. Ihr müsst ihren Anführer Heb'Jin ausschalten.\n\nDas Problem ist nur, dass er oben auf dem Fledermaushorst steht und von dort seine Truppen antreibt.\n\nSchlagt seine Trommel und ich versichere Euch, dass er herunterkommen wird. Das ist der Moment, in dem Ihr ihn töten könnt.\n\nNehmt doch auch dieses Netz hier - wir haben es von seinen Kopfgeldjägern. Fangt damit seine Fledermaus ein, nachdem sie gelandet ist. Auf diese Weise müsst Ihr nicht beide bekämpfen.", sourceObjective = "Elementzähmerin Dagoda in Zim'Torga möchte, dass Ihr Heb'Jin tötet.", completion = "Ihr habt es geschafft!\n\n<Dagoda gibt Euch einen fetten Schmatzer auf die Wange.>\n\nIhr könnt Euch gar nicht vorstellen, wie mich das erleichtert! Die Trolle greifen uns von allen Seiten an und uns dagegen zu verteidigen, setzt uns wirklich unter Druck - von seinem ununterbrochenen Geschrei ganz zu schweigen.\n\nBitte, {name}, sucht Euch von dem hier etwas aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[12663] = { id = 12663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiedervereint", description = "{name}!\n\nDu musst mein Geschenk bekommen haben! Dreh dich um, Mann, und lasst mich dich mal ansehen... Ahhh, du machst mich stolz.\n\nWir haben viel hinter uns, du und ich, und nun werden wir beide dem Lichkönig dienen.\n\nHalt dich an mich und du wirst davon profitieren, Mann. Profitieren... doch zuerst müssen wir dich auf den neuesten Stand bringen. Viel ist passiert, seitdem wir uns das letzte Mal gesehen haben.\n\nGeh und sprich mit Grindbruch, damit er dich auf einen Rundflug über Zul'Drak mitnimmt. Hör mir zu und du wirst alles erfahren, was du wissen musst.", sourceObjective = "Drakuru in Voltarus möchte, dass Ihr mit Grindbruch sprecht und den Rundflug über Zul'Drak macht.", completion = "So, nun weißt du, was uns gegenübersteht, Mann.\n\nGeh hinunter, lass dir etwas Zeit, lern das Land kennen und denk dir irgendeine Strategie aus.\n\nIch werde schon bald ein paar Aufgaben für dich haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12664] = { id = 12664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkler Horizont", description = "Ahh, noch ein Bittsteller, der des Lichkönigs Ruf gefolgt ist.\n\n<Drakuru schnüffelt an Euch.>\n\nFrisch verseucht, hm? Du riechst noch immer wie die Lebenden!\n\nDie Reihe derer, die den Segen des Lichkönigs suchen, ist lang. Du musst dich von den Massen abheben und beweisen, dass du wahrer Macht würdig bist.\n\nAls ich über Zul'Drak hinweg sah, konnte ich spüren, dass etwas in dir steckt. Ich war es, der dich zu uns \"einladen\" ließ.\n\nDer Rest liegt an dir...\n\nGeh und sprich mit Grindbruch und er wird dich auf einen Rundflug über Zul'Drak mitnehmen. Es wird viel zu tun geben, wenn du überhaupt irgendeinen Wert für mich besitzen willst.", sourceObjective = "Drakuru in Voltarus möchte, dass Ihr mit Grindbruch sprecht und den Rundflug über Zul'Drak macht.", progress = "Hast du dir das Schlachtfeld schon angesehen, Mann?", completion = "So, nun weißt du, was uns gegenübersteht, Mann.\n\nIch möchte, dass du hinunter gehst, das Land kennenlernst und dich unter deine Brüder mischst. Sei bereit...\n\nSchon bald wird es viel für dich zu tun geben. Enttäusch mich bloß nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[12665] = { id = 12665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich spüre eine Erschütterung", description = "Etwas ist nicht in Ordnung mit Quetz'lun, der Windnattergöttin. Was genau es ist, vermag ich nicht zu sagen, aber ich weiß, dass ihr Altar von mächtigen Kreaturen überrannt wurde.\n\nIch werde Euch dorthin auf dem Rücken eines meiner von Euch geretteten Kinder entsenden. Zusammen werdet Ihr Euch schnell und verstohlen bewegen können, um das Rätsel um Quetz'luns Schicksal zu lösen.\n\nMein Kind wird Euch sicher zu mir zurückbegleiten. Haltet nur Eure Augen offen.\n\nSobald Ihr bereit seid, sagt Bescheid und ich werde eins meiner Kätzchen rufen.", sourceObjective = "Har'koa hat Euch gebeten, herauszufinden, was mit Quetz'lun geschehen ist. Sprecht mit ihr, um heimlich auf einem ihrer Kinder zum Altar von Quetz'lun zu reiten.\n\nKehrt zu ihr am Altar von Har'koa zurück, sobald Ihr die Aufgabe erfüllt habt.", progress = "Warum die Verzögerung, {name}?", completion = "Ich danke Euch, dass Ihr mein Kätzchen sicher zurückgebracht habt.\n\nTief in meinem Inneren wusste ich es bereits. Ich habe versucht, es zu leugnen, aber Eure Augen haben die Wahrheit ans Licht gebracht.\n\nTrotzdem spüre ich noch etwas Anderes. Es ist nicht alles so, wie es scheint.", sourceObjectiveStatus = "unverified-source-field" }
quests[12666] = { id = 12666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbereitungen für die Unterwelt", description = "Quetz'lun mag vielleicht tot sein, doch ich kann ihren Geist noch immer spüren: Sie ist in der Unterwelt bei ihrem Altar. Wir müssen herausfinden, wie wir Euch dorthin bringen können.\n\nWie es das Glück so will, steht mir eine Anzahl einstiger Bittsteller zur Verfügung, die nicht länger ihre heilige Zier benötigen. Meine Unterdrücker und Klauen werden sie höchstwahrscheinlich noch immer tragen.\n\nBringt mir diesen Schmuck und ich werde Euch mithilfe seiner Energie ein Tor zu Quetz'luns höllischer Unterwelt öffnen.", sourceObjective = "Har'koa am Altar von Har'koa möchte, dass Ihr 8 Stück heiliger Zier sammelt und sie anschließend bei ihr abliefert.", progress = "Ich hätte niemals geglaubt, dass es dazu kommen würde - die Drakkari sind wahrhaftig verloren.", completion = "<Die Leopardengöttin blickt traurig auf die vor ihr liegende Sammlung heiliger Symbole.>\n\nEs gab eine Zeit, als diese hier noch etwas zu bedeuten hatten... Sehen wir einmal, ob wir sie zu einem besseren Zweck einsetzen können", sourceObjectiveStatus = "unverified-source-field" }
quests[12667] = { id = 12667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht die Windschlangengöttin auf", description = "Ihr seid nun zwar bereit, doch ich bin mir nicht sicher, ob Ihr auch für das gewappnet seid, was denn kommen wird.\n\nWenn Ihr Euch zurück in den Bereich von Quetz'luns Altar begebt, dann werdet Ihr damit auch das Reich des Todes betreten. Ich hab's so im Gefühl, dass es kein angenehmer Aufenthalt sein wird.\n\nVersucht, Euch von den Dingen dort drinnen nicht ablenken zu lassen. Geht einfach nur in Richtung Altargebäude und sucht Quetz'luns Geist auf.", sourceObjective = "Geht zum Altar von Quetz'lun und sucht Quetz'luns Geist auf.", completion = "Du Wurm. Sag mir, wieso ich dich nicht an Ort und Stelle vernichten soll?", sourceObjectiveStatus = "unverified-source-field" }
quests[12668] = { id = 12668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Weg zur Rache ebnen", description = "Ich habe etwas Besonderes für meine Lieblingshohepriester geplant. Doch zuerst werdet Ihr den Grundstein für meine Rache legen und Euch somit beweisen.\n\nIhr wollt doch am Leben bleiben, oder?\n\nWie Ihr gesehen habt, genießen meine Verehrer ihren hiesigen Aufenthalt. Doch nun ist die Zeit gekommen, dass sie ihre letzte Schuld begleichen müssen.\n\nTut mir doch einen klitzekleinen Gefallen, {name}: Lockt sie in die Nähe meiner Seelenbrunnen und macht ihrem Dasein ein Ende.\n\nSie schmecken gar köstlich - und ihr Opfer wird nicht umsonst gewesen sein, das kann ich Euch versichern.", sourceObjective = "Quetz'luns Geist am Altar von Quetz'lun hat Euch damit beauftragt, in der Nähe ihrer Seelenbrunnen 12 Trolle zu töten. Diese können entweder Anbeter von Quetz'lun oder schlangengebissene Berserker sein.\n\nKehrt erst dann wieder zu ihr zurück, wenn Ihr Eure Aufgabe erfüllt habt.", progress = "Wieso kehrt Ihr schon zurück, obwohl Eure Aufgabe noch nicht erfüllt ist? Erkennt Ihr denn nicht, dass nur ein einziger Gedanke von mir genügt, um Euch zu zerstören?\n\nGeht nun, kleiner {race}. Führt meinen Befehl zu Ende!", completion = "Exquisit. Vielleicht seid Ihr doch zu etwas zu gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12669] = { id = 12669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So weit, so schlecht", description = "Alles, was Ihr mir berichtet habt, stimmt mit unseren Informationen überein. Etwas über Drakuru zu erfahren und sein Vertrauen zu gewinnen, stellt die Basis für Eure zukünftigen Missionen dar.\n\nKehrt zu ihm zurück und macht, was er sagt. Tut alles, was nötig ist, um glaubwürdig zu erscheinen, {name}. Vieles hängt davon ab, wie Ihr Euch macht.\n\nDoch dieses Mal werdet Ihr eine zusätzliche Aufgabe bekommen: Gießt diese Lösung in ihre Seuchenkessel dort draußen. Dadurch sollte ihr Seuchenwirkstoff neutralisiert und ihre Ladung unbrauchbar gemacht werden.", sourceObjective = "Stefan in der Schwarzen Wacht möchte, dass Ihr zu Drakuru zurückkehrt und alles tut, was er von Euch verlangt.\n\nWährend Ihr beim Reliquiar des Schmerzes seid, sollt Ihr die Verdünnungslösung in 5 Seuchenkessel schütten.\n\nKehrt zu Stefan in der Schwarzen Wacht zurück, falls Ihr Euren bezauberten Halsreif verlieren solltet, und Ihr werdet Ersatz bekommen.", progress = "{name}, bitte sagt mir, dass Eure Tarnung nicht aufgeflogen ist...", completion = "Gute Arbeit, {name}!\n\nDas Zeug in den Kesseln zu verdünnen, wird nicht nur Leben retten, sondern auch dafür sorgen, dass sich die Geißel in dieser Region nicht so schnell verbreitet.\n\nNun kommt schon, erzählt mir, was Ihr über Drakurus Strategie in Zul'Drak erfahren habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12670] = { id = 12670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Scharlachrote Ernte", description = "Unterhalb von Acherus befindet sich die Todesbresche, die Bühne, auf der unser Angriff auf den Scharlachroten Kreuzzug stattfinden wird. Schwingt Euch auf einen meiner Geißelgreifen, die auf beiden Seiten dieser Plattform zu finden sind, und meldet Euch bei Prinz Valanar. Tut, was er sagt, und Ihr möget den Tag erleben, an dem diese Länder unter unsere Herrschaft fallen werden.", sourceObjective = "Meldet Euch bei Prinz Valanar bei der Todesbresche.", completion = "Riecht Ihr das?\n\n<Valanar macht einen kurzen Atemzug.>\n\nFrisches Fleisch… Der Geruch des Scharlachroten Kreuzzugs liegt in der Luft.\n\nEntschuldigt, {class}, ich bin sicher, dass Ihr nicht interessiert seid an meiner Art der feinen Küche. Ihr seid hier, um zu arbeiten! Um den Angriff anzuführen! Ja... ich weiß. Der Lichkönig hat mir alles erzählt, was ich über Euch wissen muss, {name}.\n\nDie Zeit ist gekommen, um Blut zu vergießen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12671] = { id = 12671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufklärungsflug", description = "Es wird Zeit, dass wir hier Flugzeuge zum Laufen bringen. Die Professorin hat mich gebeten, das seltsame Wetterphänomen im Nordosten zu untersuchen.\n\nDie Sache ist, dafür brauche ich einen Copiloten, wenn wir in unbekanntes Territorium fliegen. Keine zehn Pferde bekommen mich da alleine hin.\n\nWas meint Ihr, Heißsporn? Vielleicht lernt Ihr noch ein oder zwei Dinge dazu. Und wenn Ihr erstmal lernt, mit den Winden des Nordens umzugehen... dann könnt Ihr so ziemlich überall fliegen.", sourceObjective = "Helft Pilot Vic den Aufklärungsflug abzuschließen.", completion = "Ihr habt mir da oben das Leben gerettet, Kumpel. Nette Flugkünste!", sourceObjectiveStatus = "unverified-source-field" }
quests[12672] = { id = 12672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wegbereiter", description = "Ich werde Euch die Chance geben, Eure Existenz noch ein wenig zu genießen.\n\nFragmente der Kraft, die meinem Fluch Nahrung gaben, sind über den Altarboden verteilt. Es ist mein Wunsch, dass Ihr einige davon für mich aufsammelt. Nicht so viele, dass mein Fluch aufgehoben wird, aber genug, dass es mir schließlich gelingen wird, Rache an meinem Propheten zu üben.\n\nGeht, Insekt. Lauft und erfüllt meine Befehle, bevor ich meine Meinung darüber ändere, Euch am Leben zu lassen.", sourceObjective = "Quetz'luns Geist verlangt, dass Ihr 10 Fragmente unterweltlicher Macht sammelt. Kehrt zu ihr zum Altar von Quetz'lun zurück, wenn Euch dies geglückt ist.", progress = "Eine Schande, dass Har'koa Euch nicht früher vorbeigeschickt hat. Auf der anderen Seite haben wir uns nie besonders gut verstanden.\n\nSie hat Eure Hilfe vermutlich einfach nur lange genug zurückgehalten, damit das hier geschieht.", completion = "Mit diesen wird es funktionieren. Wahrscheinlich brauche ich sie allerdings sowieso nicht.\n\nAber es hat Spaß gemacht, Euch nach meiner Pfeife tanzen zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12673] = { id = 12673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach oben buckeln, nach unten treten", description = "Wenn du es jemals wert sein willst, die Geschenke des Lichkönigs zu erhalten, dann musst du lernen, ein großer Anführer zu sein - einer, der Respekt abverlangt!\n\nIch habe eine Aufgabe für dich, die deine Fähigkeit zu Führen verfeinern wird, Mann...\n\nEinige meiner Diener sind dazu ausgebildet, Seuchenkristalle in dem Gebiet unter uns zu sammeln, doch sie sind faul und arbeiten nur langsam. Du wirst die Leitung über sie haben, Mann.\n\nNimm dieses Szepter und zeig ihnen, wie man die Arbeit richtig macht. Lass sie die Kristalle sammeln, sobald sie unter deiner Kontrolle sind!", sourceObjective = "Oberanführer Drakuru in Voltarus möchte, dass Ihr das Szepter der Suggestion auf die Seuchenspuke anwendet und sie dann 7 Seuchenkristalle sammeln lasst.", progress = "Wurden meine Untergebenen von dir zurechtgepeitscht, {name}?", completion = "Wir werden mehr Kristalle haben als je zuvor!\n\nMach weiter so, {name}. Ich werde schon bald noch mehr Aufgaben für dich haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12674] = { id = 12674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zornentbrannte Hölle", description = "Es ist nun Zeit, dass Ihr meine drei Hohepriester Mu'funu, Tua-Tua und Hawinni bestraft. Sie befinden sich alle irgendwo im Altargebiet verstreut.\n\nNehmt diesen Verhexungsstecken - er ist von meinem Zorn und Unwillen erfüllt. Ich bin mir sicher, dass er ein effektives Werkzeug sein wird.\n\nIhr müsst ihn einfach einsetzen und sie anschließend vernichten. Der Hex wird sich dann um den Rest kümmern.\n\n<Quetz'lun grinst über beide Ohren.>\n\nHabt Erfolg und ich werde Euch womöglich gehen lassen - versagt und Ihr werdet sterben.", sourceObjective = "Quetz'luns Geist am Altar von Quetz'lun möchte, dass Ihr Quetz'luns Verhexungsstecken auf Hohepriester Mu'funu, Hohepriester Tua-Tua und Hohepriester Hawinni anwendet. Anschließend sollt Ihr sie vernichten.", progress = "DENKT IHR ETWA, DASS ICH EIN IDIOT BIN?\n\nSIE SIND NICHT TOT!", completion = "<Der schreckliche Geist vor Euch gibt ein Gekicher von sich, das Euer Blut gefrieren lässt.>\n\nSie hätten damit rechnen können. Und ich werde ihnen dasselbe wieder und immer wieder zu spüren geben...", sourceObjectiveStatus = "unverified-source-field" }
quests[12675] = { id = 12675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine letzte Sache", description = "Da gäbe es noch eine letzte Sache zu erledigen und meine Rache am Propheten wäre perfekt. Die Fragmente der Macht, die Ihr gesammelt habt, müssen mit einem Teil des Geistes eines lebendigen Gottes erfüllt werden. Ihr werdet also Har'koa anflehen müssen, ob sie nicht etwas von ihrem Geist abgeben möchte.\n\nSobald dies dann getan ist und Ihr zurückkehrt, wird es nicht in der Unterwelt sein, nein, Ihr werdet zur materiellen Welt meines Altars zurückkehren. Meine Kinder und Wächter werden Euch nicht länger angreifen - Ihr könnt also zu meinem Propheten gelangen, ohne Euch großartig Sorgen wegen ihnen machen zu müssen.", sourceObjective = "Liefert die Fragmente unterweltlicher Macht bei Har'koa ab und bittet sie um einen Teil ihres Geistes. Sie befindet sich noch immer am Altar von Har'koa.", progress = "Ihr seid zurückgekehrt, {name}.", completion = "Ein Teil meines Geistes?\n\n<Die Schneeleopardengöttin hält einen Moment inne, um darüber nachzudenken.>\n\nDas ist ein ziemlich teures Geschenk, wenn man sich überlegt, dass es zu Rachezwecken eingesetzt wird und ich durch die Machenschaften meiner Unterdrücker schon ziemlich geschwächt wurde.\n\nIch weiß vielleicht trotzdem einen Weg, wie wir die Sache lösen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[12676] = { id = 12676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sabotage", description = "Wir werden versuchen herauszufinden, welchen Zweck diese Kristalle erfüllen, und Ihr geht zurück nach Voltarus und tut, was Drakuru von Euch verlangt.\n\nMit jeder Aufgabe, die Ihr für ihn erledigt, wird er Euch mehr Vertrauen schenken und uns damit Einblick in sein Denken gewähren.\n\nIch habe auch eine andere Aufgabe für Euch, während Ihr schon mal dort seid: Drakurus Geißelwagen stellen eine beträchtliche Gefahr dar - sie müssen zerstört werden.\n\nMacht Euch auf den Weg zu den Wagen und bringt diese Sprengladungen an. Geht in Deckung, sobald Ihr sie scharf gemacht habt! Die Explosion wird Euch verraten, wenn Ihr zu nah dran steht.", sourceObjective = "Stefan in der Schwarzen Wacht möchte, dass Ihr eine weitere Aufgabe für Drakuru erledigt.\n\nZusätzlich dazu müsst Ihr an 5 Geißelwagen im Reliquiar des Schmerzes Sprengladungen anbringen.\n\nKehrt zu Stefan in der Schwarzen Wacht zurück, falls Ihr Euren bezauberten Halsreif verlieren solltet, und Ihr werdet Ersatz bekommen.", completion = "Ausgezeichnet!\n\nEuer verdeckter Einsatz hat sich wirklich ausgezahlt, {name}.\n\nNun lasst uns einmal einen Blick auf dieses Szepter werfen...", sourceObjectiveStatus = "unverified-source-field" }
quests[12677] = { id = 12677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährliche Materialien", description = "Seuchenkristalle?! Was könnte dieser Mistkerl Drakuru nur vorhaben? Offensichtlich arbeitet er an etwas Bedeutendem.\n\nTanzt weiterhin nach seiner Pfeife und vielleicht, sobald er sich etwas mehr an Euch gewöhnt hat, wird er Euch seine Pläne verraten. Versucht in Voltarus ein paar Proben der geernteten Kristalle in die Finger zu bekommen, wenn gerade niemand hinsieht.\n\nDoch aufgepasst! Der Umgang mit diesen Kristallen könnte Euch enttarnen.", sourceObjective = "Stefan in der Schwarzen Wacht möchte, dass Ihr nach Voltarus geht und all das erledigt, was Drakuru Euch aufgibt. Während Ihr dort seid, sollt Ihr 5 geerntete Seuchenkristalle stehlen.\n\nKehrt zu Stefan in der Schwarzen Wacht zurück, falls Ihr Euren bezauberten Halsreif verlieren solltet, und Ihr werdet Ersatz bekommen.", progress = "Willkommen zurück, {name}.\n\nKonntet Ihr irgendwelche Proben von Drakurus Kristallen mitgehen lassen?", completion = "Faszinierend!\n\nWir werden uns diese Kristalle gleich einmal näher ansehen, um deren Beschaffenheit herauszufinden.\n\nNun sagt mir, {name}, gibt es irgendwelche Neuigkeiten über diesen Drakuru?", sourceObjectiveStatus = "unverified-source-field" }
quests[12678] = { id = 12678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leid wird vom Chaos getrieben", description = "Sie haben Stellung außerhalb der Todesbresche bezogen und versuchen vergeblich, uns zurückzudrängen. Sie hoffen, dass sie dadurch ihre Pferde, Minen, ihr Holz und ihre Bürger retten können.\n\nDies wird Eure erste Lektion in Sachen Geißelkriegsführung sein: SCHRECKEN!\n\nGeht an die südliche Front und tötet die Scharlachroten Kreuzfahrer. Lasst ihre Leichen in Ruhe, damit wir sie für unseren Todesfeldzug einsetzen können.\n\nDoch was am aller wichtigsten ist: tötet die flüchtenden Dorfbewohner. Tote Soldaten nehmen sie in Kauf, doch einfache Bürger? Das erfüllt die Herzen der Menschen mit Furcht.", sourceObjective = "Prinz Valanar in der Todesbresche befiehlt Euch, 10 Scharlachrote Kreuzfahrer oder Scharlachrote Arbeiter, und 10 Bürger von Havenau zu töten.", completion = "Könnt Ihr es spüren, {name}? Dieses Gefühl ist pure Macht, wie sie durch Euren Körper fließt. So etwas kennen Sterbliche nicht.\n\nWir haben an den Fronten den Sieg errungen. Die Spuke werden die Reste beseitigen und alles für Razuvious' Ankunft vorbereiten. Wir werden unsere Aufmerksamkeit nun auf taktischere Ziele richten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12679] = { id = 12679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heute Abend speisen wir in Havenau", description = "Die Himmelsverdunkler sind hirnlose Konstrukte, die nur ein Ziel kennen: TÖTEN! Sie haben es ganz besonders darauf abgesehen, jeden zu töten, der aus Havenau flieht, um sich in Neu-Avalon in Sicherheit zu bringen. Gewiss können wir diese Feiglinge nicht entwischen lassen, nur damit sie später die Waffen gegen uns erheben werden!\n\nEs gibt jedoch ein kleines Problem. Sie verwenden Saronitpfeile, um ihre Reichweite zu maximieren und den größtmöglichen Schaden anzurichten. Saronit ist allerdings ein Metall, das nur in Nordend vorkommt, also sind die Vorräte begrenzt! Beschafft mir diese Pfeile und ich werde Euch reich belohnen.", sourceObjective = "Orithos der Himmelsverdunkler in der Todesbresche möchte, dass ihr 15 Saronitpfeile beschafft.", progress = "Anhand der Flugbahn ihrer Pfeile würde ich sagen, dass sich die meisten südlich von uns auf den Höfen von Havenau und in deren näheren Umgebung finden lassen.", completion = "Gut gemacht, {class}! Eure Taten treiben die Kriegsmaschinerie der Geißel voran!\n\nAch ja, Eure Belohnung - wie versprochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12680] = { id = 12680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grand Theft Palomino", description = "Welch Zufall, dass der Scharlachrote Kreuzzug keinen Steinwurf von hier entfernt einen Stall voller Pferde hat. Sie bewachen ihn zwar hartnäckig, doch ein aufstrebender junger Todesritter könnte durch ihre Verteidigungen brechen und nehmen, was rechtmäßig ihm gehört!\n\nSobald Ihr dann ein Pferd aus den Ställen von Havenau besorgt habt, sollt Ihr es zu mir bringen und ich werde sehen, ob es sich in ein ordentliches Todesstreitross umwandeln lassen wird oder nicht.\n\nMerkt Euch, {name}: Gestohlen ist es erst dann, wenn man sich erwischen lässt. Und nehmt Euch vor dem verrückten Stallmeister Kitrik in Acht!", sourceObjective = "Salanar der Reiter in der Todesbresche möchte, dass Ihr ein Pferd aus den Ställen von Havenau stehlt und es zu ihm bringt.", progress = "Ihr wollt doch nicht für immer zu Fuß gehen, oder?", completion = "Nun zum eigentlichen Test: Habt Ihr das Zeug dazu, ein ungezähmtes Todesstreitross zu beherrschen und den Willen dessen zu brechen, nach dem es Euch am meisten verlangt?", sourceObjectiveStatus = "unverified-source-field" }
quests[12681] = { id = 12681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reagenzagent", description = "Der Erzmagier Pentarus in Dalaran wird erwarten, dass wir mit allerlei Arten von Reagenzien und Glücksbringern zurückkehren. Es sieht so aus, als hätten die Einheimischen Tierteile recht gern. Verdrehte Klauen von Blutklauenrocs scheinen ihnen die Liebsten zu sein.\n\nEs ist nicht an mir, zu sagen, ob die Gerüchte stimmen oder nicht, aber ich habe so das Gefühl, dass da durchaus etwas dran sein könnte.\n\nDie Rocs leben in den Knochenfeldern im Nordosten, wo sie sich von den Überresten alter Mammuts ernähren. Wollt Ihr mir helfen, für die Forschungsarbeit des Erzmagiers Klauen zu sammeln?", sourceObjective = "Bringt Colvin Norrington an Dorians Außenposten 5 verdrehte Rocklauen.", progress = "Habt Ihr es geschafft, verdrehte Klauen zu finden?", completion = "<Colvin schaut bewundernd auf die Klauen, die Ihr mitgebracht habt.>\n\nDiese werden mehr als ausreichen. Die Gorlocs haben ein Sprichwort, welches besagt: je verdrehter die Klaue, umso mehr Macht besitzt sie. Ich bin mir sicher, der Erzmagier wird bei dieser Expedition etwas für sein Geld bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12683] = { id = 12683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brenn darauf zu helfen", description = "Es gibt kein Material im ganzen Becken, das ätzender und beißender ist als Bittertiden-Hydrasputum. Ich besitze besondere Behälter, um es für Erzmagier Pentarus' Studien zu sammeln. Nun brauche ich nur noch jemanden, der mutig genug ist, es, ähm... einzusammeln.\n\nIhr wirkt wie <ein abgehärteter, abenteuerlustiger/eine harte> abenteuerlustige:c; {class}. Was haltet Ihr davon, Euch ein bisschen Geld zu verdienen und gleichzeitig Dalarans Sache zu helfen?\n\nAlles, was Ihr zu tun habt, ist, diesen Behälter zum Bittertidensee im Südwesten mitzunehmen. Greift eine Hydra an und benutzt den Behälter, um das Sputum einzufangen, das sie auf Euch niederregnen lässt.", sourceObjective = "Colvin Norrington bei Dorians Außenposten möchte, dass Ihr 5 Proben Hydrasputum sammelt und 5 Bittertidenhydras tötet.", progress = "Habt Ihr diese Proben besorgt?", completion = "Wunderbar! Hier ist Eure Bezahlung, wie abgemacht. Und, äh, ein kleiner Rat: Ihr solltet in den nächsten Tagen lange, heiße Bäder nehmen, wenn dieses \"brennende Gefühl\" weiter anhält.", sourceObjectiveStatus = "unverified-source-field" }
quests[12684] = { id = 12684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blut eines toten Gottes", description = "Mam'toth, der Gott der Mammuts, hat sich selbst vernichtet und dabei lieber den Großteil seines Tempels mit sich gerissen, als es seinen Trollen zu erlauben, seine Macht zu erlangen.\n\nWenn ich einen Teil meines Geistes opfern soll, so brauche ich etwas, um mich zu stärken.\n\nMam'toth hat einen enormen Krater im Nordosten hinterlassen, gerade nördlich des Altars von Quetz'lun. In diesem Krater lebt sein Blut noch immer.\n\nBringt es mir.", sourceObjective = "Har'koa hat Euch gebeten, 7 Blutproben von Mam'toth zu sammeln. Bringt sie zu ihr am Altar von Har'koa.", progress = "Ich wünschte, es gäbe etwas, womit wir Mam'toth von den Toten zurückholen könnten, aber es gibt nichts.\n\nWir können ihm und seinem Opfer Ehre erweisen, indem wir den Kampf gegen die Drakkari fortführen.", completion = "Nun gut. Lasst uns sehen, ob das hier funktioniert...", sourceObjectiveStatus = "unverified-source-field" }
quests[12685] = { id = 12685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Man erntet, was man sät", description = "Darauf ist es hinausgelaufen... Rache.\n\n<Har'koa seufzt.>\n\nNehmt diesen Beutel mit Ritualgegenständen und vollzieht in der Nähe von Quetz'luns Leiche auf ihrem Altar ein Ritual. Wenn alles reibungslos abläuft, dann sollte Ihr Geist in die materielle Welt gezogen werden, von wo aus sie ihre Macht vom Propheten wiedererlangen kann.\n\nDer Rest wird an Euch liegen, {name}. Ihr müsst den Propheten in seinem ausgelaugten Zustand erschlagen.", sourceObjective = "Erschlagt den ausgelaugten Propheten von Quetz'lun und informiert anschließend Hexendoktor Khufu in Zim'Torga.", completion = "<Der Hexendoktor schüttelt ungläubig den Kopf.>\n\nEs hört sich an, als wärt Ihr Quetz'luns Unterwelt gerade noch lebend entkommen.\n\nIch bin froh, dass es Euch gibt. Ich weiß nicht, ob ich den Mut gehabt hätte, um mit dieser Situation fertig zu werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[12686] = { id = 12686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Null Toleranz", description = "Ignoranz! Unerträglich ist das, Mann! Meine ganze Ladung Seuche ist zu nichts zu gebrauchen!\n\nDieser Bastard Darmuk! Er war dafür verantwortlich, ein Auge auf die Seuche zu werfen, doch enttäuscht hat er mich, Mann, enttäuscht!\n\nDas wird dir eine gute Lektion sein, {name}. Versagen ist wie ein gefährlicher Virus: Du musst schnell sein, ihn einfangen und töten, bevor er dich tötet!\n\nNimm dieses Szepter, es wird meine verseuchten Trolle stärker machen, damit du sie dann auf Darmuk hetzen und ihn töten kannst. Er liegt dort unten im Süden auf der Lauer.\n\nLass dies ein Beispiel für alle sein, Mann: Enttäusch Drakuru nich'!", sourceObjective = "Drakuru in Voltarus möchte, dass Ihr zum Reliquiar des Schmerzes geht und das Ermächtigungsszepter auf einen Diener von Drakuru anwendet, um anschließend mit seiner Hilfe Darmuk zu töten.", progress = "Hat Darmuk für sein Versagen schon bezahlen müssen, {name}?", completion = "Gut gemacht, {name}. Du lernst schneller, als ich gedacht habe.\n\nGeh jetzt und ruh dich etwas aus. Bald werde ich dich einer noch größeren Prüfung unterziehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12687] = { id = 12687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ins Reich des Schattens", description = "Das Pferd, das Ihr gestohlen habt, wurde ins Reich der Schatten verschleppt. Dort wird mein dunkler Reiter das Biest niederstrecken und es wieder als Todesstreitross auferstehen lassen. Denkt Ihr, dass Ihr den Mut besitzt, dem Ross hinterher ins Reich des Schattens zu folgen?\n\nSolltet Ihr einwilligen, werde ich Euch dorthin befördern. Geht nach Süden, sobald Ihr dort angekommen seid, und sucht auf den Feldern nach einem der dunklen Reiter. Um den Sieg davonzutragen, müsst Ihr ihn niederstrecken, sein Todesstreitross übernehmen und es wieder zur Todesanhöhe bringen. Lasst den Ruf des Reiters ertönen, falls Ihr erfolgreich sein solltet.", sourceObjective = "Salanar der Reiter auf der Todesanhöhe hat Euch dazu herausgefordert, einen dunklen Reiter von Acherus zu erschlagen und sein Todesstreitross von Acherus in Eure Gewalt zu bringen.\n\nBringt das Todesstreitross von Acherus auf die Todesanhöhe und lasst den Ruf des Reiters ertönen, um Salanar herbeizurufen.", completion = "Ihr hattet dort Erfolg, wo andere Initianden fehlschlugen, {name}. Dafür werdet Ihr großzügig belohnt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12688] = { id = 12688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Desaster konstruieren", description = "Diese idiotischen Goblins und ihre Anhänger haben beschlossen, dass diese Säule und ihre Kristalle nun ihnen gehören. Ich kam hierher, um die Kristalle zu untersuchen und Proben zu sammeln, aber sie haben mich überwältigt und wollten mich nicht zum Lager zurückkehren lassen.\n\nWenn Ihr mir helft, hier auszubrechen, können wir diesen Schlägern eine Lektion erteilen, die sie nie vergessen werden!", sourceObjective = "Helft Ingenieurin Helice, aus Schwindelgrins' Grabungsstätte zu entkommen, und sprecht dann mit Hemet Nesingwary in Nesingwarys Basislager.", completion = "Danke, dass Ihr Helice befreit und ihr zu einer sicheren Rückkehr verholfen habt. Wir waren alle bereits voller Sorge, als sie nicht von ihrer Suche nach Kristallen zurückkehrte.", sourceObjectiveStatus = "unverified-source-field" }
quests[12689] = { id = 12689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hand der Orakel", sourceObjective = "Hallo! Freut mich sehr, dich wiederzusehen!\n\nIch wusste, wir Freunde. Ich wusste es! Du guter Freund. Nicht nur von uns, sondern von allen Orakeln. Danke, dass du uns gerettet hast! Danke, danke!\n\nIch gesehen, wie du Wauwau gut verprügelt hast! Untotes Ding gesagt, dass ihr einmal gute Freunde - stimmt das? Ich davon nichts wissen. Doch du Wauwau fertig gemacht haben, oder? Du jetzt nur noch Freund von Orakel?\n\nHalt! Nicht zustimmen ohne Nachdenken. Du sicher nicht mehr Freund sein willst von Wauwauleuten?", sourceObjectiveStatus = "unverified-source-field" }
quests[12690] = { id = 12690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennstoff", description = "Es wird Zeit, dass wir auf Gundrak marschieren, Mann. Es wird Zeit, dass ich dich auf diese Trolle loslasse!\n\nSie sind durch unsere Mauern gestoßen und haben gleich nördlich von hier eine ganze Armee in Stellung gebracht.\n\nHahaha!\n\nSie werden nichts weiter als Brennstoff sein, Mann! Wir werden die Häuptlinge gefangen nehmen und den Rest töten! - alles Teil meines eigentlichen Plans...\n\nHier, nimm dieses Szepter und befiehl meine Monstrositäten. Schick sie zur Drakkariarmee und lass sie alle töten! Sobald die Häuptlinge auftauchen, wird mein Begleiter Schieferschwinge herbeieilen, sie ergreifen und hierher zu mir bringen.", sourceObjective = "Drakuru in Voltarus möchte, dass Ihr das Szepter des Befehls auf die aufgeblähten Monstrositäten anwendet und dann ihre Fähigkeiten dazu einsetzt, um 60 Schädelberster der Drakkari zu töten und 3 Häuptlinge der Drakkari hervorzulocken.\n\nDie Häuptlinge tauchen erst dann auf, wenn genug Schädelberster getötet wurden.", progress = "Hast du die Trolle platt gemacht, {name}?", completion = "Wir haben es geschafft, Mann!\n\nIch habe die Häuptlinge eingesperrt und du hast mithilfe meiner Monstrositäten den Sieg über ihre Armeen davongetragen.\n\nZeit zu feiern, Mann!", sourceObjectiveStatus = "unverified-source-field" }
quests[12691] = { id = 12691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verwitterte Kiste", description = "Die steinerne Kiste scheint verschlossen zu sein. Offensichtlich passt ein Schlüssel in das große Schlüsselloch aus Stein.\n\nVielleicht besitzt einer der Wächter in der Nähe diesen Schlüssel.", sourceObjective = "Erbeutet einen gewaltigen, steinernen Schlüssel von einem der Sholazarwächter in der Nähe und bringt ihn zur verwitterten Kiste bei der Warte der Schöpfer.", progress = "Die Steinkiste rührt sich nicht.", completion = "Der gewaltige, steinerne Schlüssel dreht sich mit einem tiefen Knarzen und die Kiste öffnet sich, um den verborgenen Schatz im Inneren zu enthüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12692] = { id = 12692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr des Lichjägers", description = "Gut, ich kehre zum Hügel der Wildherzen zurück, damit auch alle Wildherzen wissen, was du für Wolvar und Zepik getan. Du großer Jäger und sie so dumm, das nicht zu glauben.\n\nGeh zu Hügel zurück und sprich mit Ältesten Harkek... Ich sorge dafür, dass er erster Wildherz seien, der weiß, dass du kein Verräter.\n\nDanke, Lichjäger.", sourceObjective = "Kehrt zum Hügel der Wildherzen zurück und sprecht mit dem Ältesten Harkek.", completion = "Es gut, dich wiederzusehen. Ich wusste, du kein Verräter, ich froh, dass Zepik bewiesen hat.\n\nIch höre, du nun Lichjäger - das ziemlich gut! Du machst Harkek stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[12695] = { id = 12695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr der netten Trockenhaut", description = "Juhu! Soo-say wohl sorgen um uns! Vielleicht du gehst zurück zu Stadt und sagst ihm, dass alles in Ordnung? Ja, geh und erzähl Soo-say.\n\nIch werde glänzendes Kugelding von totem Lichkerl schnappen - ich dich dort treffen! Geh, geh! Ich dich dort treffen!", sourceObjective = "Kehrt zum Baldachin der Regenrufer zurück und sprecht mit dem Hochorakel Soo-say.", completion = "Gut, dich wiederzusehen! Wir besorgt, als du nicht sofort zurückkamst.\n\nJaloot dich zurückgetrieben - viel Energie in Jaloot, er sehr schnell. Er mir erzählte, wie du ihn vor Lichding gerettet. Moodle mir erzählt, wie du auch Mooswandler gerettet. Du wirklich nett.\n\nIch hoffe, du bei uns eine Weile bleibst. Immer etwas zu tun hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[12696] = { id = 12696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luftüberwachung", description = "Ihr wart Wes eine große Hilfe, als Ihr mit ihm diese Flugmaschine wieder zum Laufen gebracht habt.\n\nWenn Ihr uns weiterhin helfen wollt: Es gibt da eine ungewöhnliche, von Nordosten aufziehende Wettererscheinung. Ich verfüge bereits über einen einsatzbereiten Piloten, aber er braucht leider einen Copiloten.\n\nWenn Ihr Euch dem gewachsen fühlt, könnt Ihr den Flug zum Landeplatz am See nehmen. Sagt Vic, dass ich Euch geschickt habe.", sourceObjective = "Professorin Kalvert möchte, dass Ihr den Flug zum Landeplatz am See nehmt und dort mit Pilot Vic sprecht.", completion = "Die Professorin hat Euch zu mir geschickt? In Ordnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[12697] = { id = 12697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gothik der Ernter", description = "CHAOS, {name}! Der Kreuzzug ist wild geworden. Sie haben alle Streitkräfte außerhalb von Neu-Avalon dazu abbestellt, eine Blockade am Lichtgipfel östlich von hier zu errichten. Sie versuchen wie verzweifelt die Mine von Havenau leerzuschürfen und das Erz auf die Fregatten zu verladen, die an der Küste vor Anker liegen.\n\nNa dann lasst uns mal ein wenig Unruhe stiften. Gothik der Ernter, Großnekromant des Lichkönigs, hat uns mit seiner Anwesenheit gesegnet. Er hält ein Geschenk parat, das er gerne dem Scharlachroten Kreuzzug machen würde... Sucht ihn auf.", sourceObjective = "Sprecht mit Gothik dem Ernter in der Todesbresche.", completion = "Ihr habt hart gekämpft, um in das Reich des Ernters einzudringen... Wartet.\n\n<Gothik betrachtet seine Notizen.>\n\nIch möchte mich entschuldigen, {race}. Alte Gewohnheiten wird man nicht so schnell los.\n\nValanar hat Euch also geschickt? Ich kann mich dann darauf verlassen, dass Ihr eine gewisse Kompetenz besitzt.\n\nIch habe ein Geschenk für diese Hunde vom Scharlachroten Kreuzzug. Eines, das ihre Arbeit in den Minen sicherlich vorantreiben wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[12698] = { id = 12698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geschenk, das nicht aufhört zu schenken", description = "Ich bin aus dem gefrorenen Innersten von Naxxramas gekommen, um mich an Seelen gütlich zu tun und unseren Todfeinden eine ordentliche Tracht Prügel zu verpassen - nur leider gibt es keine Seelen mehr.\n\nDieses Gerät, das ich Euch gleich geben werde, ist ein tragbarer Seuchenverbreiter. Nehmt ihn, geht nach Osten zu den Minen von Havenau und entfesselt ihn auf die Scharlachroten Minenarbeiter, die dort drinnen arbeiten. Verwandelt die Minenarbeiter mit seiner Hilfe in Ghule und kehrt zu mir zurück, wenn Ihr eine kleine Armee um Euch gesammelt habt. Für sie habe ich einen besonderen Platz im Seelenstaubsauger freigehalten!", sourceObjective = "Gothik der Ernter in der Todesbresche hat Euch die Gabe des Ernters gegeben, um sie gegen die Scharlachroten Minenarbeiter einzusetzen. Erschafft mithilfe des Geräts 5 Scharlachrote Ghule und kehrt anschließend zu Gothik zurück.", progress = "Eine kleine Anmerkung: Minenarbeiter werden nicht immer zu Ghulen. Manchmal verwandeln sie sich in wütende Geister, die fest dazu entschlossen sind, Euch zu töten.", completion = "Sie wissen, dass die Minenarbeiter nicht länger sicher sind. Sie werden sich nun umso schneller zurückziehen, mit dem Rücken zu uns!", sourceObjectiveStatus = "unverified-source-field" }
quests[12699] = { id = 12699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der peinliche Vorfall", description = "Es gibt da ein kleines Problem zu lösen, bevor wir losziehen können. Wisst Ihr, ich kann den Schlüssel für meine Flugmaschine einfach nicht finden.\n\nIch hab' so ziemlich überall nach ihm gesucht... Vielleicht könnt Ihr mir helfen. Es gibt nur noch einen Ort, an dem ich noch nicht gesucht habe: im See.\n\nIch werde Euch sogar meinen eigenen Lufttank zur Verfügung stellen. Er ist zwar fast leer, hat jedoch noch genug Luft für ein paar Atemzüge.", sourceObjective = "Sucht nach Vics Schlüssel im See am Flussnabel.", progress = "Habt Ihr schon was gefunden, {name}?", completion = "Ausgezeichnet!", sourceObjectiveStatus = "unverified-source-field" }
quests[12700] = { id = 12700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gelegenheitsangriff", description = "Nur die Streitkräfte des Scharlachroten Kreuzzugs bei Neu-Avalon und dem Lichtgipfel stellen noch eine Herausforderung dar! Die Zeit, die Scharlachrote Flotte beim Lichtgipfel anzugreifen, ist gekommen.\n\nDas Ablenkungsmanöver an der Mine hat sie ins Chaos gestürzt. Sie versuchen verzweifelt, die Gegend freizuräumen und zu ihren Schiffen zurückzukehren.\n\nDie Zeit ist reif! Prinz Valanar nutzt die Gelegenheit, um ihrer Flotte den letzten Stoß zu versetzen. Meldet Euch bei ihm - umgehend!", sourceObjective = "Sprecht mit Prinz Valanar in der Todesbresche.", completion = "Ihr habt uns gut gedient, {class}. Nur wenige Eurer Brüder haben den ersten Angriff auf die Eindringlinge des Scharlachroten Kreuzzugs überlebt. Ihr seid als einer der Stärksten hervorgegangen.\n\n\n\nÖstlich von uns jenseits der Mine von Havenau liegt die Küste - vom Scharlachroten Kreuzzug \"Lichtgipfel\" genannt. Zwischen uns und ihren Schiffen stehen Eintausend ihrer Soldaten. Unüberwindlich? Davon kann kaum die Rede sein...", sourceObjectiveStatus = "unverified-source-field" }
quests[12701] = { id = 12701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Massaker am Lichtgipfel", description = "In ihrer Eile werden die Diener des Scharlachroten Kreuzzugs einen schwerwiegenden Fehler begehen: zu vergessen, ihre Loren zu überprüfen.\n\nIhr sollt nach Osten zur Mine von Havenau reisen und die Lore finden, die meine Diener am Nebengebäude abgestellt haben. Klettert dann hinein und ein Scharlachroter Minenarbeiter wird sich unwissentlich darum kümmern, dass Ihr sicher hinter die feindlichen Linien gebracht werdet.\n\nSobald Ihr dann an Bord eines ihrer Schiffe seid, sollt Ihr ihre Kanonen gegen sie verwenden! SCHLACHTET SIE ALLE AB!\n\nRuft den Geißelgreif herbei, wenn Ihr bei der Kanone steht, und er wird Euch sicher wieder zurückbringen.", sourceObjective = "Prinz Valanar in der Todesbresche hat Euch befohlen, 100 Scharlachrote Verteidiger zu vernichten.", progress = "{class} kennen keine Angst!", completion = "Ihr habt die gesamte Flotte des Scharlachroten Kreuzzugs in wenigen Minuten ausradiert! Ich werde vom Lichkönig dafür eine Auszeichnung erhalten! Alles, was vom Scharlachroten Kreuzzug noch übrig bleibt, sind die Bewohner von Neu-Avalon.\n\nIch werde die Brandstifter und Nekromanten umgehend auf Havenau ansetzen. Ihr werdet meinen Report zum Hochlord bringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12702] = { id = 12702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hühnerparty!", description = "Ich wette, Ihr nicht ratet, was schon wieder passiert.\n\nNe, nicht Goregek oder Hühner.\n\nJa, gut, ich lüge. Goregek schon wieder Hühner frei gelassen. Dummer Goregek mit hungrigem Bauch.\n\nLass mich wissen, wenn du brauchst Hilfe von einem der Jäger... sie hier irgendwo in der Nähe.", sourceObjective = "Fangt 12 entflohene Hühner für Ältesten Harkek auf dem Hügel der Wildherzen.", progress = "Hühner normalerweise nicht weit kommen... Wenn Wespen sie nicht essen, vielleicht wir sie einfach das nächste Mal draußen auf Feld lassen.", completion = "Du gut darin.\n\nVielleicht wir eines Tages Goregek einfach in Fluss fallen lassen, damit du das nie wieder machen musst.", sourceObjectiveStatus = "unverified-source-field" }
quests[12703] = { id = 12703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kartaks Wut", description = "Du der große Lichjäger, he? Gut, so starken Wildherzverbündeten in Kampf zu haben. Vielleicht du stark genug, sogar Kartak zu rufen.\n\nGroßer Kampf bei Kartaks Stellung im Südwesten. Geh und töte Funken-Großzungen, bis du kriegst gute Menge von Orakelblut. Bring Blut zu Altar in Kartaks Stellung, um Kartak für schmackhafte Gelage von Großzungen zu rufen.\n\nKartak nimmt deinen Körper, wenn du würdig... Mit Kartaks Kraft du tötest mehr Großzungen als in besten Träumen.\n\nGeh und töte viele, Jäger!", sourceObjective = "Bringt eine reine Probe vom Blut der Orakel zum Altar von Kartak, um Kartak zu beschwören. Mit der Hilfe von Kartaks geteilten Kräften sollt Ihr für Schamanen Jakjek in Kartaks Stellung 50 in der Nähe befindliche, funkenbesprühte Gorlocs töten.", completion = "Ritual ging so leicht für dich!\n\nDu eines Tages kommst zurück für mehr Töten, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[12704] = { id = 12704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besänftigung des großen Regensteins", description = "Seit Mooswandler angegriffen wurden, ich in Sorge, wir vielleicht nicht gut zu Großem Regenstein... wir vielleicht zu gierig. Wir müssen mehr Schätze opfern!\n\nDu letztes Mal gut darin, Glitzers zu finden... vielleicht du suchst um Dorf herum nach mehr Glitzers? Du womöglich brauchst einen von guten Regenrufern zu Hilfe. Sag uns nur, wen.", sourceObjective = "Das Hochorakel Soo-say im Baldachin der Regenrufer möchte, dass Ihr einen Gefährten auswählt und 6 glänzende Kostbarkeiten sammelt.\n\nSprecht noch einmal mit dem Hochorakel Soo-say, um Euch die Hilfe eines Eurer früheren Gefährten zusichern zu lassen.", progress = "Nie genug Glitzers... Großer Regenstein gut zu uns, wir müssen gut sein zu Großer Regenstein.", completion = "So viele gute Glitzers! Du gut darin.\n\nKomm zurück später für mehr, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[12705] = { id = 12705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wille der Titanen", description = "Wauwaumenschen angreifen Funkenbesprühten... wir müssen kämpfen oder sie nur angreifen auch andere Orakel.\n\nDu gut Freund von uns, also wir erlauben dir vielleicht besondere Ehre. Die Großen haben vor langer Zeit hinterlassen Beschützer für Schreine... Er immer noch hier, aber er nicht wissen, etwas falsch, bis Schreine verwüstet.\n\nWauwaumenschen da unten haben böse Kristalle zum Ärgermachen... Bring einen bösen Kristall zu Blitzschrein, damit Soo-holu weiß, dass er helfen.\n\nErschreck nicht, wenn Soo-holu deinen Körper nimmt... er sehr mächtig, also er dich beschützt.", sourceObjective = "Erlangt einen getrübten Kristall von den Wolvar in der Nähe der Zuflucht der Funkenbesprühten und bringt ihn zum großen Blitzstein, um Soo-holu zu beschwören. Tötet mithilfe Soo-holus geteilter Macht 50 in der Nähe befindliche Wolvar der Wildherzen und kehrt anschließend zu Blitzrufer Soo-met in der Nähe des großen Donnersteins zurück.", completion = "Soo-holu stark, hm? Ich sehr froh, dass er zugestimmt, seinen Körper mit dir für Kampf zu teilen.\n\nEr mehr Vertrauen in Leute, die er schon vorher getroffen, also vielleicht komm zurück ein anderes Mal, um mehr zu helfen, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[12706] = { id = 12706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieg an der Todesbresche!", description = "<Prinz Valanar händigt Euch eine versiegelte Schriftrolle aus.>\n\nDies ist der komplette Bericht über Euren Sieg bei der Todesbresche. Bringt ihn zu Hochlord Mograine in Acherus. Ich habe dafür gesorgt, dass in dem Report von Euren Heldentaten die Rede ist. Mograine wird Euch zweifellos für diesen Sieg belohnen, {name}.\n\nNun geht!", sourceObjective = "Liefert Prinz Valanars Bericht bei Hochlord Darion Mograine in Acherus: der Schwarzen Festung ab.", progress = "Ich war mir sicher, dass Ihr es nicht mehr in einem Stück zurückschaffen würdet, {class}. Vielleicht steckt doch mehr in Euch, als ich zuerst vermutet habe.", completion = "<Hochlord Mograine liest sich den Report durch.>\n\nDie gesamte Flotte des Scharlachroten Kreuzzugs?\n\n<Hochlord Mograine nickt.>\n\nSolch Macht, {name}... Solch eine Darbietung von Dominanz habe ich schon seit Jahren nicht mehr gesehen... seit mein Vater...\n\n\n\nEs ist nicht wichtig...\n\nJa: Eure Auszeichnung - bevor ich sie vergesse.", sourceObjectiveStatus = "unverified-source-field" }
quests[12707] = { id = 12707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wollige Gerechtigkeit", description = "Ahunae hat über deine Reise zum Krater Mam'toth gehört, Mann. Die Kinder von Mam'toth sind erzürnt und schreien nach Gerechtigkeit!\n\nFolg der Allee in Richtung Nordosten die Stufen hoch zur nächsten Ebene von Zul'Drak. Zu deiner Rechten wirst du die Überreste des Altars von Mam'toth finden.\n\nHalt' das Medaillon von Mam'toth einem tobenden Mammut vor die Nase, wenn du dort bist. Es wird sich dann für eine Weile beruhigen, was dir die Chance gibt, auf seinen Rücken zu springen.\n\nReite anschließend mit ihm alle Jünger von Mam'toth nieder, die dir über den Weg laufen!", sourceObjective = "Skalpierer Ahunae in Zim'Torga möchte, dass Ihr mithilfe des Medaillons von Mam'toth ein tobendes Mammut beruhigt, um dann auf ihm zu reiten. Anschließend sollt Ihr 12 Jünger von Mam'toth zu Tode trampeln.", completion = "Erster Punkt für die Opfer, Mann!", sourceObjectiveStatus = "unverified-source-field" }
quests[12708] = { id = 12708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzauberte Tikikrieger", description = "Ich weiß, dass Ihr Euch auf dem Weg zur Festung von Zol'Maz gen Nordosten befindet, {class}. Ich möchte, dass Ihr Euch um die Spezialwächter des Kriegsfürsten kümmert, wenn Ihr schon einmal dort seid.\n\nDie verzauberten Tikikrieger, wie sie genannt werden, stellen eine äußerst reelle Gefahr dar. Sollten die Drakkari sie in Massen produzieren, würden wir recht schnell überrannt werden.\n\nNa dann wollen wir ihnen mal zeigen, dass es sich nicht lohnt, die Dinger zu erschaffen.", sourceObjective = "Elementzähmerin Dagoda in Zim'Torga möchte, dass Ihr 12 verzauberte Tikikrieger zerstört.", completion = "Jetzt werden sie es sich wahrscheinlich zweimal überlegen, bevor sie mehr von diesen Dingern herstellen. Mich schaudert der Gedanke daran, wie es sein würde, wenn wir gegen eine ganze Armee dieser Dinger kämpfen müssten.\n\n<Der Elementzähmer scheint, einen Moment lang in Gedanken versunken zu sein.>\n\nIch nehme einmal an, dass es genauso wäre, als würde man gegen die endlosen Wellen der Geißel ankämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12709] = { id = 12709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhexte Behälter", description = "Entschuldigt, {name}, mir scheint, Ihr seid unterwegs nach Nordosten zur Festung Zol'Maz? So eine Reise wäre für uns eine großartige Gelegenheit, unsere Sammlung der Schätze der Drakkari zu vollenden.\n\nIch habe erfahren, dass der Kriegsfürst der Drakkari extrem paranoid ist. Alle seine Behältnisse in der Feste hat er mit schrecklicher Magie verhexen lassen. Es wird gemunkelt, dass die Tikikrieger das Heilmittel haben - aber wer weiß das schon genau?\n\nWenn Ihr Euch die Zeit nehmen würdet, mir ein paar der Behälter zu holen, wäre ich Euch ziemlich dankbar.", sourceObjective = "Chronist To'kini in Zim'Torga möchte, dass Ihr 12 Behälter der Festung Zol'Maz sammelt.", progress = "Kann es sein, dass sich die Behältnisse in Eurem Rucksack befinden?", completion = "Seht Euch das alles nur mal an!\n\nSeht Euch dies an, {name}. Dieses von Euch mitgebrachte Exemplar zeigt es deutlich: Die Drakkari erkannten, dass das Land durch die Anwesenheit der Geißel schwächer wurde.\n\nDer Kriegsfürst fühlte sich dazu gezwungen, die sich dadurch bietende Gelegenheit wahrzunehmen. Er drängte die Propheten dazu, Ihre Götter zu töten, um deren Macht zu beherrschen und die Streitkräfte des Lichkönigs zurückzudrängen.\n\nSie waren so oder so dem Untergang geweiht. Sie waren somit unbewusst für ihre eigene Zerstörung verantwortlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[12710] = { id = 12710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enthüllung", description = "Gute Arbeit, {name}.\n\nDu bist der Beweis, dass ich'n Auge für Talent besitze! Nun siehst du, weshalb mir der Lichkönig seinen Segen gegeb'n hat...\n\nDie Zeit is' gekommen, dir meinen eigentlichen Plan zu enthüllen, Mann.\n\nNun wirst du seh'n, wie wir über die Schwärme der Drakkaritrolle hinwegfegen werd'n, um unseren angestammt'n Platz im großen Palast von Gundrak einzunehmen.\n\nNimm dieses Szepter, Mann. Es is'n Zeichen meines Vertrauens in dir. Es wird dir Zugang zu meinen oberen Gemächern gewähren, damit du selbst Zeuge unserer Geheimwaffen sein kannst.", sourceObjective = "Drakuru in Voltarus möchte, dass Ihr den Teleporter benutzt, der in sein oberes Gemach führt.", progress = "Hast du meine Schöpfungen mit eigenen Augen sehen können, {name}?", completion = "So, da hast du es also, Mann.\n\nWir werden die ultimative Geißelarmee erschaffen und sie wird dem Lichkönig dienen. Er wird äußerst zufrieden sein!\n\nDu kannst das Szepter behalten, {name}. Du wirst es brauchen, um meine Armee in die Schlacht zu führen...\n\nSchon bald!", sourceObjectiveStatus = "unverified-source-field" }
quests[12711] = { id = 12711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herrenlose Post", sourceObjective = "Auf dem Briefkasten liegen einige unleserliche Briefe und Schriftrollen. Nutzlos…\n\nVielleicht solltet Ihr mal hinein schauen?", sourceObjectiveStatus = "unverified-source-field" }
quests[12712] = { id = 12712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlüssel des Kriegslords Zol'Maz", description = "{name}, wir benötigen einen Schlüssel, um die Ketten des Nashorngottes Akali zu lösen. Selbst jetzt, während wir hier noch reden, ist er auf dem Weg zur Schlachtbank.\n\nDer Drakkarikriegslord Zol'Maz trägt den Schlüssel bei sich. Als er von Euren Heldentaten erfuhr, hat er sich mitsamt seiner Familie in sein Bollwerk zurückgezogen; die Stufen hoch gen Nordosten.\n\nDer Kriegslord ist stark und Ihr werdet Hilfe benötigen. Solch Hilfe ließe sich herbeirufen, indem Ihr während des Kampfes vor seinen Toren das Tiki, das Schwert und die Zauberformeln seiner Familienmitglieder miteinander kombiniert.", sourceObjective = "Har'koa in Zim'Torga möchte, dass Ihr den Schlüssel des Kriegslords Zol'Maz beschafft.", progress = "Ich kann nicht genug betonen, wie wichtig es ist, dass wir den Schlüssel des Kriegslords um jeden Preis in die Hände zu bekommen.", completion = "Es wäre vielleicht besser gewesen, wenn ich Euch darum gebeten hätte, ihn direkt nach Gundrak zu bringen anstatt hierher.\n\nIch denke jedoch, dass es am besten ist, wenn Ihr zuerst hört, was ich noch zu sagen habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[12713] = { id = 12713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verrat", description = "Die Zeit ist gekommen, um dieser Scharade ein Ende zu setzen, {name}.\n\nSo wertvoll Eure Informationen auch sein mögen, wir müssen Drakuru erledigen und sein Projekt stoppen, bevor seine verrückten Spießgesellen auf die Welt losgelassen werden.\n\nWir haben Euer Szepter für die Aufgabe modifiziert. Wenn die Zeit reif ist, werdet Ihr es gegen Drakurus Seuchenbluttrolle einsetzen und sie damit gegen ihren eigenen Meister aufhetzen. Es ist Eure einzige Chance, ihn zu vernichten.\n\nKämpft gut.", sourceObjective = "Stefan in der Schwarzen Wacht möchte, dass Ihr Drakuru besiegt.\n\nFalls Ihr Euren bezauberten Halsreif verlieren solltet, dann kehrt zu Stefan in der Schwarzen Wacht zurück und besorgt Euch einen neuen.", progress = "Habt Ihr Euch Drakuru schon gestellt, {name}?", completion = "So, es ist vollbracht.\n\nEs gibt noch immer viel zu tun, doch Dank Euch wird unsere Arbeit hier viel einfacher sein.\n\nBitte, nehmt dies als Zeichen unserer Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[12714] = { id = 12714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wille des Lichkönigs", description = "Es ist der Wille des Lichkönigs, der uns vorantreibt, {name}. Niemand ist sich dessen mehr bewusst, als die Todesritter. Unsere schiere Existenz ist mit seinem Bewusstsein verbunden. Sicherlich habt Ihr ihn zu Euch sprechen hören, habt gespürt, wie er in Eure Gedanken eindringt...\n\nKönnt Ihr ihn jetzt hören? Vielleicht ist es zu früh für Euch.\n\n<Mograine schließt seine Augen und es scheint, als nickte er jemandem zu.>\n\nJawohl, mein Fürst. Es wird vollbracht werden.\n\n{name}, Ihr sollt zur Todesbresche zurückkehren und Euch bei Prinz Valanar melden. Der Lichkönig befiehlt es!", sourceObjective = "Kehrt zur Todesbresche zurück und meldet Euch bei Prinz Valanar.", completion = "Havenau ist unser! Tausend Leichen liegen auf dem Boden verstreut und warten nur auf ihre Wiedergeburt. Jetzt werden wir die Kraft der Geißel auf unseren Feind entfesseln!\n\nDie Ghule haben schon mit ihrem Angriff auf Neu-Avalon begonnen. Unsere Streitkräfte sind ihnen gefolgt und haben die Krypta der Erinnerung eingenommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12715] = { id = 12715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krypta der Erinnerung", description = "Die Angriffe auf die Tore der letzten Bastion des Scharlachroten Kreuzzugs haben begonnen. Unsere Ghule sind dabei, ihre Streitkräfte an den Frontlinien zu zermürben, während wir hart daran arbeiten, die Verteidigung unserer Basis an vorderster Front zu verstärken - damit meine ich die Krypta der Erinnerung.\n\nGeht nach Süden zur Krypta - sie liegt gleich bei Neu-Avalon - und meldet Euch bei meinem verehrten Bruder Prinz Keleseth.\n\nEr wird Euch erwarten.\n\nMacht Euch bereit, {name}, denn Ihr werdet Zeuge der nächsten Stufe unserer Kriegsführung sein: DOMINANZ!\n\nReitet aus, Todesritter!", sourceObjective = "Meldet Euch bei Prinz Keleseth in der Krypta der Erinnerung.", completion = "Seid gegrüßt, {class}. Ich bin Blutfürst Keleseth, Herrscher über die südöstlichen Gebiete Nordends. Der Lichkönig möchte mich und meine Fähigkeiten dazu einsetzen, diesen Sterblichen, dieser Beleidigung in den Augen der Geißel, ein Ende zu setzen. Wie mit allen Dingen, die der Lichkönig von mir verlangt, so werde ich auch jetzt mit Freude gehorchen. Meinen Durst mit einem Meer an endlos vielen Seelen zu stillen, versüßt natürlich die Sache, meint Ihr nicht auch?", sourceObjectiveStatus = "unverified-source-field" }
quests[12716] = { id = 12716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Seuchenfürstens Gesuch", description = "Seht Euch dieses Kürbisbeet an! Merkt Ihr, dass irgendetwas fehlt? Natürlich merkt Ihr das nicht - und wisst Ihr warum? Weil Ihr ein Idiot seid! Euer Gehirn war womöglich das Erste, was gestorben ist.\n\n<Noth seufzt.>\n\nIch wurde dazu beauftragt, einen Seuchenkessel zusammenzustellen, und Ihr werdet mir dabei helfen.\n\nDirekt hinter dem Tor von Neu-Avalon befindet sich das Gasthaus. Dort sollt Ihr mir einen leeren Kessel stehlen. Geht dann anschließend zur Schmiede, die sich auch gleich in der Nähe des Tores befindet, und besorgt mir eine Eisenkette. Bringt das Zeug gemeinsam mit zehn Kreuzfahrerschädeln zu mir. Soll ich Euch auch noch sagen, woher Ihr die Schädel bekommt?", sourceObjective = "Noth der Seuchenfürst möchte, dass Ihr ihm 1 leeren Kessel, 1 Eisenkette und 10 Kreuzfahrerschädel bringt.", progress = "Habt Ihr die Materialien gesammelt, um die ich Euch gebeten habe?", completion = "Perfekt! Nun gebt mir einen Moment lang Zeit, damit ich die Vorbereitungen treffen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[12717] = { id = 12717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noths Spezialgebräu", description = "Der Kessel kann nun seine faule Verderbnis ausspeien und über das Land verbreiten!\n\nNun, Todesritter: Eine kurze Lektion in Sachen Seuchenkessel. Das Gas des Kessels ist für alles Lebendige tödlich, erfüllt die Diener der Geißel jedoch mit Macht. Wie alle Schöpfungen der Geißel ernährt sie sich vom Tod und wird stärker, je länger sie sich nähren kann.\n\nNehmt diese Kreuzfahrerschädel und werft sie in den Kessel. Ihr werdet mit dem Resultat sehr zufrieden sein.", sourceObjective = "Werft den Haufen Kreuzfahrerschädel in den Seuchenkessel.", progress = "Der Kessel rührt sich nicht.", completion = "Der Seuchenkessel fängt an zu rasseln, als Ihr die Schädel hineinwerft.\n\nNach ein paar Sekunden tauchen ein paar Phiolen mit dunkler Flüssigkeit auf der Oberfläche auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[12718] = { id = 12718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Totenschädel fürs Gebräu", progress = "Im Seuchenkessel blubbert und kocht das giftige Gebräu - überall dickes Gas verbreitend.\n\nHabt Ihr noch mehr Kreuzfahrerschädel, die Ihr hineinwerfen könnt?", completion = "Der Seuchenkessel fängt an zu rasseln, als Ihr die Schädel hineinwerft.\n\nNach ein paar Sekunden spürt Ihr die herrliche Wirkung der dunklen und schaumigen Flüssigkeit, auch Noths Spezialgebräu genannt." }
quests[12719] = { id = 12719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es gibt kein Entrinnen", description = "Es wird schon ausreichen, wenn wir sie komplett vernichten, {name}. Und um das zu erreichen, wird es nicht genügen, dass nur ein paar Hundert hirnlose Ghule die Tore von Neu-Avalon angreifen. Wir müssen ins Allerheiligste des Dorfes vordringen und ihre Würdenträger beseitigen. Ihnen muss gezeigt werden, dass niemand der Geißel entkommen kann!\n\nMacht Euch auf den Weg in Richtung Südwesten zum Rathaus von Neu-Avalon und beseitigt den Bürgermeister. Sucht dort auch nach der Registratur von Neu-Avalon und bringt sie mir.", sourceObjective = "Prinz Keleseth in der Krypta der Erinnerung hat Euch befohlen, Bürgermeister Quimby zu töten und die Registratur von Neu-Avalon zu beschaffen.", progress = "Es gibt kein Entrinnen!", completion = "Die Registratur wird uns Vieles über die Insekten des Scharlachroten Kreuzzugs verraten.\n\n<Keleseth blättert durch die Seiten der Registratur.>\n\nTodes- und Geburtsraten, doch was am allerwichtigsten ist: Logistik.\n\nSeht her, {name}, sie haben schon vier Schiffe ausgesandt. Lasst mich sehen... Worauf steuern sie zu?\n\n\n\nWAS? Das ist nicht möglich. Sie segeln nach Nordend!\n\nNeben den Koordinaten steht geschrieben: \"Scharlachroter Morgen.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[12720] = { id = 12720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man Freunde gewinnt und Feinde beeinflusst", description = "Auf meinen Weltreisen habe ich mehrere interessante Entdeckungen gemacht. Habt Ihr zum Beispiel gewusst, dass man einem Mann jede auch noch so verheimlichte Wahrheit entlocken kann, indem man ihn nur richtig dazu ermutigt? Wie es das Glück so will, habe ich ein wenig \"Ermutigung\" zur Hand.\n\n<Keleseth nimmt etwas aus einer juwelenbesetzten Schatulle.>\n\nDies ist mein \"Überzeuger\", wie ich ihn nenne. Legt ihn an und zieht aufs Feld hinaus, Todesritter. Richtet das spitze Ende auf die Soldaten von Neu-Avalon. Findet die Wahrheit über den \"Scharlachroten Morgen\" heraus.", sourceObjective = "Prinz Keleseth in der Krypta der Erinnerung hat Euch befohlen, die Wahrheit über den \"Scharlachroten Morgen\" herauszufinden.\n\nNehmt Keleseths Überzeuger aus der juwelenbesetzten Schatulle und bringt damit einen Scharlachroten Kreuzzügler zum Reden.", progress = "Wendet den Überzeuger auf einen Scharlachroten Kreuzfahrer an. Einer von ihnen wird letztendlich... brechen - äh, ich meine: aufgeben.", completion = "Ein Erwachen? Was für einen Unsinn redet Ihr da! Was für ein Idiot würde sein Volk schon mitten in die gefrorenen Weiten führen? Womöglich wird dieser Kurier jedoch die Antwort haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12721] = { id = 12721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Randale", description = "{name}, wir haben keine Zeit mehr. Ihr müsst den Schlüssel nehmen und Akali befreien.\n\nEr wird im Hof vor Gundrak, der Hauptstadt von Zul'Drak, gefangen gehalten. Akalis Ketten sind an vier Verankerungen befestigt. Um den Rhinozerosgott zu befreien, müsst Ihr jede einzelne von ihnen aufschließen.\n\nIn Gundrak wimmelt es nur so von Eistrollen. Ich glaube jedoch, dass Ihr mit der nötigen Vorsicht ohne große Gefahr hineinschleichen könnt.\n\nInformiert bitte den Hexendoktor, sobald Ihr die Sache erledigt habt.", sourceObjective = "Har'koa in Zim'Torga möchte, dass Ihr Akali befreit und danach Hexendoktor Khufu in Zim'Torga benachrichtigt.", completion = "Nein!\n\nSchon wieder wurde ein Gott vernichtet und seine Kräfte gestohlen. Und nun hat uns der Prophet von Akali direkt bedroht.\n\nWenn er kommt, dann wegen Har'koa. Wir können nicht zulassen, dass er auch noch ihre Kraft an sich reißt.\n\nEinmal mehr müssen wir die Götter um Rat bitten, {name}. Sie werden uns sagen, was getan werden muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[12722] = { id = 12722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie Lämmer zur Schlachtbank", description = "Die meisten Menschen wären geflohen, sobald eine Nekropole der Geißel über ihren Köpfen erschienen wäre. Doch nicht so der Scharlachrote Kreuzzug!\n\nIch muss zugeben, dass ich unseren Austausch mit dem Kreuzzug doch recht genieße. Im Laufe der Jahre haben Schlachten zwischen ihnen und der Geißel zu einigen der tragischsten Ereignisse in der Geschichte der Menschheit geführt. Und trotzdem stehen wir hier - SCHON WIEDER - und kämpfen gegen sie!\n\nWir sollen ihnen nicht die Freuden der ewigen Knechtschaft unter der Herrschaft des Lichkönigs verwehren! Geht nach Neu-Avalon und erfüllt ihren Todeswunsch. Lasst niemanden am Leben.", sourceObjective = "Baron Totenschwur in der Krypta der Erinnerung hat Euch befohlen, 10 Soldaten des Scharlachroten Kreuzzugs und 15 Bürger von Neu-Avalon zu erschlagen.", completion = "Ihr seid ziemlich effektiv mit der Klinge, {name}. Vielleicht - mit des Lichkönigs Erlaubnis, versteht sich - wärt Ihr dazu geneigt, einer meiner Diener zu werden? Stratholme sucht nach einem neuen Bürgermeister.", sourceObjectiveStatus = "unverified-source-field" }
quests[12723] = { id = 12723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter den Linien der Scharlachroten", description = "Ich habe Orbaz, Thassarian und Koltira ausgesandt, um hinter feindlichen Linien nach dem Kurier zu suchen. Sie haben die Scharlachrote Taverne ganz im Süden von Neu-Avalon zu ihrer Operationsbasis gemacht. Sie liegt hinter den zwei Obstgärten versteckt, neben der Kapelle der Scharlachroten Flamme. Ihr sollt bis zur Taverne vordringen und Euch bei Orbaz Blutbann melden. Er wird Euch über ihre derzeitige Lage aufklären.", sourceObjective = "Meldet Euch bei Orbaz Blutbann in der Scharlachroten Taverne in Neu-Avalon.", completion = "Sieht so aus, als würden wir heutzutage jedem Einlass in den Dunklen Orden gewähren. Als mir das Geschenk zuteil wurde, war es anders - sehr anders!\n\nWas diesen Kurier angeht...", sourceObjectiveStatus = "unverified-source-field" }
quests[12724] = { id = 12724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des gerechten Kreuzfahrers", description = "Wir haben nicht den geringsten Hinweis darüber, wann und wo dieser Kurier erscheinen soll. Diese Menschen wussten auch nichts.\n\n<Orbaz deutet auf die Leichen des Scharlachroten Kreuzzugs, die über den Boden verteilt liegen.>\n\nAus dem letzten konnte ich noch etwas Nützliches herausprügeln. Im Inneren der Scharlachroten Festung befindet sich ein Plan, auf dem all ihre Patrouillen eingezeichnet sind. Ich möchte, dass Ihr in die Festung einbrecht und ihn stehlt.\n\nDie Wacht ist das größte Gebäude in Neu-Avalon nordöstlich von hier.", sourceObjective = "Orbaz Blutbann in der Scharlachroten Taverne in Neu-Avalon hat Euch befohlen, die Patrouillenaufstellung von Neu-Avalon aus der Scharlachroten Festung zu stehlen.", progress = "Durchsucht alle Fugen und Ecken dieser Wacht! Der Plan ist dort!", completion = "<Orbaz blättert durch die Seiten des Plans.>\n\nDiese nutzlosen Scheusale sind geschäftig gewesen! Patrouillen im Norden, Süden, Westen und Osten, doch kein Wort über ihre Kurierwege. Wartet. Was ist das? Es sieht so aus, als gäbe es eine Patrouille, die von den westlichen Pestländern ausgeht. Und sie wird heute genau hier vorbeikommen! Ich brauche etwas Zeit zum planen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12725] = { id = 12725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Tode vereint", description = "Durch die Linien des Scharlachroten Kreuzzugs zu brechen, war keine einfache Aufgabe. Wir mussten während des Angriffs hohe Verluste hinnehmen und verloren einen unserer besten Todesritter: Koltira Todesweber. Ich weiß nicht, ob er tot oder am Leben ist, doch ich soll verdammt sein, wenn wir nicht nach ihm suchen würden.\n\nAls ich ihn das letzte Mal sah, war er in Ketten gelegt und wurde zur Scharlachroten Festung nordöstlich von hier verschleppt. Durchsucht jeden Winkel dieser Festung, Todesritter. Findet Koltira!", sourceObjective = "Sucht nach Koltira Todesweber in der Scharlachroten Festung.", completion = "Es war töricht, mir zu folgen. Ich habe versagt. Sie hätten mich sterben lassen sollen - nun werden womöglich zwei von uns getötet werden.\n\n<Koltira schüttelt den Kopf.>\n\nWir sind {class} der Geißel - das ist dem Bündnis der dunklen Bruderschaft ein Dorn im Auge.\n\nThassarian, du verdammter Trottel!", sourceObjectiveStatus = "unverified-source-field" }
quests[12726] = { id = 12726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lied von Wind und Wasser", description = "Du Sturm zugehört, ja? Das Sturmherrenschelf hallt mit uralten Liedern... das Lied von Wind und Wasser.\n\nDer große Sturm verschlingt die Söhne des Taifuns und des Unwetters. Hier, nimm diese Trommel und spiel sein Lied... Haifuns Lied.\n\nHilf ihm, Wind und Wasser aufzusaugen, damit Sturm weitermachen kann.", sourceObjective = "Soo-nee möchte, dass Ihr die Trommeln des Sturms auf dem Sturmherrenschelf verwendet und Haifun dabei helft, 3 Sturmwiedergänger und 3 Aqueousgeister zu verschlingen.", completion = "Ich danke dir, {name}. Dank dir wird uns der große Sturm freundlich gesonnen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[12727] = { id = 12727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutiger Ausbruch", description = "Der Alarm wurde geläutet. Der Hochinquisitor und seine Akolyten werden bald hier sein. Ich bin zu schwer verwundet, um von irgendwelchem Nutzen sein zu können, werde jedoch so gut wie möglich helfen.\n\nErschlagt den Hochinquisitor und seine Spießgesellen. Reißt ihm den Kopf ab und bringt ihn Thassarian. Rache wird seine barbarische Seele besänftigen.\n\nUnd noch etwas, {name}: Falls Ihr überleben und zurück zu Thassarian gelangen solltet, dann sagt ihm, dass sie in der Kapelle Gefangene hinrichten. Womöglich wird er Euch dann dorthin schicken, damit Ihr einmal mehr den Helden spielen könnt.", sourceObjective = "Erschlagt Hochinquisitor Valroth und bringt Valroths Kopf zu Thassarian in der Scharlachroten Taverne in Neu-Avalon.", progress = "Was ist mit Koltira?", completion = "Ich werde den Kopf dieses Monsters an die Ghule verfüttern!\n\n<Thassarian wirft den Kopf ins Hinterzimmer.>\n\nHat es Koltira wieder herausgeschafft?\n\n<Thassarian hält inne.>\n\nIch bin mir sicher, dass er's geschafft hat. Diese Mauern können ihn nicht lange halten.\n\nZeit, Rache zu nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12728] = { id = 12728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klamm beobachten: Höhlen der Winterflossen", description = "Ich muss meine Notizen zusammentragen und eine Präsentation für meine Kollegen in Dalaran vorbereiten.\n\nWährend ich das mache, muss ich Euch darum bitten, den Höhlen der Winterflossen im Norden einen Besuch abzustatten. Dort müsst Ihr Euch in den Eingang der Höhle stellen und das Arkanometer benutzen.\n\nKehrt umgehend zu mir zurück, sobald Ihr die Daten gesammelt habt. Ohne sie würde mein Material unvollständig sein.", sourceObjective = "Bibliothekar Garren vom Bernsteinflöz möchte, dass Ihr zu den Höhlen der Winterflossen geht und dort das Arkanometer benutzt.", completion = "Ausgezeichnet, jetzt ist mein Bericht komplett.\n\nIch werde den Rat auf jeden Fall von Eurer Gefälligkeit wissen lassen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12729] = { id = 12729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Götter haben gesprochen", description = "Die Götter haben gesprochen und wir müssen uns ihrer Weisheit beugen.\n\nGeht in den Norden nach Zim'Rhuk und vernichtet dort Wächter, bis sie Euch das unbefleckte Herz abtreten. Reist in den Osten zum Altar von Quetz'lun und bringt Unfrieden unter die Altarbehüter, bis Ihr ihre stürmische Essenz bergen könnt.\n\nBringt beides zu Har'koa und sie wird sie zu etwas zusammenfügen, das den verblichenen Akalipropheten zwingen wird, zu erscheinen.", sourceObjective = "Bringt das unbefleckte Herz des Wächters und die stürmische Essenz des Behüters zu Har'koa in Zim'Torga.", progress = "Habt Ihr, was benötigt wird, {name}?", completion = "Euer Heldenmut scheint grenzenlos, {name}.\n\nBitte gebt mir das Herz und die Essenz und ich werde sie in etwas verwandeln, das den Propheten zwingen wird, vor Euch zu erscheinen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12730] = { id = 12730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschwörung bei Zol'Heb", description = "Ihr müsst dieses Beschwörungsjuwel nach Zol'heb gleich südlich von Gundrak bringen.\n\nDort befindet sich ein Kreis der Macht. Benutzt dieses Juwel und zwingt damit den Propheten von Akali zu erscheinen.\n\nMein Herz ist mit Euch, {name}. Gemeinsam haben wir schon viel durchgestanden und Ihr habt alles getan, was in Eurer Macht steht, um nicht nur mein Leben zu retten, sondern auch das der anderen Götter, die von den Drakkari vernichtet wurden.\n\nDoch ich fürchte, dass wir uns in diesem Leben nicht mehr wiedersehen werden.", sourceObjective = "Har'koa in Zim'Torga möchte, dass Ihr den Propheten von Akali tötet.", progress = "Das Einzige, was ich Euch anbieten kann, sind die Wärme meiner Worte und den damit verbundenen Herzenstrost.\n\nLasst Euch so viel Zeit wie nötig, um all Euren Mut zusammenzunehmen und bereit zu sein; doch ich flehe Euch an: Lasst Euch nicht zu lange Zeit oder der Prophet wird über uns kommen.", completion = "Ihr habt es geschafft! {name}, Ihr seid der Held von Zul'Drak!\n\nWir stehen in Eurer Schuld und werden diese doch nie begleichen können. Die Zandalari haben mir jedoch eine Reihe von Objekten anvertraut und meinen, dass sie Euch womöglich interessieren könnten.\n\nBitte, ich möchte, dass Euch dies gehört - ein Zeichen unserer Dankbarkeit - doch beeilt Euch. Ich spüre, dass es noch eine weitere wichtige Angelegenheit gibt!", sourceObjectiveStatus = "unverified-source-field" }
quests[12732] = { id = 12732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Herzbluts Stärke", description = "Eines Tages Rejek mächtiger Krieger. Blut und Himmelsfeuer Rejek stark machen werden. Du bald siehst.\n\nRejek gibt dir Phiole, bringe sie zur obersten Spitze der Sonnenstrahlsäule, weit im Westen. Fülle Wasser in Phiole.\n\nDann du gehst nach Norden zu Grenze von Becken, zu Felsvorsprung nördlich von Knochenfelder. Du findest und tötest Blutklauenmatriarchin. Nimm Herzblut.\n\nDu mischt Herzblut und Wasser und bringst zu Rejek. Rejek trinkt, macht stark.", sourceObjective = "Bringt eine Phiole voll Sonnenstrahlherzblut zu Rejek auf dem Hügel der Wildherzen.", progress = "Du bringst Rejek Geschenk?", completion = "Rejek dankt dir. Rejek trinkt, wird stark, nie vergisst mächtiges Geschenk von {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12733] = { id = 12733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herausforderung des Todes", description = "Sie wurde ins Leben gerufen, als der Lichkönig auf den gefrorenen Weiten den Sieg über Illidan Sturmgrimm errang: Die Herausforderung des Todes ist ein Übergangsritus, den alle Todesritter über sich ergehen lassen müssen.\n\nSucht andere Todesritter von Acherus auf und fordert sie zu einem Duell heraus. Sie sind dazu verpflichtet, die Herausforderung zu akzeptieren und so lange zu kämpfen, bis ein Sieger hervortritt!\n\nGeht nun, {name}! Sieg der Geißel! Ehre dem Lichkönig!", sourceObjective = "Olrun die Schlachtenruferin hat Euch befohlen, 5 Duelle mit anderen Todesrittern zu gewinnen.\n\nIhr könnt gegen Initianden der Todesritter oder gegen Spieler kämpfen.", progress = "Habt Ihr die Herausforderung des Todes abgeschlossen?", completion = "Dem Sieger gehört der Ruhm, {class}! Gut gemacht! Die Gunst des Lichkönigs ist Euch an diesem Tage sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[12734] = { id = 12734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rejek: Erstes Blut", description = "Rejek gerade jüngster Krieger in ganzem Stamm der Wildherzen geworden. Vater gab Rejek ein mächtiges Schwert, um Feinde der Wildherzen zu besiegen, aber alter Brauch sagt, Schwert muss erst Blut schmecken. Alter Krieger normalerweise das macht. Du Rejek diese Ehre machen?\n\nNimm Klinge, steche in Leichen aller Wildherzenfeinde: Wespen und Hartknöchel im Südwesten und Großzungen. Vielleicht Klinge in Blut von Nebelflüsterern tauchen, weit im Nordwesten bei Bittertidensee.", sourceObjective = "Taucht Rejeks Klinge in das Blut der Leichen von einer saphirblauen Schwarmwespe, einem Hartknöchelstürmer und 3 Mitgliedern des Stamms der Nebelflüsterer - es können entweder Orakel der Nebelflüsterer oder Krieger der Nebelflüsterer sein. Kehrt zu Rejek auf dem Hügel der Wildherzen zurück, sobald die Aufgabe abgeschlossen ist.", progress = "Du Rejeks Klinge in Blut gebadet?", completion = "Rejek sieht Blutspuren seiner Feinde auf der Klinge. Nun hat Rejek mächtige Waffe für mächtigen Krieger, der er wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[12735] = { id = 12735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein reinigendes Lied", description = "Erde in Sholazar ist sauber. Die Säulen haben das Land Jahrhunderte lang beschützt.\n\nWasser, nicht so sauber, kommt von draußen... von Meeren, von Seen, von Flüssen. Wasser bringt manchmal böse Geister mit - muss gesäubert werden.\n\nNimm dieses Glockenspiel und spiele am Bittertidensee, am Tausendwinterfluss und am Flussnabel. Das macht böse Geister wütend... und dann musst du sie töten.", sourceObjective = "Soo-nee beim Baldachin der Regenrufer will, dass Ihr am Bittertidensee, am Tausendwinterfluss und am Flussnabel das läuternde Glockenspiel erklingen lasst und die bösen Geister tötet, die das Wasser dort verschmutzen.", completion = "Wasser... gesäubert. Ja. Alles gut.\n\nDu verstehst uns, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12736] = { id = 12736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lied der Besinnung", description = "Natürlich du nicht so schlau wie ein Gorloc! Du nur {race}.\n\nDu aber nicht hoffnungslos! Du zeigst, du kannst lernen. Vielleicht Kristalle machen dich schlau, wie Kristalle uns machen schlau!\n\nIch dich lehren Lied spielen, um Geist zu reinigen. Du spielst Lied bei Kristallen, dann Kristalle machen deinen Geist besser... nicht so gut wie den von Gorlocs, aber besser als jetzt. Lebensblutsäule kaputt, aber andere Säulen immer noch gut!", sourceObjective = "Soo-nee im Baldachin der Regenrufer möchte, dass Ihr das Didgeridoo des Nachsinnens auf der Spitze der Schimmersäule, der Sonnenstrahlsäule, der Mooslichtsäule und der Himmelszeltsäule verwendet.", completion = "Du sehen? Ich kann dir sagen, schon schlauer geworden. Und wenn nicht schlauer... dann... glücklicher!", sourceObjectiveStatus = "unverified-source-field" }
quests[12737] = { id = 12737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lied der Fruchtbarkeit", description = "Ein Sturm ist ein zerstörerisches Kraft. Sturm verbrennt Bäume. Sturm überflutet Häuser.\n\nDoch Sturm kann auch Leben spenden, wenn man kennt richtiges Lied. Bei Sturmherrenschelf über Hort der Schöpfer gibt es klein Dreckhügel. Die sehr fruchtbar - darin starke Samen. Warten nur auf richtiges Lied.\n\nDu nehmen dies Horn und spielen Lied für Samen.", sourceObjective = "Soo-nee beim Baldachin der Regenrufer möchte, dass Ihr zum Sturmherrenschelf nordwestlich des Horts der Schöpfer geht und das Horn der Fruchtbarkeit neben 8 Hügeln durchtränkten Mutterbodens blast.", completion = "Du lernen schnell, {name}. Du Lied gut gelernt. Vielleicht ich zeigen anderes Lied nächstes Mal.", sourceObjectiveStatus = "unverified-source-field" }
quests[12738] = { id = 12738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrei nach Rache!", description = "Der Schrei nach Rache darf nicht zu überhören sein, {name}. Kommandant Seuchenfaust hat sich mit einer Kompanie von Todesrittern auf den Weg gemacht, um die Kapelle der Scharlachroten Flamme dem Erdboden gleichzumachen. Falls dort irgendwelche Todesritter gefangen sein sollten, dann wird Seuchenfaust sie da rausbringen.\n\nIhr könnt sie noch immer einholen, wenn Ihr Euch beeilt. Die Kapelle befindet sich westlich von hier.", sourceObjective = "Meldet Euch bei Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme.", completion = "Sie bestehen auch nur aus Fleisch und Knochen - der Geißel also nicht gewachsen.\n\nWir haben zwar keinen unserer Brüder gefunden, sind jedoch über etwas Besonderes gestolpert.", sourceObjectiveStatus = "unverified-source-field" }
quests[12739] = { id = 12739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine besondere Überraschung", description = "Wir kamen hierher, nahmen den Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, {name}. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Insbesondere gibt es da drinnen einen recht angriffslustigen Tauren, an dessen Hinrichtung Ihr besonderen Gefallen finden solltet.", sourceObjective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Malar Tapferhorn hinzurichten - einen gefangenen Anhänger der Argentumdämmerung im Gefängnis in der Nähe.", completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, {name}. Ihr seid ein Diener der Geißel, einer von uns - für immer...", sourceObjectiveStatus = "unverified-source-field" }
quests[12740] = { id = 12740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallschirme für den Argentumkreuzzug", description = "Diese Himmelsschrecken töten meine Leute! In den Tod zu stürzen, ist eine schreckliche Art zu sterben.\n\n{class}, Ihr müsst diese Fallschirme hinaus zu ihnen aufs Feld bringen! Zumindest haben sie dann eine Überlebenschance.", sourceObjective = "Kommandant Falstaav in der Argentumwache möchte, dass Ihr 10 Argentumkreuzfahrer oder Argentumschildmänner draußen auf dem Hof mit Fallschirmen versorgt.", completion = "Ihr seid ein guter Mann, {name}. Wir können uns glücklich schätzen, dass Ihr zufällig vorbeigekommen seid.\n\nBleibt doch ein Weilchen. Ich bin mir sicher, dass es hier vieles zu tun gibt, bei dem ein fähiger {class} wie Ihr helfen könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[12741] = { id = 12741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stärke des Sturms", description = "Dumme Großzungen denken, Singen zu Wolken ihnen Macht gibt. Rejek zeigt Großzungen, wie man Macht kriegt - durch Nehmen!\n\nWeit im Nordwesten liegt großes, flaches Gebiet, das Großzungen \"Sturmherrenschelf\" nennen. Rejek ist sicher, man kann dort nur hinkommen, wenn fliegen wie ein Vogel.\n\nAuf diesem Schelf hat Rejek von mächtigen Kräften von Wind und Wasser gehört. Töte sie für ihre Bosheit und bringe dann zum \"Sturmschrein\" von Großzungen an der Westseite des Schelfs. Rejek wird warten, bis du mit ultimativer Macht zurückkommen.", sourceObjective = "Sammelt 3 Essenzen des Monsuns und 3 Essenzen des Sturms ein und bringt sie zum Sturmschrein. Kehrt mit der wahren Macht des Sturms zu Rejek auf dem Hügel der Wildherzen zurück.", progress = "Du bringst Rejekwahre Macht des Sturms?", completion = "Nun Rejek zeigt feigen Großzungen, wie man Elemente wirklich benutzt!", sourceObjectiveStatus = "unverified-source-field" }
quests[12742] = { id = 12742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine besondere Überraschung", description = "Wir kamen hierher, nahmen den Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, {name}. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Insbesondere gibt es da drinnen einen recht angriffslustigen Menschen, an dessen Hinrichtung Ihr besonderen Gefallen finden solltet.", sourceObjective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Ellen Stanbrück hinzurichten - eine gefangene Anhängerin der Argentumdämmerung im Gefängnis in der Nähe.", completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, {name}. Ihr seid ein Diener der Geißel, einer von uns - für immer...", sourceObjectiveStatus = "unverified-source-field" }
quests[12743] = { id = 12743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine besondere Überraschung", description = "Wir kamen hierher, nahmen den Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, {name}. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Insbesondere gibt es da drinnen eine recht angriffslustige Nachtelfe, an deren Hinrichtung Ihr besonderen Gefallen finden solltet.", sourceObjective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Yazmina Eichendorn hinzurichten - eine gefangene Anhängerin der Argentumdämmerung im Gefängnis in der Nähe.", completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, {name}. Ihr seid ein Diener der Geißel, einer von uns - für immer...", sourceObjectiveStatus = "unverified-source-field" }
quests[12744] = { id = 12744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine besondere Überraschung", description = "Wir kamen hierher, nahmen diesen Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, {name}. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Insbesondere gibt es da drinnen einen recht angriffslustigen Zwergen, an dessen Hinrichtung Ihr besonderen Gefallen finden solltet.", sourceObjective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Donovan Dulfrost hinzurichten - einen gefangenen Anhänger der Argentumdämmerung im Gefängnis in der Nähe.", completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, {name}. Ihr seid ein Diener der Geißel, einer von uns - für immer...", sourceObjectiveStatus = "unverified-source-field" }
quests[12745] = { id = 12745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine besondere Überraschung", description = "Wir kamen hierher, nahmen den Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, {name}. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Insbesondere gibt es da drinnen einen recht angriffslustigen Gnom, an dessen Hinrichtung Ihr besonderen Gefallen finden solltet.", sourceObjective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Goby Blastenheimer hinzurichten - einen gefangenen Anhänger der Argentumdämmerung im Gefängnis in der Nähe.", completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, {name}. Ihr seid ein Diener der Geißel, einer von uns - für immer...", sourceObjectiveStatus = "unverified-source-field" }
quests[12746] = { id = 12746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine besondere Überraschung", description = "Wir kamen hier an, nahmen diesen Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, {name}. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Vor allem gibt es dort drinnen einen recht angriffslustigen Draenei, an dessen Hinrichtung Ihr besonderen Gefallen finden werdet, wie ich meine.", sourceObjective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Valok den Gerechten hinzurichten - einen gefangenen Anhänger der Argentumdämmerung im Gefängnis in der Nähe.", progress = "Wie fühlt es sich an?", completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, {name}. Ihr seid ein Diener der Geißel, einer von uns; für immer...", sourceObjectiveStatus = "unverified-source-field" }
quests[12747] = { id = 12747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine besondere Überraschung", description = "Wir kamen hier an, nahmen diesen Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, {name}. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Insbesondere gibt es da drinnen eine recht angriffslustige Blutelfe, an deren Hinrichtung Ihr besonderen Gefallen finden werdet, wie ich meine.", sourceObjective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Lady Eonys hinzurichten - eine gefangene Anhängerin der Argentumdämmerung im Gefängnis in der Nähe.", completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, {name}. Ihr seid ein Diener der Geißel, einer von uns; für immer...", sourceObjectiveStatus = "unverified-source-field" }
quests[12748] = { id = 12748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine besondere Überraschung", description = "Wir kamen hier an, nahmen diesen Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, {name}. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Insbesondere gibt es da drinnen einen recht angriffslustigen Orc, an dessen Hinrichtung Ihr besonderen Gefallen finden werdet, wie ich meine.", sourceObjective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Kug Eisenkiefer hinzurichten - einen gefangenen Anhänger der Argentumdämmerung im Gefängnis in der Nähe.", progress = "Wie fühlt es sich an?", completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, {name}. Ihr seid ein Diener der Geißel, einer von uns; für immer...", sourceObjectiveStatus = "unverified-source-field" }
quests[12749] = { id = 12749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine besondere Überraschung", description = "Wir kamen hierher, nahmen den Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, {name}. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Insbesondere gibt es da drinnen einen recht angriffslustiger Troll, an dessen Hinrichtung Ihr besonderen Gefallen finden solltet.", sourceObjective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Iggy Dunkelhauer hinzurichten - einen gefangenen Anhänger der Argentumdämmerung im Gefängnis in der Nähe.", completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, {name}. Ihr seid ein Diener der Geißel, einer von uns - für immer...", sourceObjectiveStatus = "unverified-source-field" }
quests[12750] = { id = 12750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine besondere Überraschung", description = "Wir kamen hier an, nahmen diesen Ort auseinander und gingen in Richtung Gefängnis. Wir hatten nicht erwartet, was wir dort vorfanden, {name}. Scheint, als wäre der Kreuzzug sehr beschäftigt gewesen. Das Gefängnis ist voller gefangener Anhänger der Argentumdämmerung. Die meisten von ihnen waren schon tot, als wir ankamen, doch ein paar atmeten noch.\n\nIch wollte schon hineingehen und den Rest von ihnen hinrichten, doch ich denke, dass Ihr die Ehre haben solltet. Insbesondere gibt es da drinnen einen recht angriffslustigen Diener der Verlassenen, an dessen Hinrichtung Ihr besonderen Gefallen finden werdet, wie ich meine.", sourceObjective = "Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Antoine Brack hinzurichten - einen gefangenen Anhänger der Argentumdämmerung im Gefängnis in der Nähe.", completion = "Fühlt sich gut an, was meint Ihr? Ihr seid nicht mehr einer von ihnen, {name}. Ihr seid ein Diener der Geißel, einer von uns; für immer...", sourceObjectiveStatus = "unverified-source-field" }
quests[12751] = { id = 12751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So etwas wie Heimkehr", description = "Kehrt zu Thassarian in der Scharlachroten Taverne zurück und lasst ihn wissen, dass Koltiras Schrei nach Rache erhört wurde. Die Kapelle der Scharlachroten Flamme wird in weniger als ein paar Stunden nur noch ein Haufen Asche sein.\n\nIhr seid ein kaltblütiges Monster, {name}. Ich verneige mich vor Euch, <Bruder/Schwester>.", sourceObjective = "Überbringt Thassarian in der Scharlachroten Taverne in Neu-Avalon die Nachricht Eures Sieges.", completion = "Wieder ein Sieg für die Geißel! Für diese Hunde, diese Scharlachroten, gibt es kein Entrinnen mehr. Jetzt ist es nur noch eine Frage der Zeit...", sourceObjectiveStatus = "unverified-source-field" }
quests[12752] = { id = 12752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifelte Forschung", description = "{name}, der Lichkönig macht uns mit einer Invasion zu schaffen. Um ihn zu seinem Frostthron zurückzudrängen, müssen Horde und Allianz wie Pech und Schwefel zusammenhalten. Doch nun musste diese Allianz auf der Terrasse des Lichts in Shattrath einen Schlag hinnehmen.\n\nGeht zum neuen Apothekerlager dort und sprecht mit Großapotheker Putress, um unseren Kampf gegen den Lichkönig zu unterstützen. Er forscht wie verzweifelt an einem Heilmittel, das die Zombieseuche beseitigen wird. Dieses Mittel ist unsere Erlösung.\n\nMacht schnell, {name}. Mit jeder Sekunde, die vergeht, findet ein weiteres unschuldiges Leben sein Ende.", sourceObjective = "Sprecht mit Großapotheker Putress im neuen Apothekerlager auf der Terrasse des Lichts in Shattrath.", completion = "Grüße, Bruder. Ihr möget zwar im Namen der Argentumdämmerung geschickt worden sein, doch das ist nicht der Grund, weshalb Ihr hier seid... Ihr seid hier, um Eurem Volk den Respekt zu verschaffen, den wir uns so redlich verdient haben. Alle Verlassenen würden zustimmen, wenn ich sage: der Zweck heiligt die Mittel. Und unsere Forschungen für das Heilmittel der Zombieseuche sind genau dieses Sprichwort in die Tat umgesetzt...", sourceObjectiveStatus = "unverified-source-field" }
quests[12753] = { id = 12753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verzweifelte Allianz", description = "<Guter/Gute> {name}, der Lichkönig macht uns, der Horde und der Allianz, mit Krankheiten und einer Invasion zu schaffen. Nur indem wir unsere Stärke vereinen, können wir, die zwei großen Kulturen Azeroths, seinem Angriff standhalten und überleben.\n\nAuf der Terrasse des Lichts in Shattrath hat diese Allianz schon einen Schlag hinnehmen müssen. Um unseren Kampf gegen den Lichkönig zu unterstützen, müsst Ihr zu unserem neuen Allianzlager auf der Terrasse des Lichts gehen und dort mit Bischöfin Lazaril sprechen.\n\nDas Licht sei mit Euch, {name}.", sourceObjective = "Sprecht mit Bischöfin Lazaril im neuen Allianzlager auf der Terrasse des Lichts in Shattrath.", completion = "Bruder {race}, ich bin stolz, in diesen Zeiten der Not an Eurer Seite stehen zu dürfen. Seid gesegnet und möge die Allianz zwischen Zwergen und Menschen eintausend Jahre lang währen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12754] = { id = 12754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überfall am Rundblick", description = "Während Ihr damit beschäftigt wart, Kirchen niederzubrennen und Ungeziefer zu beseitigen, habe ich mich an die Ausarbeitung eines Plans gemacht.\n\nDer Scharlachrote Kurier wird den Scharlachroten Rundblick innerhalb der nächsten Stunde passieren. Die Straßen dort sind recht ungeschützt und wimmeln nur so von Kreuzfahrern. Werft diese provisorische Tarnung über, wenn Ihr dort angekommen seid, und wartet, bis der Kurier vorbeikommt. Schlagt mit all Eurer Wildheit zu, sobald er in Eurer Reichweite ist! Macht ihn nieder und nehmt sein Hab und Gut mitsamt seinen Kleidern!\n\nDer Rundblick ist 200 Meter östlich von hier.", sourceObjective = "Orbaz Blutbann in der Scharlachroten Taverne in Neu-Avalon hat Euch befohlen, den Scharlachroten Kurier zu töten und seine Sachen und die Nachricht zu beschaffen.", progress = "Wenn Ihr diesen Kurier verpasst, werde ich gezwungen sein, Euch zu töten. Mit \"gezwungen\" meine ich, dass ich großen Gefallen daran finden werde, Euer Leben auszulöschen.\n\nBEEILT EUCH!", completion = "<Orbaz liest sich die Nachricht durch.>\n\nDie Armeen von Herdweiler und Tirisfal werden direkt in ein Massaker laufen.\n\n<Orbaz grinst.>\n\nNun zum zweiten Teil des Plans. Ihr werdet diese Nachricht höchstpersönlich an Hochgeneral Abbendis übergeben - dafür sind die Kleider gedacht...", sourceObjectiveStatus = "unverified-source-field" }
quests[12755] = { id = 12755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begegnung mit dem Schicksal", description = "Diese Nachricht muss Abbendis erreichen. Wir wollen nicht ihren Verdacht auf uns ziehen. Sie müssen weiterhin davon ausgehen, dass alles für sie nach Plan verläuft.\n\nIhr werdet die Kleider des Scharlachroten Kuriers anlegen und mit der Hilfe von ein wenig dunkler Magie seine Gestalt annehmen.\n\nAbbendis befindet sich im Königshafen südlich des Scharlachroten Rundblicks. Erzählt ihr die Neuigkeiten und bekommt so viel Informationen wie möglich aus ihr heraus. Sie wird uns sagen können, was es über den \"Scharlachroten Morgen\" zu wissen gibt.", sourceObjective = "Orbaz Blutbann hat Euch befohlen, die Nachricht des Scharlachroten Kuriers bei Hochgeneral Abbendis im Königshafen abzuliefern.", progress = "Wo seid Ihr gewesen? Ihr seid zwei Stunden zu spät. Wir waren gerade dabei, einen Kurier zum Hochkommandanten zu schicken.", completion = "<Hochgeneral Abbendis liest sich die Nachricht durch.>\n\nVerdammt! Die Armeen von Herdweiler und Tirisfal dürfen Neu-Avalon nicht erreichen! Die Geißel wird sie alle töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12756] = { id = 12756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Scharlachrote Ansturm tritt hervor", description = "Hört gut zu, Kurier. Die Lande des Scharlachroten Kreuzzugs sind verloren. Neu-Avalon und Havenau wurden von der Geißel überrannt. Die Fratze des Todes ist über uns gekommen und droht damit, uns jeden Augenblick in seine Gewalt zu bringen.\n\nKehrt mit dieser Nachricht zu Galvar zurück:\n\n\"Lasst Eure Armeen umdrehen und bereitet Eure Schiffe darauf vor, in Richtung der gefrorenen Weiten zu segeln. Wenn wir uns das nächste Mal sehen, wird es in Nordend sein.\"\n\nGebt dies Galvar.\n\n<Abbendis händigt Euch ein Tagebuch aus.>\n\nEs wird alles erklären.\n\nDen Scharlachroten Kreuzzug gibt es nicht mehr. Lang lebe der Scharlachrote Ansturm!", sourceObjective = "Liefert das Buch \"Der Weg der Erlösung\" bei Orbaz Blutbann in der Scharlachroten Taverne in Neu-Avalon ab.", progress = "<Orbaz lacht.>\n\nWas ist das? Ein Malbuch für Kinder?", completion = "<Orbaz blättert durch das Tagebuch.>\n\nWas für ein Müll! Dies ist der \"Scharlachrote Morgen\"?\n\nSie segeln in ihren Tod! Konzentrieren wir uns lieber auf die anrückenden Armeen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12757] = { id = 12757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Armeen des Scharlachroten Ansturms rücken näher...", description = "Wir müssen uns auf die anrückenden Armeen vorbereiten, {name}. Ihr werdet Hochlord Mograine schleunigst von Eurer Entdeckung berichten! Ich werde ein Portal direkt nach Acherus öffnen. Tretet hindurch und Ihr werdet dorthin befördert.\n\nGebt Hochlord Mograine auch Abbendis' Tagebuch. Vielleicht wird er es nützlich finden.", sourceObjective = "Liefert das Buch \"Der Weg der Erlösung\" bei Hochlord Darion Mograine in \"Acherus: der Schwarzen Festung\" ab.", progress = "Ihr habt was getan?", completion = "Ihr seid zu einem Werkzeug des Untergangs geworden, {class}! Wir werden diese anrückenden Armeen vernichten und ihre Toten zu unseren Dienern machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12758] = { id = 12758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Helden Helm", description = "Rejek hört Geschichten von riesigen Metallmännern beim weit entfernten Sturmherrenschelf. Du finden es weit im Nordwesten, außerhalb des Rands des Beckens.\n\nStell dir vor, wie Rejek den Kopf eines Riesenmetallmanns als Helm benutzen. Machen Rejek unaufhaltsam! Machen Rejek mächtig!\n\nDu es holen für Rejek, aber Metallkopf vielleicht nicht einfach abzumachen von Metallkörper. Vielleicht Bomben klauen von kleinen, grünen Männchen und ihren Freunden in Schwindelgrins' Grabungsstätte in der Nähe der Sonnenstrahlsäule? Benutzen Bomben um Kopf abzukriegen von Metallkörper und bringen zu Rejek.", sourceObjective = "Besorgt Sprengstoff der Venture Co. von der Venture Company in Schwindelgrins' Grabungsstätte und benutzt ihn, um den Kopf eines Sturmbetrachters zu erhalten. Bringt Rejek beim Hügel der Wildherzen den Kopf des Sturmbetrachters.", progress = "Du bringen Rejek neuen Helm?", completion = "Rejek sieht, du seien erfolgreich gewesen! Jetzt Rejek probieren neuen Kriegshelm auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[12759] = { id = 12759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Instrument des Krieges", description = "Zepik mir erzählen, du vielleicht der beste Gorlocjäger, er getroffen... außer Zepik. Immer noch große Schlacht im Südwesten - du gehen helfen.\n\nZepik ein paar der größten, bösesten Fallen in seiner Truhe in Kartaks Stellung hat... Vekgar befohlen, sie für Kampf zu nutzen, also du sie auch benutzen. Geh jede Falle auswählen, die du willst, und töte viele von Großzungen.\n\nGanz, ganz viele!", sourceObjective = "Holt einige von Zepiks Fallen aus seiner Truhe in Kartaks Stellung. Verwendet die Fallen, um 50 der sich in der Nähe aufhaltenden, funkenbesprühten Gorlocs zu töten, dann kehrt zu Schamane Jakjek in Kartaks Stellung zurück.", progress = "Ziemlich durcheinander! Aber immer noch so lustig.", completion = "Du fast so gut mit diesen Fallen wie Zepik!", sourceObjectiveStatus = "unverified-source-field" }
quests[12760] = { id = 12760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheime Kraft der Wildherzen", description = "Schlacht tobt immer noch in Kartaks Stellung... Ich denke, es an der Zeit für dich, großes Geheimnis der Wildherzen zu lernen.\n\nWir haben Beeren aus anderen Ländern, aus denen wir gekommen... sie nicht so besonders an sich, aber mische sie mit Trinkgetränks und sie machen Wildherz ganz stark. Du nun ein Wildherz... es Zeit, du wirst auch stark.\n\nIch gebe dir jetzt Trinken und dann zerschmetterst du alle Funken-Großzungen.", sourceObjective = "Nutzt den geheimen Trank der Wildherzen und tötet mit der Kraft des Tranks 30 funkenbesprühte Gorlocs um Kartaks Stellung herum.", completion = "Du wilder Kämpfer... komm bald zurück für mehr Kampf. Nie genug gute Kämpfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[12761] = { id = 12761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschen der Kristalle", description = "Funkenbesprühte immer noch angegriffen von Wauwaumenschen... Wir glauben, sie vielleicht nicht aufhören, wenn wir nicht sie aufhalten. Wir haben aber geheime Waffe, wir schicken sie zu Soo-met, damit er nutzen kann, um alle Orakel zu schützen.\n\nGeheime Waffe ist von den Großen persönlich... besonders glänzende Kristalle, die wir in heiligen Tempeln der Großen gefunden. Sei sehr vorsichtig, nicht zerbrechen.\n\nKristalle sind in Kiste nahe Schrein in Zuflucht der Funkenbesprühten, weit im Südwesten. Du gehst und benutzt Kristalle, um Soo-met helfen, Wauwaumenschen zu schlagen.", sourceObjective = "Erlangt die Verteidigung des Kristalls in der Zuflucht der Funkenbesprühten und verwendet sie, um 50 in der Nähe befindliche Wildherzwolvar zu töten. Kehrt zu Blitzrufer Soo-met in der Zuflucht der Funkenbesprühten zurück, sobald diese Aufgaben abgeschlossen sind.", progress = "Sehr mächtig. Wauwaumenschen nicht wissen von Macht der Großen. Dumme Wauwaumenschen.", completion = "Danke, Trockenhaut.\n\nIch behalten diese Kristalle - sie uns beschützen. Vielleicht du kommst bald zurück und uns hilfst noch einmal.", sourceObjectiveStatus = "unverified-source-field" }
quests[12762] = { id = 12762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht der Großen", description = "Wir müssen etwas unternehmen, um Wauwaumenschen aufzuhalten, die Zuflucht der Funkenbesprühten angreifen. Jaloot mir einen ganz besonderen Kristall gebracht, den er im Flussnabel gefunden hat... Wir erst einen wie ihn zuvor gesehen.\n\nDer Kristall jetzt nicht hat genug Kraft, aber die geöffnete Lebensblutsäule sollte genug Energie haben, um ihn aufzuladen, wenn du ihn in die Nähe bringst. Sobald der Kristall aufgeladen ist, geh zu Zuflucht der Funkenbesprühten im fernen Südwesten und lass dich von der Energie des Kristalls groß und stark machen.\n\nDann es Zeit, Wauwaumenschen in Hintern zu treten.", sourceObjective = "Ladet den schlafenden polierten Kristall an der offenen Lebensblutsäule. Reist zur Zuflucht der Funkenbesprühten und verwendet die Kraft des Kristalls, um 30 der sich in der Nähe aufhaltenden Wolvar der Wildherzen zu töten. Sprecht anschließend mit Blitzrufer Soo-met in der Zuflucht der Funkenbesprühten.", progress = "Gut, dass du uns hier hilfst. Langer Kampf.", completion = "So viel Energie in dir... voller Kraft der Großen.\n\nIch nicht lüge, ich ein bisschen neidisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[12763] = { id = 12763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschiebung von Prioritäten", description = "So dringend unsere Bedürfnisse hier auch sein mögen - es gibt Neuigkeiten aus den Ländern im Norden, die wir nicht ignorieren dürfen.\n\nIch habe soeben eine Nachricht vom Argentumkreuzzug erhalten. Offensichtlich sammeln sich die Streitkräfte der Geißel dort und drohen, Zul'Drak zu überrennen.\n\nIch muss wohl kaum erwähnen, {name}, dass unser Kampf hier aussichtslos wäre, wenn das geschähe. Ihr müsst den Kreuzzüglern dort helfen, die Armeen des Lichkönigs zurückzuschlagen.\n\nSprecht mit Makki, sobald Ihr aufbruchbereit seid.", sourceObjective = "Späher Vor'takh möchte, dass Ihr nach Zul'Drak reist und Euch bei Unteroffizier Riannah an der Lichtbresche meldet.\n\nMakki Orkan im Lager Oneqwah wird für Euren Transport sorgen.", completion = "Möge das Licht obsiegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12766] = { id = 12766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Eurem Abgesandten", description = "<Der Drache in Elfengestalt nimmt Euch das Vorstellungsschreiben ab, liest es sich kurz durch und steckt es in seinen Ärmel.>\n\nAlles scheint in Ordnung zu sein. Wenn es Euch jedoch nichts ausmacht, dann würde ich Euch darum bitten, mit dem Abgesandten hier im Tempel zu sprechen.\n\nSie hat noch eine Sache von großer Wichtigkeit, um die Ihr Euch kümmern solltet, bevor wir Euch hoch zur Königin schicken können.\n\n<Er klopft sich auf den Ärmel, in dem er den Brief gesteckt hat.>\n\nIch werde ihn sicher aufbewahren, bis Ihr zurück seid.", sourceObjective = "Sprecht mit Lauriel Wahrklinge im Wyrmruhtempel.", completion = "Ihr müsst {name} sein. Man hat mir gesagt, dass Ihr kommen würdet.\n\nIch denke, dass ich hier eine Aufgabe habe, für die Ihr ganz besonders gut geeignet seid. Nehmt Euch ihrer an und Ihr würdet in die hiesige Drachengemeinschaft aufgenommen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12767] = { id = 12767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Eurem Abgesandten", description = "<Der Drache in Elfengestalt nimmt Euch das Vorstellungsschreiben ab, liest es sich kurz durch und steckt es in seinen Ärmel.>\n\nAlles scheint in Ordnung zu sein. Wenn es Euch jedoch nichts ausmacht, dann würde ich Euch darum bitten, mit dem Abgesandten hier im Tempel zu sprechen.\n\nEr hat noch eine Sache von großer Wichtigkeit, um die Ihr Euch kümmern solltet, bevor wir Euch hoch zur Königin schicken können.\n\n<Er klopft sich auf den Ärmel, in dem er den Brief gesteckt hat.>\n\nIch werde ihn sicher aufbewahren, bis Ihr zurück seid.", sourceObjective = "Sprecht mit Golluck Felsenfaust im Wyrmruhtempel.", completion = "Ihr müsst {name} sein. Mir wurde gesagt, dass Ihr kommen würdet.\n\n\n\nIch habe hier etwas, um das Ihr Euch kümmern müsst. Tut es und Ihr würdet Euch den hiesigen Drachen beweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12768] = { id = 12768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wächter des Wyrmruhtempels", description = "Ihr habt mehr als nur Eure Vertrauenswürdigkeit bewiesen.\n\nIhr solltet zum Wyrmruhtempel zurückkehren und erneut mit dem Wächter Tariolstrasz sprechen, {name}.", sourceObjective = "Sprecht mit Tariolstrasz im Wyrmruhtempel.", completion = "Schon so bald zurück, {name}?\n\nCeristrasz hat uns schon berichtet, dass Ihr kommen würdet. Ich danke Euch für das, was Ihr am Rubindrachenschrein geleistet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12769] = { id = 12769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wächter des Wyrmruhtempels", description = "Ihr habt mehr als nur Eure Vertrauenswürdigkeit bewiesen.\n\nIhr solltet zum Wyrmruhtempel zurückkehren und erneut mit dem Wächter Tariolstrasz sprechen, {name}.", sourceObjective = "Sprecht mit Tariolstrasz im Wyrmruhtempel.", completion = "Schon so bald zurück, {name}?\n\nVargastrasz hat uns schon berichtet, dass Ihr kommen würdet. Ich danke Euch für das, was Ihr am Rubindrachenschrein geleistet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12770] = { id = 12770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umverteilung der Ressourcen", description = "Hört zu, {class}!\n\nEure Tage hier sind gezählt. So sehr wir fähige Kämpfer in unseren Reihen brauchen, gibt es Ärger im Norden, der unsere Probleme wie eine sommerliche Sturmwindparade erscheinen lässt.\n\nEs sieht aus, als ob die Geißel ihre Anstrengungen konzentrieren und einen Vorstoß nach Zul'Drak durchführen würde. Wenn Zul'Drak fallen sollte, könnten wir genauso gut einpacken.\n\nIhr könnt Eure Besorgungen hier noch erledigen, aber dann müsst Ihr zur Lichtbresche aufbrechen. Redet mit Samuel, wenn Ihr eine Transportmöglichkeit braucht.\n\nWegtreten.", sourceObjective = "Gryan Starkmantel will, dass Ihr Euch bei Unteroffizier Riannah an der Lichtbresche in Zul'Drak meldet.\n\nIhr könnt wegen einer Transportmöglichkeit zur Lichtbresche bei Samuel Klarbuch vorsprechen.", completion = "Möge das Licht obsiegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12771] = { id = 12771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisenschmiede", description = "Unsere Gebete wurden erhört! Mithilfe des gebündelten Lichts der Naaru von Shattrath und den gemeinsamen Danksagungen der Gläubigen konnten wir Artefakte von großer Macht erschaffen. Sie werden unsere Waffen im Kampf gegen des Lichkönigs Machenschaften sein.\n\nNehmt dies, {name}. Behaltet es stets im Auge und sorgt dafür, dass es sicher in Eisenschmiede ankommt. Magni Bronzebart wird es kaum erwarten können, den Kampf nach Nordend zu tragen, und dies wird ihn sicherlich seinem Ziel ein Stück näher bringen.", sourceObjective = "Bischöfin Lazaril möchte, dass Ihr das lichterfüllte Artefakt zu König Magni Bronzebart in Eisenschmiede bringt.", progress = "Hallo {name}. Noch nie habe ich einen kräftigeren {race} gesehen! Die Prüfungen der Scherbenwelt haben Euch hart gemacht, Bruder. Ihr seid der Stolz Eures Volkes!", completion = "Bei meinem Barte! Diesem hier wohnt eine Kraft inne, die einer Flotte unserer Flugmaschinen Konkurrenz machen könnte! Ich werde es meinen Kriegspriestern geben und wir werden uns einen Plan ausdenken, mit dem wir diese schrecklichen Nekropolen so schnell wie möglich wieder nach Nordend schicken können... mit uns dicht auf den Fersen!\n\nOh, Muradin, mein Bruder, du musst leben! Bei der Ehre der Bronzebärte: Ich werde dich finden!", sourceObjectiveStatus = "unverified-source-field" }
quests[12772] = { id = 12772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verzweifelte Allianz", description = "<Guter/Gute> {name}, der Lichkönig macht uns, der Horde und der Allianz, mit Krankheiten und einer Invasion zu schaffen. Nur indem wir unsere Stärke vereinen, können wir, die zwei großen Kulturen Azeroths, seinem Angriff standhalten und überleben.\n\nAuf der Terrasse des Lichts in Shattrath hat diese Allianz schon einen Schlag hinnehmen müssen. Um unseren Kampf gegen den Lichkönig zu unterstützen, müsst Ihr zu unserem neuen Allianzlager auf der Terrasse des Lichts gehen und dort mit Bischöfin Lazaril sprechen.\n\nDas Licht sei mit Euch, {name}.", sourceObjective = "Sprecht mit Bischöfin Lazaril im neuen Allianzlager auf der Terrasse des Lichts in Shattrath.", completion = "{name}, geehrter {race}, seid willkommen. Möget Ihr im Schein des Lichts baden - möge Eure uralte Weisheit unser Land in diesen Zeiten der Not schützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12773] = { id = 12773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darnassus", description = "Unsere Gebete wurden erhört! Mithilfe des gebündelten Lichts der Naaru von Shattrath und den gemeinsamen Danksagungen der Gläubigen konnten wir Artefakte von großer Macht erschaffen. Sie werden unsere Waffen im Kampf gegen des Lichkönigs Machenschaften sein.\n\nNehmt dies, {name}. Behaltet es stets im Auge und sorgt dafür, dass es sicher in Darnassus ankommt. Liefert es bei Tyrande Wisperwind ab - für ihre Priesterinnen wird es einen unerlässlichen Quell der Macht im Kampfe gegen die unheiligen Streitkräfte des Nordens darstellen.", sourceObjective = "Bischöfin Lazaril möchte, dass Ihr das lichterfüllte Artefakt zu Tyrande Wisperwind in Darnassus bringt.", progress = "{name}, mein Sohn. Wieder einmal sind wir in einen Konflikt verwickelt, der alles, was wir kennen, in Stücke reißen könnte. Es ist gut, dass ein {class} mit Euren Talenten und Eurer Stärke uns bei der Verteidigung des Weltenbaums zu Hilfe kommt.", completion = "Was ist das? Was für ein Segen! Das Licht, das sie in diesem Artefakt aufgefangen haben, scheint beinahe so hell wie das Licht des Mondes! Unsere Priester werden diese Kraft gegen unsere Feinde einsetzen und des Lichkönigs Invasion wird mit Sicherheit fehlschlagen. Habt Dank, {name}. Unser Weltenbaum wird nun in Sicherheit sein.\n\nAuch spürten wir, dass weit im Norden womöglich ein weiterer Weltenbaum existieren könnte - versteckt in der Nähe des Lichkönigs eigenen Reichs. Der Tag mag vielleicht kommen... an dem wir beide Bäume hüten und eine neue Ära des Friedens einläuten mögen...", sourceObjectiveStatus = "unverified-source-field" }
quests[12774] = { id = 12774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmwind", description = "Unsere Gebete wurden erhört! Mithilfe des gebündelten Lichts der Naaru von Shattrath und den gemeinsamen Danksagungen der Gläubigen konnten wir Artefakte von großer Macht erschaffen. Sie werden unsere Waffen im Kampf gegen des Lichkönigs Machenschaften sein.\n\nNehmt dies, {name}. Behaltet es stets im Auge und sorgt dafür, dass es sicher in Sturmwind ankommt. Der König von Sturmwind ist vor Kurzem zurückgekehrt. Ich bin mir sicher, dass er für dieses Werkzeug dankbar sein wird.", sourceObjective = "Bischöfin Lazaril möchte, dass Ihr das lichterfüllte Artefakt zu König Varian Wrynn in Sturmwind bringt.", progress = "{name}, gut Euch zu sehen. Eure Stärke und Euer Können sind wie ein Segen in diesen Zeiten von Kummer und Schmerz.", completion = "Also haben Shattraths heilige Leute erschaffen, was sie versprochen haben! Im Nachhinein würde ich sagen, dass es die richtige Entscheidung war, so viele Priester und Paladine dorthin zu beordern, anstatt sie gegen die Geißel in den Kampf zu schicken. Mit diesen heiligen Waffen werden wir vielleicht dazu imstande sein, den verdammten Lichkönig und seine Dienerschaft zurückzuschlagen!\n\nUnd so ernenne ich Euch hiermit zu Fürst {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12775] = { id = 12775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verzweifelte Allianz", description = "<Guter/Gute> {name}, der Lichkönig macht uns, der Horde und der Allianz, mit Krankheiten und einer Invasion zu schaffen. Nur indem wir unsere Stärke vereinen, können wir, die zwei großen Kulturen Azeroths, seinem Angriff standhalten und überleben.\n\nAuf der Terrasse des Lichts in Shattrath hat diese Allianz schon einen Schlag hinnehmen müssen. Um unseren Kampf gegen den Lichkönig zu unterstützen, müsst Ihr zu unserem neuen Allianzlager auf der Terrasse des Lichts gehen und dort mit Bischöfin Lazaril sprechen.\n\nDas Licht sei mit Euch, {name}.", sourceObjective = "Sprecht mit Bischöfin Lazaril im neuen Allianzlager auf der Terrasse des Lichts in Shattrath.", completion = "Bruder, wir wurden wieder gerufen, um gegen die Geißel zu kämpfen. Es ist gut, dass Ihr hier seid - mit Eurer Stärke und der Kraft des Lichtes mögen wir vielleicht doch noch den Sieg davontragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12776] = { id = 12776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Exodar", description = "Unsere Gebete wurden erhört! Mithilfe des gebündelten Lichts der Naaru von Shattrath und den gemeinsamen Danksagungen der Gläubigen konnten wir Artefakte von großer Macht erschaffen. Sie werden unsere Waffen im Kampf gegen des Lichkönigs Machenschaften sein.\n\nNehmt dies, {name}. Behaltet es stets im Auge und sorgt dafür, dass es sicher zur Exodar gelangt. Liefert es bei Prophet Velen in der Halle des Lichts ab, auf dass er seine Kräfte gegen die unheiligen Streitkräfte des Nordens einsetzen mag.", sourceObjective = "Bischöfin Lazaril möchte, dass Ihr das lichterfüllte Artefakt bei Velen in der Exodar abliefert.", progress = "Meine Tochter, die Lande der Menschen und Orcs hatten einen positiven Einfluss auf Euch - eine solche Stärke wohnt Euch nun inne...", completion = "Ah, ich kann sehen, wie die Kraft der Naaru durch diesen Gegenstand leuchtet, als wohnte das Licht selbst in seinem Inneren. So viel Gutes kann mit diesem Werkzeug vollbracht werden; die Nekropolen, die aus den gefrorenen Weiten des Nordens geschickt wurden, werden sicherlich scheitern.", sourceObjectiveStatus = "unverified-source-field" }
quests[12777] = { id = 12777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verzweifelte Allianz", description = "<Guter/Gute> {name}, der Lichkönig macht uns, der Horde und der Allianz, mit Krankheiten und einer Invasion zu schaffen. Nur indem wir unsere Stärke vereinen, können wir, die zwei großen Kulturen Azeroths, seinem Angriff standhalten und überleben.\n\nAuf der Terrasse des Lichts in Shattrath hat diese Allianz schon einen Schlag hinnehmen müssen. Um unseren Kampf gegen den Lichkönig zu unterstützen, müsst Ihr zu unserem neuen Allianzlager auf der Terrasse des Lichts gehen und dort mit Bischöfin Lazaril sprechen.\n\nDas Licht sei mit Euch, {name}.", sourceObjective = "Sprecht mit Bischöfin Lazaril im neuen Allianzlager auf der Terrasse des Lichts in Shattrath.", completion = "Zu sehen, dass ein nobler {race} wie Ihr uns zu Hilfe eilt, erfüllt mein Herz mit Licht. Seid gesegnet, guter {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[12778] = { id = 12778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende des Scharlachroten Kreuzzugs", description = "Die Falle hat zugeschnappt, Todesritter. Die Armeen von Herdweiler und Tirisfal sind angekommen; gerade rechtzeitig, um noch zu sehen, wie ihre Enklave in Flammen steht! Falls sie jetzt umkehren sollten, werden sie mit dem Rücken zu uns kämpfen müssen.\n\n<Mograine schüttelt den Kopf.>\n\nNein, ihnen bleibt nur eine Wahl, deren Resultat unumgänglich wäre: IHR ENDE!\n\nWährend wir hier noch sprechen, bereiten sie sich auf ihr letztes Gefecht vor.\n\nDer Lichkönig erwartet Eure Rückkehr, Champion. Er ist dort unten bei der Todesbresche und hält Ausschau.", sourceObjective = "Geht zur Todesbresche und sucht den Lichkönig auf.", completion = "Ihr habt mir gut gedient, {name}. Die Lande des Scharlachroten Kreuzzugs wurden von der Geißel gebrandmarkt. Ihr habt für Tod und Vernichtung gesorgt, so weit das Auge reicht, und mir den letzten Rest der Armeen des Scharlachroten Kreuzzugs ans Messer geliefert.\n\n\n\nEs ist nun Zeit, dass Ihr zu Ende bringt, was Ihr begonnen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12779] = { id = 12779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alle Dinge müssen ein Ende...", description = "Ihr habt unzählige Legionen vernichtet und noch immer verlangt es Eurem dunklen Herzen nach mehr, {name}.\n\n<Der Lichkönig hält inne.>\n\nAlle Dinge müssen ein Ende haben, Todesritter. Das letzte Aufgebot der Armeen des Scharlachroten Kreuzzugs stellt sich uns entgegen. Für sie wird es kein Entrinnen geben... Sie haben keine Wahl. Aus diesem Grund werden sie auch mit einer Wildheit kämpfen, wie Ihr sie noch nie erlebt habt.\n\nStoßt in dieses Horn und ruft einen meiner Wyrms herbei. Klettert auf seinen Rücken und reitet mit ihm in die Schlacht. Mit seiner Hilfe werdet Ihr dem Scharlachroten Kreuzzug ein Ende bereiten.", sourceObjective = "Der Lichkönig hat Euch befohlen, den Scharlachroten Kreuzzug auszuradieren.\n\nBenutzt das Horn der Frostbrut, um einen Frostbrutbezwinger herbeizurufen und mit ihm 150 Scharlachrote Soldaten und 10 Scharlachrote Ballisten zu vernichten. Weicht Geschossen aus, indem Ihr aus ihrer Schusslinie fliegt!", progress = "Tötet sie alle...", completion = "Kniet nieder, Ritter. Hiermit setze ich Euch diesen Helm auf, um Euer schreckenerregendes Aussehen zu vervollkommnen. Jeder, der auch nur wagen sollte, einen Blick auf Euer dunkles Antlitz zu werfen, wird wissen, dass ihn der Tod ereilen wird. Lasst niemanden es wagen, sich gegen unseren König zu stellen, ohne dass er Euren gnadenlosen Zorn zu spüren bekäme, {name}.\n\nEs bleibt nur noch eine letzte Aufgabe...\n\n\n\nDie Kapelle des hoffnungsvollen Lichts.", sourceObjectiveStatus = "unverified-source-field" }
quests[12780] = { id = 12780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feind unseres Feindes", description = "So geschmacklos es für uns auch sein mag, mit Todesrittern zusammenzuarbeiten, wir können uns einfach nicht leisten, bei unseren hiesigen Verbündeten wählerisch zu sein.\n\nWir sind zwischen der Geißel und den Drakkari eingeschlossen, die nichts weiter wollen, als uns aus dem Weg zu räumen, damit sie zueinander kommen können.\n\nReist nach Westen zur Schwarzen Wacht. Sprecht dort mit Stefan und seht nach, ob Ihr ihm zu Diensten sein könnt.", sourceObjective = "Unteroffizier Riannah in der Lichtbresche möchte, dass Ihr mit Stefan in der Schwarzen Wacht sprecht und ihm Eure Unterstützung anbietet.", sourceObjectiveStatus = "unverified-source-field" }
quests[12781] = { id = 12781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen!", description = "Willkommen zu World of Warcraft!\n\nAls besonderen Dank dafür, dass Ihr die World of Warcraft Collector's Edition gekauft habt, erhaltet Ihr diesen Geschenkgutschein. Tauscht ihn bei Siouxsie der Banshee in der Schwarzen Festung ein und Ihr werdet ein Geschenk erhalten: einen kleinen Gefährten, der Euch auf Eurer Suche nach Abenteuern und Ruhm begleiten wird.\n\nNochmals danke. Genießt Euren Aufenthalt in World of Warcraft!", sourceObjective = "Bringt den Geschenkgutschein der Schwarzen Festung zu Siouxsie der Banshee in der Schwarzen Festung.", sourceObjectiveStatus = "unverified-source-field" }
quests[12782] = { id = 12782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifelte Forschung", description = "{name}, der Lichkönig macht uns mit einer Invasion zu schaffen. Um ihn zu seinem Frostthron zurückzudrängen, müssen Horde und Allianz wie Pech und Schwefel zusammenhalten. Doch nun musste diese Allianz auf der Terrasse des Lichts in Shattrath einen Schlag hinnehmen.\n\nGeht zum neuen Apothekerlager dort und sprecht mit Großapotheker Putress, um unseren Kampf gegen den Lichkönig zu unterstützen. Er forscht wie verzweifelt an einem Heilmittel, das die Zombieseuche beseitigen wird. Dieses Mittel ist unsere Erlösung.\n\nMacht schnell, {name}. Mit jeder Sekunde, die vergeht, findet ein weiteres unschuldiges Leben sein Ende.", sourceObjective = "Sprecht mit Großapotheker Putress im neuen Apothekerlager auf der Terrasse des Lichts in Shattrath.", completion = "Was für ein ausgezeichnetes Exemplar Ihr seid. Wir müssen viele Experimente durchführen und unser Nachschub an Freiwilligen ist fast erschöpft. So, Elfe, wie es schon Euer Name andeutet: Habt Ihr etwas Blut übrig? Frisches Blut ist immer willkommen...", sourceObjectiveStatus = "unverified-source-field" }
quests[12783] = { id = 12783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifelte Forschung", description = "{name}, der Lichkönig macht uns mit einer Invasion zu schaffen. Um ihn zu seinem Frostthron zurückzudrängen, müssen Horde und Allianz wie Pech und Schwefel zusammenhalten. Doch nun musste diese Allianz auf der Terrasse des Lichts in Shattrath einen Schlag hinnehmen.\n\nGeht zum neuen Apothekerlager dort und sprecht mit Großapotheker Putress, um unseren Kampf gegen den Lichkönig zu unterstützen. Er forscht wie verzweifelt an einem Heilmittel, das die Zombieseuche beseitigen wird. Dieses Mittel ist unsere Erlösung.\n\nMacht schnell, {name}. Mit jeder Sekunde, die vergeht, findet ein weiteres unschuldiges Leben sein Ende.", sourceObjective = "Sprecht mit Großapotheker Putress im neuen Apothekerlager auf der Terrasse des Lichts in Shattrath.", completion = "Was für ein ausgezeichnetes, robustes Exemplar Ihr seid. Wir haben viele Experimente durchzuführen und unser Nachschub an Freiwilligen ist fast erschöpft. Frisches Blut ist in der Tat willkommen und mit dem Zorn in Eurem Blute ließe sich stundenlang forschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12784] = { id = 12784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifelte Forschung", description = "{name}, der Lichkönig macht uns mit einer Invasion zu schaffen. Um ihn zu seinem Frostthron zurückzudrängen, müssen Horde und Allianz wie Pech und Schwefel zusammenhalten. Doch nun musste diese Allianz auf der Terrasse des Lichts in Shattrath einen Schlag hinnehmen.\n\nGeht zum neuen Apothekerlager dort und sprecht mit Großapotheker Putress, um unseren Kampf gegen den Lichkönig zu unterstützen. Er forscht wie verzweifelt an einem Heilmittel, das die Zombieseuche beseitigen wird. Dieses Mittel ist unsere Erlösung.\n\nMacht schnell, {name}. Mit jeder Sekunde, die vergeht, findet ein weiteres unschuldiges Leben sein Ende.", sourceObjective = "Sprecht mit Großapotheker Putress im neuen Apothekerlager auf der Terrasse des Lichts in Shattrath.", completion = "Was für ein ausgezeichnetes Exemplar Ihr seid. Wir müssen viele Experimente durchführen und unser Nachschub an Freiwilligen ist fast erschöpft. Frisches Blut ist immer willkommen und ich bin mir sicher, dass jemand Eurer Statur etwas Blut übrig hat...", sourceObjectiveStatus = "unverified-source-field" }
quests[12785] = { id = 12785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orgrimmar", description = "Wir haben einen Durchbruch errungen! Unsere Zombieexemplare haben uns einen neuen Einblick in die Beschaffenheit der Geißelseuche gewährt. Man könnte also sagen, dass unsere Forschungen verrottete, köstliche Früchte tragen...\n\nBringt diese Kiste nach Orgrimmar. In ihr befindet sich ein mit der Zombieseuche infizierter Kopf und noch so eine Idee von mir: eine Antiseuche. Die zwei Seuchen bekämpfen sich im Inneren des Zombiegehirns. Ich bin mir ziemlich sicher, dass es der Schlüssel zu einem Heilmittel ist.\n\nBringt die Kiste zu meinem Assistenten Apotheker Karlov. Er ist bei Thrall in Orgrimmar.", sourceObjective = "Großapotheker Putress möchte, dass Ihr Apotheker Karlov in Orgrimmar das Zwei-Seuchen-Hirn bringt.", progress = "Willkommen in Orgrimmar, {name}. Großapotheker Putress hat uns schon benachrichtigt... Habt Ihr das infizierte Gehirn dabei?", completion = "Ah, sehr gut. Die Krankheiten, die dieser verrottete Kopf in sich trägt, sind zwar tödlich, doch wir dürfen uns von Gefahr oder Ekel nicht schrecken lassen. Eines Tages, {name}, werdet Ihr erkennen, dass Verdammnis der Weg zur Erlösung ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[12786] = { id = 12786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerfels", description = "Wir haben einen Durchbruch errungen! Unsere Zombieexemplare haben uns einen neuen Einblick in die Beschaffenheit der Geißelseuche gewährt. Man könnte also sagen, dass unsere Forschungen verrottete, köstliche Früchte tragen...\n\nBringt diese Kiste nach Donnerfels. In ihr befindet sich ein mit der Zombieseuche infizierter Kopf und noch so eine Idee von mir: eine Antiseuche. Die zwei Seuchen bekämpfen sich im Inneren des Zombiegehirns. Ich bin mir ziemlich sicher, dass es der Schlüssel zu einem Heilmittel ist.\n\nBringt die Kiste zu meinem Assistenten Apotheker Chaney. Er ist bei Magatha Grimmtotem in Donnerfels.", sourceObjective = "Großapotheker Putress möchte, dass Ihr Apotheker Chaney in Donnerfels das Zwei-Seuchen-Hirn bringt.", progress = "Willkommen in Donnerfels, {name}. Großapotheker Putress hat uns schon benachrichtigt... Habt Ihr das infizierte Gehirn dabei?", completion = "Ah, sehr gut. Die Krankheiten, die dieser verrottete Kopf in sich trägt, sind zwar tödlich, doch wir dürfen uns von Gefahr oder Ekel nicht schrecken lassen. Eines Tages, {name}, werdet Ihr erkennen, dass Verdammnis der Weg zur Erlösung ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[12787] = { id = 12787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Unterstadt", description = "Die Zombieseuche war ein versteckter Segen. Auf unserer Suche nach einem Heilmittel haben wir sehr viel über die Geißel und ihre ansteckende Krankheit gelernt. Unsere Forschungen haben uns Waffen gegen sie verliehen. Waffen - und Werkzeuge...\n\nNehmt das hier, es ist der Kopf eines Zombies und er wurde zum Teil von seiner Seuche geheilt, indem wir ihm ein aus unseren neusten Entdeckungen hergestelltes Präparat injiziert haben. Liefert den Kopf beim Apothekermeister Faranell ab. Ich habe eine Liste mit Experimenten, denen der Kopf unterzogen werden soll.", sourceObjective = "Großapotheker Putress möchte, dass Ihr Apothekermeister Faranell in Unterstadt das Zwei-Seuchen-Hirn bringt.", progress = "Grüße, {name}. Seid Ihr aus Shattrath gekommen? Habt Ihr Anweisungen von Großapotheker Putress für mich?", completion = "Ah, was für ein ausgezeichnetes Exemplar du doch bist. Die Krankheit - die Krankheiten, wie sie durch dein Gehirn tanzen, müssen dir so erhabene Visionen bescheren. Wir werden lange Nächte miteinander verbringen, werden sprechen, du und ich, und ich werde dir deine Gedanken herauspicken, während ich dir das Fleisch von deinem Schädel abziehe.\n\nHab keine Angst, Kleiner. Dein Opfer wird uns ein unglaubliches Wissen vermitteln. Du bist ein Geschenk für die Verlassenen - du wirst ein neues Zeitalter einläuten; ein Zeitalter, in dem wir von den Völkern dieser Erde respektiert werden. Dein Platz in der Geschichte ist sicher...", sourceObjectiveStatus = "unverified-source-field" }
quests[12788] = { id = 12788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silbermond", description = "Wir haben einen Durchbruch errungen! Unsere Zombieexemplare haben uns einen neuen Einblick in die Beschaffenheit der Geißelseuche gewährt. Man könnte also sagen, dass unsere Forschungen verrottete, köstliche Früchte tragen...\n\nBringt diese Kiste nach Silbermond. In ihr befindet sich ein mit der Zombieseuche infizierter Kopf und noch so eine Idee von mir: eine Antiseuche. Die zwei Seuchen bekämpfen sich im Inneren des Zombiegehirns. Ich bin mir ziemlich sicher, dass es der Schlüssel zu einem Heilmittel ist.\n\nBringt die Kiste zu meiner Assistentin Apothekerin Tepesh. Sie ist bei Lor'themar Theron in Silbermond.", sourceObjective = "Großapotheker Putress möchte, dass Ihr Apothekerin Tepesh in Silbermond das Zwei-Seuchen-Hirn bringt.", progress = "Willkommen in Silbermond, {name}. Großapotheker Putress hat uns schon benachrichtigt... Habt Ihr das infizierte Gehirn dabei?", completion = "Ah, sehr gut. Die Krankheiten, die dieser verrottete Kopf in sich trägt, sind zwar tödlich, doch wir dürfen uns von Gefahr oder Ekel nicht schrecken lassen. Eines Tages, {name}, werdet Ihr erkennen, dass Verdammnis der Weg zur Erlösung ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[12789] = { id = 12789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zur Bresche!", description = "Macht Euch bereit, {class}. Ich entsende Euch zur Lichtbresche nordöstlich von hier.\n\nIch habe Nachricht erhalten, dass die Geißel dazu übergegangen ist, Zul'Drak einzunehmen.\n\n<Valus starrt Euch direkt in die Augen.>\n\nDies wird nicht passieren.\n\nSeht zu, dass die Diener der Geißel dort vernichtet werden. Das Licht verlangt danach.\n\nWegtreten.", sourceObjective = "Kreuzritter Valus bei der Lichtwarte möchte, dass Ihr Euch bei Unteroffizier Riannah in Lichtbresche in Zul'Drak meldet.", completion = "Ausgezeichnet. Valus muss meinen Bericht erhalten haben.\n\nLasst uns an die Arbeit gehen, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12790] = { id = 12790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hin- und zurückkommen: mit Magie", description = "Nur, falls Ihr es nicht wissen solltet: Ihr könnt den Kristall auf der Plattform hinter mir dazu benutzen, um Euch zur Violetten Wacht im Kristallsangwald unterhalb von Dalaran zu teleportieren.\n\nIm Gegenzug könnt Ihr dann auch den Kristall in der Wache verwenden, um zur Kammer über mir zu gelangen.\n\nTut dies nun für mich.", sourceObjective = "Erzmagierin Celindra am Violetten Tor möchte, dass Ihr den Teleporter zum Kristall der Violetten Wacht und den Teleporter zum Dalarankristall verwendet.", progress = "Ich spüre, dass Ihr noch nicht alle beide Teleportationskristalle verwendet habt.\n\nMacht nichts, lasst Euch Zeit.", completion = "Ausgezeichnet, {class}. Nun wisst Ihr, wie man zum Kristallsangwald gelangt und wie man auch wieder zurückkommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12791] = { id = 12791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das magische Königreich Dalaran", description = "Hallo, {name}. Ihr wisst womöglich, dass wir Kirin Tor unsere Stadt hier nach Nordend verlegt haben.\n\nDalaran liegt nicht länger unter seiner schützenden Kuppel am Ufer des Lordameresees. Nun schwebt die Insel auf magische Weise über dem Kristallsangwald.\n\nWir glauben, dass Ihr nun bereit dazu seid, zur Stadt zu reisen. Sprecht mich wieder an und ich werde einen Teleportationszauber wirken, um Euch dorthin zu befördern.\n\nSucht Erzmagierin Celindra auf, sobald Ihr dort angekommen seid, und gebt Ihr mein Signet als Beweis dafür, dass wir gesprochen haben.", sourceObjective = "Liefert das Signet der Kirin Tor bei Erzmagierin Celindra am Violetten Tor in Dalaran ab.", progress = "Ich grüße Euch, {class}.", completion = "Willkommen in Dalaran.\n\nIch werde dafür sorgen, dass der Ring zurückgebracht wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[12792] = { id = 12792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wichtigste zuerst", description = "Hört gut zu, {race}!\n\nIn der gesamten Region kriselt es. Überall, wo Ihr hinseht, werdet Ihr Leute finden, die Eure Hilfe gebrauchen könnten.\n\n<Kunz blickt Euch direkt in die Augen.>\n\nDoch niemand braucht Eure Hilfe gerade dringender als Riannah. Die Diener der Geißel haben sich nun zwischen uns gedrängt. Sie und ihre Männer sind also abgeschnitten.\n\nLichtbresche, der Ort, an dem sich ihre Streitkräfte befinden, liegt gleich südwestlich von hier.", sourceObjective = "Kommandant Kunz in der Argentumwacht möchte, dass Ihr Euch bei Unteroffizier Riannah in der Lichtbresche meldet.", completion = "Mein Bericht muss Kunz erreicht haben.\n\nEs ist gut zu wissen, dass er wohlauf ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[12793] = { id = 12793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rauch am Horizont", description = "Habt Ihr das gehört, {race}?\n\nDas Schlachtengeschrei weit im Westen reicht bis hierher und übertönt selbst unser eigenes.\n\nDie Geißel droht damit, durch die Linien derer zu brechen, die dem sogenannten Argentumkreuzzug angehören. Dies zu verhindern, ist so dringend vonnöten, wie alles andere in der Region.\n\nReist zur Lichtbresche und unterstützt sie bei ihrem Kampf dort. Sprecht mit Maaka und er wird Euch sicher dorthin bringen.", sourceObjective = "Khufu in Zim'Torga möchte, dass Ihr zur Lichtbresche reist und Euch bei Unteroffizier Riannah meldet.\n\nMaaka wird Euch dorthin bringen.", completion = "Möge das Licht obsiegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12794] = { id = 12794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das magische Königreich Dalaran", description = "Hallo, {name}. Es ist Euch möglicherweise bekannt, dass wir Kirin Tor unsere Stadt hier nach Nordend verlegt haben.\n\nDalaran befindet sich nun nicht länger unter der schützenden Kuppel an den Ufern des Lordameresees. Nun schwebt die Stadt auf magische Art und Weise über dem Kristallsangwald.\n\nWir glauben, dass Ihr bereit seid, zu der Stadt zu reisen. Sprecht mich erneut an und ich werde einen Teleportationszauber wirken, um Euch dorthin zu befördern.\n\nWenn Ihr dort seid, so sprecht mit der Erzmagierin Celindra und gebt ihr mein Signet als Beweis dafür, dass Ihr von mir kommt.", sourceObjective = "Bringt der Erzmagierin Celindra am Violetten Tor in Dalaran das Signet der Kirin Tor.", progress = "Ich grüße Euch, {class}.", completion = "Willkommen in Dalaran.\n\nIch werde dafür sorgen, dass der Ring zurückgebracht wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[12795] = { id = 12795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farbe bekennen", description = "Gerade erst habe ich ein Signalfeuer über der Baumlinie gen Osten gesehen.\n\nDas kann nur bedeuten, dass die Dinge für die Kreuzfahrer in der Argentumwache nicht so glatt laufen.\n\nIch kann unseren Posten hier nicht verlassen, {race}, Ihr jedoch schon. Wenn es die Zeit erlaubt, dann macht Euch auf den Weg zu Kommandant Falstaav und seht nach, ob Ihr ihnen nicht die Arbeit erleichtern könnt.", sourceObjective = "Datura Blutrose an der Schwarzen Wacht möchte, dass Ihr mit Kommandant Falstaav in der Argentumwache sprecht.", completion = "Wie es der Zufall so will, gibt es da etwas, bei dem Ihr uns helfen könnt, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12796] = { id = 12796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das magische Königreich Dalaran", description = "Hallo, {name}. Ihr wisst womöglich, dass wir Kirin Tor unsere Stadt hier nach Nordend verlegt haben.\n\nDalaran liegt nicht länger unter seiner schützenden Kuppel am Ufer des Lordameresees. Nun schwebt die Insel auf magische Weise über dem Kristallsangwald.\n\nWir glauben, dass Ihr nun bereit dazu seid, zur Stadt zu reisen. Sprecht mich wieder an und ich werde einen Teleportationszauber wirken, um Euch dorthin zu befördern.\n\nSucht Erzmagierin Celindra auf, sobald Ihr dort angekommen seid, und gebt Ihr mein Signet als Beweis dafür, dass wir gesprochen haben.", sourceObjective = "Liefert das Signet der Kirin Tor bei Erzmagierin Celindra am Violetten Tor in Dalaran ab.", progress = "Ich grüße Euch, {class}.", completion = "Willkommen in Dalaran.\n\nIch werde dafür sorgen, dass der Ring zurückgebracht wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[12797] = { id = 12797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück durchs Tor", description = "Ihr sagt die Wahrheit, {race}. Ich kann spüren, wie die Essenz des Sholazarbeckens selbst jetzt, während wir hier miteinander sprechen, durch die untote Seuche allmählich verbraucht wird.\n\nIch habe mich selbst, mein Sein, an diese Rune gebunden, {race}. Bringt sie zu derjenigen, die Euch hierher geschickt hat; denn nur ihre eigene Macht kann mir den Zugang zu ihrem Reich gewähren.", sourceObjective = "Bringt die Omegarune zum Avatar von Freya im Katarakt der Regenrufer im Sholazarbecken.", progress = "Ihr seid zurückgekehrt, {name}.", completion = "Gut gemacht.\n\nWehe unseren Feinden. Wehe denjenigen, die dem Lichkönig dienen und den Kreationen der Titanen mit Zerstörung drohen. Wehe - denn der Etymidian ist gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12798] = { id = 12798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwertkartenset", description = "Jetzt, da Ihr alle Schwertkarten in einem Set gesammelt habt, erscheint eine weitere Karte. Sie zeigt einen Wahrsager, der Euch immer anzustarren scheint, egal wie Ihr die Karte haltet.\n\nIhr glaubt, dass man mithilfe der Karte womöglich mit irgendwem oder irgendetwas kommunizieren könnte.", sourceObjective = "Beschwört mithilfe des Schwertkartensets einen Wahrsager des Dunkelmond-Jahrmarkts und gebt ihm das Set.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Set der Schwertkarten zusammen zu bekommen! Ausgezeichnet.", completion = "Der Dunkelmond-Jahrmarkt hegt großes Interesse an den Tarotkarten, ruft also einfach nach uns, falls Ihr noch mehr gesammelt haben solltet. Wir verfügen auch über unsere eigenen ausgebildeten Handwerker - erlaubt uns also, Euch etwas im Austausch für die Karten anzubieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12799] = { id = 12799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geister aufsaugen", description = "\"Ihr solltet froh sein, dass er kommt,\" meinten sie. \"Ihr werdet seine Gesellschaft genießen,\" meinten sie...\n\nTja, es ist nicht so, als hätte ich in der Sache irgendeine Wahl. Finkelstein ist der beste Alchemist des Kreuzzugs. Ich nehme einmal an, dass ich mich geehrt fühlen sollte, dass er sich hier bei mir eingerichtet hat. Doch seitdem er hier ist, wurde ich dazu verbannt, verschiedene alchemistische Zutaten zu sammeln.\n\nSagt mir, {race}, was haltet Ihr davon, wenn Ihr mir zur Hand ginget? Gleich südlich von hier gibt es ein paar Teiche, die von Geistern der uralten Trolle heimgesucht werden. Bringt mir ihr Ektoplasma.", sourceObjective = "Hauptmann Arnath in Heb'Valok möchte, dass Ihr 5 Einheiten uralten Ektoplasmas von den verlorenen Drakkarigeistern in den Teichen von Zha'jin sammelt.", progress = "Guten Tag, {race}. Habt Ihr das Ektoplasma gesammelt, um das Finkelstein gebeten hat?", completion = "Habt Dank, {class}.\n\nDas sollte meinen Männern wertvolle Zeit ersparen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12800] = { id = 12800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehl des Lichkönigs", description = "Die Scharlachrote Enklave gibt es nicht mehr und um die Reste des Kreuzzugs wird man sich in Nordend kümmern.\n\nWir werden nun all unsere Aufmerksamkeit auf die Kapelle des Hoffnungsvollen Lichts richten. Wir werden es nicht mehr zulassen, dass diese Beleidigung an Euren Meister weiter existiert!\n\nIch habe meinen letzten Befehl erteilt. Geißelkommandant Thalanor erwartet Euch an Braumanns Mühle. Geht nach Nordwesten, dann durch die Höhle und Ihr erreicht das Giftige Tal. Folgt dem Pfad aus dem Tal heraus und Ihr werdet zur Mühle gelangen.\n\nEnttäuscht mich nicht, {name}.", sourceObjective = "Meldet Euch bei Geißelkommandant Thalanor bei Braumanns Mühle.", completion = "Der Hochlord und die anderen {class} sind bereit zuzuschlagen! Wir werden den letzten Rest Leben von diesem Flecken Erde tilgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12801] = { id = 12801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Licht der Morgendämmerung", description = "Die Diener der Argentumdämmerung in der Kapelle des Hoffnungsvollen Lichts lehnen sich gegen uns auf. Sie wagen es, sich der Geißel entgegenzustellen, und allein aus diesem Grund müssen sie vernichtet werden!\n\nDie mächtigen Armeen des Lichkönigs stehen für die kommende letzte Schlacht um die Pestländer bereit. Heute werden wir als Helden der Geißel verewigt werden!\n\nMeldet Euch bei Hochlord Darion Mograine, wenn Ihr kampfbereit seid. Er wird den endgültigen Marschbefehl geben und unsere Armeen bei der Kapelle des Hoffnungsvollen Lichts anführen.", sourceObjective = "Besiegt die Streitkräfte der Argentumdämmerung und findet das Licht der Morgendämmerung.\n\nMeldet Euch bei Hochlord Darion Mograine, falls Ihr überleben solltet.", progress = "<Hochlord Mograine nickt.>", completion = "Für uns wird es keine Buße geben, {name}. Wir sind auf ewig dazu verdammt, als Monster auf dieser Welt zu wandeln. Der Lichkönig mag uns zwar nicht mehr völlig beherrschen, doch die Geister unserer Vergangenheit werden auf ewig unsere Erinnerungen heimsuchen.\n\nWir müssen es also auf die einzige Art und Weise wiedergutmachen, in der wir uns verstehen: das Töten...\n\nIch ersuche Euch also, mir nach Acherus zu folgen und dort als Ritter der Schwarzen Klinge zu dienen. Gemeinsam werden wir den Lichkönig vernichten und der Geißel ein Ende machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12802] = { id = 12802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein Herz liegt in Euren Händen", description = "<Drakurus Stimme erfüllt Euren Geist.>\n\nHe, Mann! Das Auge der Propheten is' der Wahnsinn! Ich hab's benutzt, um dich zu beobachten un' ich seh', du hast jetzt das Herz! Nich' schlecht...\n\nJetzt musst du's zu meinem Podest bei der Passage von Drak'atal bringen, 'n kleines Stück östlich von hier.\n\nAuf dem Sockel da musst du mein Elixier trink'n, um mich zu beschwör'n. Diesmal musst du 'n bisschen verzweifeltes Mojo von den Verteidigern da reinmischen, damit's klappt.", sourceObjective = "Drakuru möchte, dass Ihr ihm das Herz der Uralten zur Drak'atal Passage bringt.\n\nUm das Elixier verwenden zu können, müsst Ihr 5 verzweifelte Mojo sammeln.", completion = "Beeindruckend, Mann! Gütig vom Schicksal, dass es uns zusamm'gebracht hat.\n\nBald säuber' ich Drak'Tharon und nehm' Rache für meine Brüda. Un' du kriegst Drak'Tharons größten Schatz zur Belohnung!", sourceObjectiveStatus = "unverified-source-field" }
quests[12803] = { id = 12803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naturgewalt", description = "Ich bin nicht sicher, was ich sah, als ich nach Nordosten flog, aber es sah aus wie eine gigantische Frau, die in den Landen dort die Geißel aufmischte.\n\nIch hörte den Professor über eine gewisse \"Lebenswächterin\" sprechen, von den Titanen dazu beauftragt, das Sholazarbecken zu behüten. Ich bin nicht bewandert in Titanengeschichte, aber das klingt, als sei sie die Richtige.\n\nIch weiß auch, dass alle Teilnehmer unserer Expedition so gut wie tot sind, wenn die Geißel die Grenze zwischen den Verlorenen Landen und dem Rest von Sholazar überquert. Was haltet Ihr davon, sie zu suchen und ihr zu helfen?", sourceObjective = "Begebt Euch zur Seuchenfront zwischen dem Katarakt der Regenrufer und den Verlorenen Landen im Sholazarbecken und sucht den Avatar von Freya.", completion = "Ihr seid nicht von hier. Aber Ihr gehört auch nicht zur Geißel.\n\nWas soll ich mit Euch anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[12804] = { id = 12804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Steak für Jäger", description = "Manchmal gibt es nichts Schlimmeres als ein Lager voller Jäger. Die sind so erpicht darauf, Raubtiere zu erlegen, dass ich nur trockenes, zähes Fleisch bekomme. Und das ist nicht gerade etwas, worauf man sich nach einem langen, beschwerlichen Tag auf der Jagd freuen kann.\n\nZum Glück kann man hier in der Nähe aber auch zartes, saftiges Fleisch finden. Südlich des Flusses und Lagers leben Langhalsgrasfresser. Das wäre wirklich perfektes Fleisch für unsere hungrigen Jäger. Bringt mir die besten Fleischstücke und wir können einen Festschmaus für unsere Kameraden zubereiten.", sourceObjective = "Bringt 5 Langhalsgrasfresser-Steaks zu Korg dem Spalter in Nesingwarys Basislager.", progress = "Habt Ihr die Steaks?", completion = "Das nenne ich eine Mahlzeit! Wenn es etwas Gutes an dem Schiffbruch gibt, dann wohl, dass wir davor bewahrt worden sind, einen Monat lang nichts anderes als Pökelfleisch zu essen! Vielen Dank nochmals, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12805] = { id = 12805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfangen von Lebenskraft", description = "Die Lebensblutsäule wurde mit brachialer Gewalt umgeworfen und ließ die Erde selbst erbeben.\n\nDie Elementare, die sich bei der Versprengten Scherbe aufhalten, tragen die Lebensessenz in sich, die der Säule ihre Stärke verlieh. Ich kann nicht zulassen, dass diese Energie verschwendet wird, denn nur vier Säulen bestehen noch.\n\nBegebt Euch zur Versprengten Scherbe im Südosten und sucht die Lebensblutelementare.\n\nVerwendet diesen Edelstein bei ihren Überresten, um ihre wilde Energie einzufangen. Wir brauchen diese Energie, um das Land zu heilen, wenn alles vorüber ist.", sourceObjective = "Der Avatar von Freya möchte, dass Ihr Euch zur Versprengten Scherbe im Südosten begebt und den Edelstein der Lebenskraft an 8 vernichteten Lebensblutelementaren verwendet.", completion = "Ich danke Euch, {name}. Der Sturz der Säule ist eine Schande, doch wir müssen retten, was noch zu retten ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[12806] = { id = 12806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Todesanhöhe so schnell Ihr könnt!", description = "Einige würden sagen, dass unsere allerwichtigste Aufgabe nicht den Lichkönig betrifft, sondern die völlige Zerstörung des Scharlachroten Ansturms. Eine Torheit, wie ich meine, doch wer bin ich, um darüber urteilen zu können?\n\nDie Todesanhöhe befindet sich weit im Südwesten an den Klippen, die über das Meer hinausblicken. Dort befindet sich Lordkommandant Arete und führt höchstpersönlich Aufsicht über die Zerstörung des Scharlachroten Ansturms.\n\n<Der Baron räuspert sich.>\n\nSeht zu, dass Ihr Euch so schnell wie möglich bei ihm meldet. Er hat nach Euch und nur nach Euch gefragt.", sourceObjective = "Meldet Euch bei Lordkommandant Arete auf der Todesanhöhe in Eiskrone.", completion = "Wurde verdammt noch mal Zeit! Zweifellos hat Baron Splitter sich Zeit gelassen, Euch zu mir zu schicken.\n\nIch sollte den leeren Platz zwischen seinen Schultern entfernen lassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12807] = { id = 12807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was bis jetzt geschehen ist...", description = "Wir haben viel zu tun, aber ich finde, zuerst steht eine kleine Gedächtnisauffrischung an.\n\nWir Todesritter haben eine anschauliche Vergangenheit mit unseren Freunden, den Scharlachroten, hinter uns - und die sind dumm genug, sich im nordwestlich gelegenen Hafen unter uns auszuruhen.\n\nWenn Ihr bereit für ein paar Worte seid, dann wendet Euch noch einmal an mich und ich werde Euch erleuchten.", sourceObjective = "Lauscht Lordkommandant Aretes Erzählung über die Todesanhöhe.", completion = "In seiner Torheit hat sich der Argentumkreuzzug entschieden, angesichts der Anwesenheit des Scharlachroten Ansturms ein Auge zuzudrücken. Wir hingegen werden das nicht tun.\n\nEs ist uns gleich, ob sie im Kampf gegen den Lichkönig hilfreich wären. Wir halten sie nicht für würdig genug, um zu existieren. Wir werden ihnen ein Ende bereiten, ein für alle Mal!", sourceObjectiveStatus = "unverified-source-field" }
quests[12808] = { id = 12808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verzweifelte Allianz", description = "<Guter/Gute> {name}, der Lichkönig macht uns, der Horde und der Allianz, mit Krankheiten und einer Invasion zu schaffen. Nur indem wir unsere Stärke vereinen, können wir, die zwei großen Kulturen Azeroths, seinem Angriff standhalten und überleben.\n\nAuf der Terrasse des Lichts in Shattrath hat diese Allianz schon einen Schlag hinnehmen müssen. Um unseren Kampf gegen den Lichkönig zu unterstützen, müsst Ihr zu unserem neuen Allianzlager auf der Terrasse des Lichts gehen und dort mit Bischöfin Lazaril sprechen.\n\nDas Licht sei mit Euch, {name}.", sourceObjective = "Sprecht mit Bischöfin Lazaril im neuen Allianzlager auf der Terrasse des Lichts in Shattrath.", completion = "Mein gnomischer Bruder, ich bin stolz, in diesen Zeiten der Not an Eurer Seite stehen zu dürfen. Seid gesegnet und mögen die schlauen Augen Eures Volkes den Weg zu unserer Erlösung finden...", sourceObjectiveStatus = "unverified-source-field" }
quests[12809] = { id = 12809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisenschmiede", description = "Unsere Gebete wurden erhört! Mithilfe des gebündelten Lichts der Naaru von Shattrath und den gemeinsamen Danksagungen der Gläubigen konnten wir Artefakte von großer Macht erschaffen. Sie werden unsere Waffen im Kampf gegen des Lichkönigs Machenschaften sein.\n\nNehmt dies, {name}. Behaltet es stets im Auge und sorgt dafür, dass es sicher in Eisenschmiede ankommt. Hochtüftler Mekkadrill in Tüftlerstadt wird es kaum erwarten können, sich die Kraft des Artefakts zu Nutze zu machen.", sourceObjective = "Bischöfin Lazaril möchte, dass Ihr das lichterfüllte Artefakt zu Hochtüftler Mekkadrill in Eisenschmiede bringt.", progress = "Hallo, {name}! Seht Euch mal an! Ich sehe, dass Ihr seit unserer letzten Begegnung haargenau einskommasieben-drei Mikrometer gewachsen seid. Die Luft der Scherbenwelt hatte einen Effekt auf Euch, da bin ich mir sicher.", completion = "Unglaublich makellos! Der Grad an Lichtenergie, den dieses Gerät speichern kann, übersteigt alles bisher Bekannte! Oh, nur daran zu denken, welche Möglichkeiten sich dadurch eröffnen, lässt meine Bartstoppeln zittern und meine Zehennägel sich aufstellen - ho, ho! Der antinachtaktive Photostreugenoauslöser, den ich daraus herstellen könnte, würde die Nacht zum Tage machen! Die Geißel wird gar nicht wissen, wie Ihr geschieht. Wir werden sie alle mit nur einem Zug am Hebel vernichten!", sourceObjectiveStatus = "unverified-source-field" }
quests[12810] = { id = 12810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut im Wasser", description = "Die Truppen im Hafen des Ansturms haben erhebliche Verstärkung durch Greifenreiter erhalten. Ihr braucht ein Reittier, mit dem Ihr sie aus der Luft holen könnt. Doch zunächst benötigen wir die Komponenten für das Ritual, das dies erst einmal ermöglichen wird.\n\nEine beträchtliche Menge Blut ist für die Durchführung des Rituals vonnöten.\n\n<Der Lordkommandant deutet nach Nordwesten hinab.>\n\nUnten im Hafen gibt es bereits verfügbare Vorräte... Haie. Kehrt nicht zurück, ehe Ihr nicht diese Blase mit ihrem Blut gefüllt habt.", sourceObjective = "Lordkommandant Arete auf der Todesanhöhe möchte, dass Ihr die Blutblase mit dem Blut von 10 ausgehungerten Haien füllt.", completion = "Gut gemacht. Nehmt Euch einen Moment Zeit, das Salzwasser auf Eurer Haut zu trocknen, ehe wir fortfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[12811] = { id = 12811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifelte Forschung", description = "{name}, der Lichkönig macht uns mit einer Invasion zu schaffen. Um ihn zu seinem Frostthron zurückzudrängen, müssen Horde und Allianz wie Pech und Schwefel zusammenhalten. Doch nun musste diese Allianz auf der Terrasse des Lichts in Shattrath einen Schlag hinnehmen.\n\nGeht zum neuen Apothekerlager dort und sprecht mit Großapotheker Putress, um unseren Kampf gegen den Lichkönig zu unterstützen. Er forscht wie verzweifelt an einem Heilmittel, das die Zombieseuche beseitigen wird. Dieses Mittel ist unsere Erlösung.\n\nMacht schnell, {name}. Mit jeder Sekunde, die vergeht, findet ein weiteres unschuldiges Leben sein Ende.", sourceObjective = "Sprecht mit Großapotheker Putress im neuen Apothekerlager auf der Terrasse des Lichts in Shattrath.", completion = "Was für ein ausgezeichnetes, robustes Exemplar Ihr seid. Wir haben viele Experimente durchzuführen und unser Nachschub an Freiwilligen ist fast erschöpft. Frisches Blut ist in der Tat willkommen und mit Eurem wilden Blut ließe sich stundenlang experimentieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[12812] = { id = 12812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orgrimmar", description = "Wir haben einen Durchbruch errungen! Unsere Zombieexemplare haben uns einen neuen Einblick in die Beschaffenheit der Geißelseuche gewährt. Man könnte also sagen, dass unsere Forschungen verrottete, köstliche Früchte tragen...\n\nBringt diese Kiste nach Orgrimmar. In ihr befindet sich ein mit der Zombieseuche infizierter Kopf und noch so eine Idee von mir: eine Antiseuche. Die zwei Seuchen bekämpfen sich im Inneren des Zombiegehirns. Ich bin mir ziemlich sicher, dass es der Schlüssel zu einem Heilmittel ist.\n\nBringt die Kiste zu meinem Assistenten Apotheker Karlov. Er ist bei Thrall in Orgrimmar.", sourceObjective = "Großapotheker Putress möchte, dass Ihr Apotheker Karlov in Orgrimmar das Zwei-Seuchen-Hirn bringt.", progress = "Grüße, {name}. Seid Ihr aus Shattrath gekommen? Habt Ihr Anweisungen von Großapotheker Putress für mich?", completion = "Ah, sehr gut. Die Krankheiten, die dieser verrottete Kopf in sich trägt, sind zwar tödlich, doch wir dürfen uns von Gefahr oder Ekel nicht schrecken lassen. Eines Tages, {name}, werdet Ihr erkennen, dass Verdammnis der Weg zur Erlösung ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[12813] = { id = 12813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhebt euch von den Toten!", description = "Wie gütig... wie großzügig unser Lordkommandant doch ist. Wo er Blumen und Sonnenschein ist, bin ich nur von Hass erfüllt.\n\nEs reicht nicht, ihre erbärmlichen Leben zu beenden - ich möchte sie erniedrigen... entwürdigen!\n\nWas könnte unaussprechlicher sein, als sich in das zu verwandeln, was man hasst? Seine Existenz der Auslöschung einer Sache zu widmen und dann am Ende selbst dazu zu werden?\n\nWie traurig.\n\nBringt diese Tinktur nach Nordwesten zum Hafen des Ansturms. Träufelt sie auf ihre reglosen Leichen und beobachtet das Geschehen - aber meidet die Kathedrale.", sourceObjective = "Setaal Dunkelheiler auf der Todesanhöhe hat Euch die Tinktur des Dunkelheilers gegeben. Träufelt sie auf 10 beliebige Leichen der Einheiten des Scharlachroten Ansturms, die Ihr im Hafen des Ansturms findet.", completion = "<Der Todesritter der Draenei fixiert Euch mit kaltem, starrem Blick, ihre Augen leer und tot. Ein durchtriebenes Grinsen kriecht über ihre Gesichtszüge.>\n\nIch habe noch mehr Tinktur für morgen vorbereitet. Auf dann, gehabt Euch wohl.", sourceObjectiveStatus = "unverified-source-field" }
quests[12814] = { id = 12814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr werdet einen Greifen brauchen", description = "Was könnte passender sein, als einen ihrer eigenen Greifen gegen sie einzusetzen? Geht zum Hafen des Ansturms und nehmt die Zügel eines ihrer Greifen aus den toten Klauen seines Reiters.\n\nKehrt mit dem Greifen zu Uzo Todesrufer zurück. Er wird für seine Verwandlung sorgen und Euch weitere Instruktionen geben.", sourceObjective = "Bringt Uzo Todesrufer auf der Todesanhöhe einen Greifen des Ansturms.", progress = "Warum hat das so lange gedauert? Sind ihre Greifen langsam? Dagegen müssen wir etwas unternehmen!", completion = "Oh ja, das wird gut!\n\nTretet zurück... ich werde den Zorn des Blutrituals herbeirufen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12815] = { id = 12815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flugsperrzone", description = "Nun, da du einen Knochengreifen hast, möchte ich, dass du jeden Tag dort hinunter fliegst und den Luftraum über dem Hafen des Ansturms zu einer Flugverbotszone machst.\n\nIch muss zugeben, Mann, dass es mich nicht wirklich juckt, ob du die Greifenreiter nun mit dem Knochengreifen tötest oder nich'. Doch ich meine, dass es um einiges einfacher sein wird, zu ihnen zu kommen, wenn du den Greifen nimmst.\n\nDavon abgesehen verfügt er über eine Menge netter kleiner Tricks, die du dir zunutze machen kannst.", sourceObjective = "Uzo Todesrufer auf der Todesanhöhe möchte, dass Ihr 10 Greifenreiter des Ansturms tötet.", progress = "Wieso bist du so schnell schon zurück? Wenn mich meine Augen nicht täuschen, dann fliegen diese Jungs vom Ansturm noch immer da rum!", completion = "So soll's sein! Und weißt du was? Das muss jeden Tag, den wir hier sind, gemacht werden.\n\nIch hoffe, dass du morgen wieder zurückkommen wirst. Dein Knochengreif wird auf dich warten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12816] = { id = 12816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersucht die Geißel bei Silbermond", description = "Der Lichkönig hat seine untoten Diener hierher geschickt - sie stehen also sozusagen direkt vor unserer Haustüre. Wir können das nicht weiter untätig hinnehmen! Ihr steht uns doch sicherlich bei der Verteidigung von Silbermond gegen diese verfluchten Eindringlinge zur Seite?\n\nEs gibt dort draußen ein paar merkwürdige Runenkreise, deren leuchtende Energie dieselbe ist wie diejenige, welche die Untoten und die Nekropole dort oben umgibt. Ich bin mir sicher, dass sie von Bedeutung sind. Findet heraus, was es damit auf sich hat. Lichtet die Reihen dieser entarteten Kreaturen, wenn Ihr schon einmal dabei seid, und bringt mir neben Eurem Bericht auch etwas als Beweis dafür, dass sie tot sind. Ihr werdet nicht leer ausgehen. Geht jetzt!", sourceObjective = "Sammelt drei dunkle nekrotische Steine von den Dienern der Geißel außerhalb von Silbermond und untersucht die leuchtenden Runenkreise in der Nähe ihres Lagers.", progress = "Habt Ihr Eure Untersuchung schon abgeschlossen? Wir haben keine Zeit zum Trödeln!", completion = "Hmm. Euren Worten nach zu urteilen, müssen die Stimmen der Kreise... auf irgendeine Art und Weise zur Kommunikation dienen. Bei dem Gedanken daran, welch unnatürliches Denken mit solcher Magie verbunden ist, stellen sich mir die Nackenhaare auf. Trotzdem: Ihr habt es herausgeschafft und seid, wie es scheint, noch in einem Stück und bei Verstand. Die Argentumdämmerung schätzt Euren Dienst.", sourceObjectiveStatus = "unverified-source-field" }
quests[12817] = { id = 12817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersucht die Geißel bei der Exodar", description = "Der Lichkönig hat seine untoten Diener hierher geschickt - sie stehen also sozusagen direkt vor unserer Haustüre. Wir können das nicht weiter untätig hinnehmen! Ihr steht uns doch sicherlich bei der Verteidigung der Exodar gegen diese verfluchten Eindringlinge zur Seite?\n\nEs gibt dort draußen ein paar merkwürdige Runenkreise, deren leuchtende Energie dieselbe ist wie diejenige, welche die Untoten und die Nekropole dort oben umgibt. Ich bin mir sicher, dass sie von Bedeutung sind. Findet heraus, was es damit auf sich hat. Lichtet die Reihen dieser entarteten Kreaturen, wenn Ihr schon einmal dabei seid, und bringt mir neben Eurem Bericht auch etwas als Beweis dafür, dass sie tot sind. Ihr werdet nicht leer ausgehen. Geht jetzt!", sourceObjective = "Sammelt drei dunkle nekrotische Steine von den Dienern der Geißel außerhalb der Exodar und untersucht die leuchtenden Runenkreise in der Nähe ihres Lagers. Kehrt anschließend zu Leutnant Kregor zurück.", progress = "Habt Ihr Eure Untersuchung schon abgeschlossen? Wir haben keine Zeit zum Trödeln!", completion = "Hmm. Euren Worten nach zu urteilen, müssen die Stimmen der Kreise... auf irgendeine Art und Weise zur Kommunikation dienen. Bei dem Gedanken daran, welch unnatürliches Denken mit solcher Magie verbunden ist, stellen sich mir die Nackenhaare auf. Trotzdem: Ihr habt es herausgeschafft und seid, wie es scheint, noch in einem Stück und bei Verstand. Die Argentumdämmerung schätzt Euren Dienst.", sourceObjectiveStatus = "unverified-source-field" }
quests[12818] = { id = 12818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufräumen", description = "Um auf den Punkt zu kommen... Ricket hat mich gebeten, ein paar stärkere Landminen zusammenzubauen, aber mir gehen die Teile aus.\n\nDirekt westlich der Stadt findet Ihr die Überreste unseres letzten Raketenschlittens... Ricket war ein wenig aufgeregt, als sie ihn auftankte, aber vermutlich hätte ich den Einfüllstutzen auch nicht direkt über den Schubdüsen anbringen dürfen. Aus Fehlern lernt man, nicht wahr?\n\nUm den kaputten Schlitten herum sollten jede Menge Ersatzteile liegen... Wieso geht Ihr nicht los, verjagt diese Plünderer und schnappt Euch ein paar Trümmer?", sourceObjective = "Jeer Funksockel in K3 hätte gerne 10 verbrannte Trümmer.", progress = "Wir brauchen etwas, das wir zur Isolation unserer Maschinen gegen die Kälte verwenden können... denk nach, Jeer, denk nach!\n\nOh, he! Habt Ihr ein paar dieser Trümmer für mich?", completion = "Die kann ich gut gebrauchen, danke!\n\nIhr habt da draußen nicht zufällig Dim gesehen? Ich habe ihn schon vor einer ganzen Weile weggeschickt und er kam bisher nicht zurück. Ich hoffe, es geht ihm gut.\n\nWo wir gerade davon sprechen... Ich frage mich, wo Janks ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[12819] = { id = 12819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur einen Minenwurf entfernt", description = "Verflixt nochmal! Wo sind meine Werkzeuge? Gerade eben waren sie doch noch da.\n\nOh! Ich habe sie wohl vergessen, als ich das Minenfeld im Westen angelegt habe. Das ist ziemlich ärgerlich. Ich wäre sehr erfreut, wenn Ihr mir die Werkzeuge wieder beschaffen könntet. Ihr müsst allerdings vorsichtig sein, wo Ihr hintretet... Ihr solltet denselben Weg benutzen können, auf dem ich herausgekommen bin.\n\nOh, versucht übrigens nicht, dorthin zu fliegen... ich war nämlich so klug und habe Türme aufgestellt, die alles angreifen, was aus der Luft kommt. Und sie kümmern sich nicht sonderlich darum, wer angeflogen kommt.", sourceObjective = "Jeer Funksockel in K3 bittet Euch, dass Ihr Funksockels Werkzeuge aus seinem Minenfeld holt.", progress = "Wenn Janks hier wäre, hätte ich einfach ihn schicken können. Aber... wenn ich's mir recht überlege... bin ich mir nicht sicher, ob ich ihm überhaupt gesagt habe, wo der sichere Weg ist.\n\nNa, zum Glück gibt es hier ja genügend von Euch Abenteurern, nicht wahr?", completion = "Ha ha! Das sind sie! Danke vielmals. Hoffentlich hattet Ihr nicht allzu große Probleme auf Eurem Weg durch das Feld.", sourceObjectiveStatus = "unverified-source-field" }
quests[12820] = { id = 12820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwölf auf einen Streich", description = "Ich warte schon eine Ewigkeit auf diese Minen! Naja, zumindest einige Tage. Warum hat das so lange gedauert?\n\nAlso, die Sache ist die, <Kompadre/meine Beste>... es gibt da einen wilden Haufen von Magnatauren - man kennt sie ja... groß, behaart und unglaublich hässlich. Und sie sind ganz scharf darauf, sich K3 unter den Nagel zu reißen.\n\nWird aber nicht klappen.\n\nWir haben ihnen ein paar Steine in den Weg gelegt... nordöstlich von hier steht unsere Verteidigung. Leider sind die Energievorräte unserer Lasertürme ziemlich eingeschränkt... und da kommen diese Minen ins Spiel! Begebt Euch dorthin und jagt sie in die Luft!", sourceObjective = "Ricket in K3 wünscht, dass Ihr mithilfe der verbesserten Landminen Garms Bann vor 12 Angreifern verteidigt. Zu den Angreifern zählen Garmeindringlinge sowie schneeblinde Anhänger.", completion = "Also... ich habe hier gesessen und habe mich an meiner eigenen Vollkommenheit gelabt, als ich in der Ferne einen Knall gehört habe! Und dann noch einen! Und noch ein Dutzend mehr! Bei dem Gedanken daran, dass all diese Magnatauren und Schneebolde in den Tod rennen, hat sich ein kleines, aber feines Lächeln in mein liebliches Gesicht geschlichen.\n\nWar es so fantastisch, wie ich es mir vorstelle?", sourceObjectiveStatus = "unverified-source-field" }
quests[12821] = { id = 12821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zellenblocktango", description = "Der Pioniertrupp ist bereit! Das heißt, dass jetzt Spaß angesagt ist!\n\nUnserem großen Angriff auf Garm steht nur noch eine Sache im Weg! Ich habe einen Läufer losgeschickt, um einen Teleporter hinter ihm aufzustellen... mit Erfolg, wenn ich das hinzufügen darf. Er ist zurückgekommen, um den Akku zu holen, der für den Betrieb benötigt wird. Aber der Teleporter funktioniert immer noch nicht... das heißt, dass der Akku dort nicht angekommen ist.\n\nIch möchte, dass Ihr auf der anderen Seite von Garms Bann nach dem Transporterakku sucht. Bringt ihn dann weiter östlich zu Garms Erhebung, sobald Ihr ihn gefunden habt, und aktiviert den Teleporter.", sourceObjective = "Ricket am K3 möchte, dass Ihr den Transporterakku findet und damit die Transporterplatte in Garms Erhebung aktiviert.", progress = "Selbst Magnatauren sollten wissen, dass man sich am besten nicht mit Goblins anlegt!", completion = "Hervorragend!\n\n<Ein böses Grinsen breitet sich in Rickets Gesicht aus.>\n\nDie Zerstörung kann beginnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12822] = { id = 12822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kenne keine Furcht", description = "Nun verfügen wir über einen offenen Teleporter, doch mein Plan ist äußerst komplex und facettenreich, weswegen er eine fehlerfreie Koordinierung erfordert. Außerdem müssen Vorräte gesammelt werden! Und Truppen rekrutiert! Voraussichtlich kommen Wochen voll harter Arbeit auf Euch zu!\n\nHaha, da habe ich Euch aber einen Schrecken eingejagt, oder? Hier, Freundchen, springt durch den Teleporter und dann auf in den Kampf!! Unsere Pioniere werden Euch Deckung geben... Sie können nicht entkommen!", sourceObjective = "Ricket auf dem K3 möchte, dass Ihr 6 Garmwächter und 8 schneeblinde Anhänger tötet.", completion = "Haha! Das wird diese Rohlinge lehren, unsere Zeit zu verschwenden. Von diesem Tag an wird der Anblick grüner Haut die Herzen aller Magnatauren mit Furcht erfüllen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12823] = { id = 12823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein perfekter Plan", description = "Hallo! Ihr wollt Euch uns für den Angriff anschließen, nehme ich an?\n\nIch habe eine besondere Aufgabe für Euch... wir werden dafür sorgen, dass die gesamte Höhle über ihnen einstürzt! Am hinteren Ende der Höhle müsste Frostgeweides Altar zu finden sein. Schleicht Euch heran und bringt dieses dichtgepackte Sprengstoffbündel irgendwo in der Nähe an.\n\nSobald der Sprengstoff erst einmal platziert ist, sollt Ihr noch lange genug bleiben, um sicherzustellen, dass Frostgeweide auch ins Gras beißt, und dann so schnell wie möglich verschwinden! Niemand weiß, wie lange die Höhle intakt bleibt, nachdem das Ding in die Luft geflogen ist!", sourceObjective = "Gino auf Garms Erhebung möchte, dass Ihr das dichtgepackte Sprengstoffbündel in der Nähe von Frostgeweides Altar anbringt und anschließend Tormar Frostgeweide tötet. Danach sollt Ihr entkommen, bevor die Höhle über Euch einbricht.", progress = "Das Sprengstoffbündel ist mein Baby... Ich habe Wochen gebraucht, um es perfekt hinzubekommen. WOCHEN!\n\nDas ist eine lange Zeit... okay.", completion = "Der ganze Berg hat gebebt! War es toll? Ich bin mir sicher, dass es das war! Wie könnte es auch anders sein?\n\nUnd die Erfinderliga beschwert sich darüber, dass alle meine Erfindungen in die Luft fliegen. Natürlich tun sie das! Ha!", sourceObjectiveStatus = "unverified-source-field" }
quests[12824] = { id = 12824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosive Stimmung", description = "Ihr seid aber schnell, das muss ich schon sagen! Danke für die Hilfe mit dem Sprengstoff... ich habe schon seit geraumer Zeit darauf gewartet, diese Erfindung mal richtig zu testen!\n\nGeht zu Ricket und berichtet ihr, dass wir nun keine Probleme mehr mit den Magnatauren haben sollten... meine Pioniere werden sich um die restlichen kümmern.\n\nDanke vielmals!", sourceObjective = "Begebt Euch zu Ricket am K3.", completion = "Ihr habt alles in die Luft gejagt? So wird's gemacht! Ich wette, dass Gino großen Spaß dabei hatte!\n\nWir sind sehr dankbar für Eure große Hilfe, {name}. Wie wäre es im Gegenzug mit einem Geschenk?", sourceObjectiveStatus = "unverified-source-field" }
quests[12825] = { id = 12825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Zeichen des Dankes" }
quests[12826] = { id = 12826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leicht instabil", description = "Fantastisch!\n\nNein, nicht Ihr... meine neuen Minen. Ihr seid schon etwas eingebildet, wie? Ich allerdings bin absolut brillant! Mein Intellekt ist unerreicht.\n\nÜber was hatten wir nochmal gesprochen? Ach ja, meine neuen Minen! Neu und verbessert... bereit für jede hinterhältige Idee, die Ricket wieder ausgeheckt haben mag.\n\nSeid doch bitte so nett und bringt sie zu Ricket. Sie ist gleich da drüben... wird also keine allzu lange Reise werden. Seid jedoch vorsichtig, sie ist etwas durchgeknallt.", sourceObjective = "Liefert Jeers verbesserte Landminen bei Ricket am K3 ab.", progress = "Jeer ist fertig mit den Minen? Fein.", completion = "Hach, sind das nicht die süßesten kleinen Babys der Zerstörung, die es auf der Welt gibt?!", sourceObjectiveStatus = "unverified-source-field" }
quests[12827] = { id = 12827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rationen-Recycling", description = "Hey! Ein neues Gesicht! Wollt Ihr Ricket vielleicht zur Hand gehen?\n\nWir haben gerade ein etwas unerwartetes Problem... Nahrungsmangel. Ich weiß, ich weiß... wir hätten das voraussehen müssen, aber die Sache ist die: Hier kommen viele Pioniergruppen durch, die jedoch nicht allzu lange bleiben, weswegen wir uns normalerweise keine Sorgen um Langzeitverköstigungen machen müssen. Doch der gute, alte K3 scheint ja jetzt ziemlich gefragt zu sein.\n\nOb es eine bequeme Lösung gibt? Im Westen befinden sich einige Lager der Gnolle... und wie es Gnolle nun einmal so an sich haben, sind auch einige dort in der Gegend verstreut, auf der Suche nach Nahrung. Hättet Ihr etwas dagegen, ein paar ihrer Rationen zu stibitzen?", sourceObjective = "Ricket am K3 bittet Euch, 16 getrocknete Gnollmahlzeiten von den wilden Hügelgnollen in der Nähe zu beschaffen.", progress = "Ah, hallo! Mein Magen knurrt schon... wie ist es gelaufen?", completion = "Hoffentlich haben sie sich nicht allzu sehr geziert, als es darum ging, ihre Kostbarkeiten mit Euch zu teilen. Wir sind bisher immer ziemlich gnädig gewesen, wenn sie sich an unsere Reste gemacht haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12828] = { id = 12828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welch Eingebung!", description = "Huch, das Zeug ist bösartig! Vielleicht nicht für den Geschmack eines Gnolls oder so, aber ich dachte, dass, was auch immer sie hatten, wenigstens... essbar wäre?\n\nDann müssen wir eben kreativer sein.\n\nTore besitzt einen Sprengstoffspender nördlich der Stadt... nicht weit vom großen Höhleneingang, könnt ihn nicht übersehen. Ich bin sicher, sie hat den Sprengstoff für irgendwelche Grabungsarbeiten vorgesehen, aber ich habe eine bessere Idee.\n\nNehmt Euch etwas davon und bewerft damit eines der Mammuts in der Nähe... die meisten von ihnen halten sich im Westen auf. Sammelt das Fleisch und bringt es zurück.", sourceObjective = "Ricket auf dem K3 möchte, dass ihr ein I.D.S.V. besorgt, damit ein Mammut in die Luft jagt und 8 Stücke herzhaftes Mammutfleisch einsammelt.", progress = "Ich weiß, mein Plan war brillant. Macht Euch keine Sorgen.\n\nFühlt es sich in dieser Präsenz von Großartigkeit nicht wunderbar an? Ein bisschen kribbelnd vielleicht?", completion = "Und es ist bereits erledigt! Ich übertreffe mich zuweilen selbst.\n\nVielen Dank, Freund!", sourceObjectiveStatus = "unverified-source-field" }
quests[12829] = { id = 12829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einrücken", description = "He, Ihr! Heiß' Tore. Ich leite den Mineneinsatz hier auf dem K3... oder ich werde es in Kürze tun!\n\nDiese Höhle hier ist voller gruseliger Krabbelviecher. Ich glaube, wir könnten ein paar weniger Spinnen gebrauchen, bevor wir hineingehen - was meint Ihr?", sourceObjective = "Tore Rumpelschlüssel vor der Kristallnetzhöhle möchte, dass Ihr 12 Kristallnetzspinnen tötet.", completion = "Haha! Schön, dass Ihr nix gegen schmutzige Arbeit habt.\n\nBin echt dankbar, Kumpel!", sourceObjectiveStatus = "unverified-source-field" }
quests[12830] = { id = 12830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückgewinnung des Erzes", description = "Wir gehen hinein!\n\nAls wir ankamen, waren hier ein paar Schneebolde... Ihre Ausgrabungen scheinen jedoch kein glückliches Ende genommen zu haben. Nicht weiter wichtig - wir hätten sowieso bald übernommen.\n\nIch habe einige unserer Bergmänner hineingeschickt, um ein paar Erzproben zu sammeln, die ich zur Kalibrierung unserer Maschinen benutzen möchte, aber sie sind noch nicht zurückgekehrt.\n\nMacht es Euch was aus, da mal hineinzugehen und Eurerseits ein paar Proben für mich zu sammeln? Die Schneebolde besitzen vermutlich ein paar, obwohl ich glaube, dass die meisten von ihnen inzwischen tot sind.", sourceObjective = "Tore Rumpelschlüssel vor der Kristallnetzhöhle hätte gerne, dass Ihr 5 Proben unreines Saroniterz sammelt.", progress = "Habt Ihr'n bisschen Erz für mich?", completion = "Huh, das ist vielleicht ein Gestank! Ihr hattet'n kleines Handgemenge mit diesen Schneebolden, oder?\n\nFinde ich aber gut!", sourceObjectiveStatus = "unverified-source-field" }
quests[12831] = { id = 12831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur teilweise vergessen", description = "Urgh... es fühlt sich an, als hätte ich einen Propeller im Magen.\n\nIch glaube, ich kann gehen, aber seitdem ich im hinteren Teil der Höhle von etwas gebissen wurde, hat sich was ziemlich Bösartiges in meinem Körper ausgebreitet. Die Spinne war größer als die anderen... und sie war auffällig gefärbt.\n\nRicket kann mir vermutlich ein Gegengift brauen, doch sie braucht den Giftbeutel von der, die mich da gebissen hat. Würde es Euch etwas ausmachen, sie für mich zu finden? Ich glaube nicht, dass Tore kommt.\n\nIch stelle mich hier einfach tot und hoffe, dass sie mich in Ruhe lassen.", sourceObjective = "Ein verletzter Goblinminenarbeiter in der Kristallnetzhöhle möchte, dass Ihr ihm einen Eisspitzengiftbeutel von einer Eisspitzenspinne bringt.", progress = "<Der verletzte Goblinminenarbeiter krümmt sich vor Schmerzen.>", completion = "Das sollte reichen... Ich hoffe, Ricket kann mir etwas zusammenmischen. Also, bereit zum Aufbruch?", sourceObjectiveStatus = "unverified-source-field" }
quests[12832] = { id = 12832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bittere Trennung", description = "He da - danke Euch! Ich dachte schon, dass ich Futter für die Spinnen werden würde. Aber man sollte sich nicht zu früh freuen - lasst uns hier verdammt nochmal verschwinden!\n\nSagt mir Bescheid, sobald Ihr bereit seid... Beeilt Euch.", sourceObjective = "Begleitet den verletzten Goblinminenarbeiter aus der Kristallnetzhöhle und meldet Euch danach bei Ricket in K3.", completion = "Danke, dass Ihr unserem Minenarbeiter dort geholfen habt, {name}! Ein Gegengift zu mischen dürfte kein großes Problem darstellen.\n\nWenn Ihr Tore wieder trefft, richtet ihr doch bitte aus, dass sie verrückt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[12833] = { id = 12833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überbestand", description = "Ah, hallo! Ihr seid nicht wie alle anderen Abenteurer davongelaufen? Ihr seid einfach ein Schatz, wie? Ich habe mich schon gefragt, ob ich komisch rieche!\n\nWir könnten hier immer noch etwas Hilfe gebrauchen und Ihr seid genau <der/die> Richtige dafür. Könnt Ihr Euch an diese Magnatauren erinnern? Nun ja, anscheinend ist die Höhle nicht ganz eingestürzt... es sind also noch immer ziemlich viele übrig. So viel zu \"Gino hat sich um sie gekümmert\", wie?\n\nZum Glück hat Jeer mehr als genug Minen hergestellt. Ihr habt verstanden!", sourceObjective = "Ricket in K3 wünscht, dass Ihr mithilfe der verbesserten Landminen Garms Bann vor den Angreifern verteidigt. Zu den Angreifern zählen Garmeindringlinge sowie schneeblinde Anhänger.", completion = "Ich mag Euch. Genau genommen seid Ihr super!\n\nEin Hoch auf {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[12834] = { id = 12834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weder Regen noch Schnee noch explodierender Flieger" }
quests[12835] = { id = 12835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voll ausgewachsen" }
quests[12836] = { id = 12836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen der Dankbarkeit", description = "Ich hätte genau die richtige Arbeit für einen eifrigen Neuling! Wir haben ein Gnollproblem. Man könnte es sogar Gnollplage nennen! Wirklich lästige Kreaturen. Es kommen immer mehr von ihnen angekrochen. Mittlerweile sind sie schon hier und klauen unsere Teile! Unfassbar!\n\nAnfang und Ende dieses Problems ist ihr dreister Anführer, Knarzfell. Ich will, dass Ihr Euch um das \"Ende\" kümmert. Stattet ihm in seinem Lager in den Blendschneehügeln weit draußen im Westen einen Besuch ab.\n\nUnd wenn ich sage \"Besuch abstatten\", meine ich damit \"ihn grausam töten\". Alles klar? Alles klar!", sourceObjective = "Ricket am K3 möchte, dass Ihr Knarzfell tötet.", progress = "Ich mag Ricket, weil sie soooo lecker ist!\n\nOh, willkommen zurück! Wie sieht es mit der Schädlingsbekämpfung aus?", completion = "Echt stark! Ihr seid genau mein {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12837] = { id = 12837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tore hat die Waren", sourceObjective = "[PLACEHOLDER] Meldet Euch bei Tore", sourceObjectiveStatus = "unverified-source-field" }
quests[12838] = { id = 12838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Informationsbeschaffung", description = "Ich muss wissen, was der Scharlachrote Ansturm heute plant. Ihr werdet mir in dieser Sache helfen.\n\nFliegt zum Hafen des Ansturms, durchwühlt die Truhen dort und sucht nach Dokumenten. Sie werden verschlossen sein, tut also alles, was nötig ist, um an die Schlüssel der Anhänger des Scharlachroten Ansturms heranzukommen.", sourceObjective = "Aurochs Grimmbann auf der Todesanhöhe möchte, dass Ihr 5 Geheimdokumente des Ansturms beschafft.", progress = "Habt Ihr die Informationen?", completion = "Gebt sie mir. Ich werde sie durchgehen und nur das Wichtigste heraussuchen. Wenn ich etwas gefunden habe, werde ich mich bei Euch melden.\n\nKommt so oder so morgen wieder. Es ist allgemein bekannt, dass sie jeden Tag ihre Pläne ändern.", sourceObjectiveStatus = "unverified-source-field" }
quests[12839] = { id = 12839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Plan (des Admirals)", description = "Auf den ersten Blick gleicht diese Notiz jeder anderen Botschaft, nach der Ihr gesucht habt; doch nachdem Ihr ihren Inhalt kurz überflogen habt, seid Ihr vom Gegenteil überzeugt.\n\nDer Brief besagt, dass sich Großadmiral Westwind irgendwo auf der Insel aufhält, sich momentan aber zurückgezogen hat. Er schreibt von einem glorreichen Tag, der bald anbrechen wird und an dem der Scharlachrote Ansturm zuerst über den Lichkönig und danach über den Rest der Welt kommen wird, um endlich wieder Ordnung nach Azeroth zu bringen.\n\nDer Lordkommandant wird das sofort sehen wollen!", sourceObjective = "Bringt dem Lordkommandanten Arete auf der Todesanhöhe die Nachricht vom Großadmiral.", progress = "Der Bericht des Scharlachroten Ansturms muss zu Aurochs Grimmbann gebracht werden.\n\n<Der Lordkommandant sieht Euch erwartungsvoll an - damit seid Ihr entlassen.>", completion = "Eine Nachricht von Westwind? Warum sagt Ihr das nicht gleich?\n\n<Arete reißt Euch den Brief aus der Hand, um ihn zu lesen.>\n\nDieser Narr! Er ist wirklich hier?!\n\n<Der Lordkommandant lacht.>\n\nDas sind neue Nachrichten. Ich frage mich nur: Wie gedenkt er, die Welt zu erobern, nachdem er den Lichkönig gestürzt hat? Was nicht heißt, dass er etwas davon auch nur in seinen wildesten Träumen erreichen könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[12840] = { id = 12840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Streng vertraulich", description = "Wenn jemand weiß, wo sich der Admiral aufhält, dann sicherlich seine Kapitäne auf den Schiffen im Hafen des Ansturms.\n\n<Der Lordkommandant reibt sich die Hände.>\n\nWenn ich mich recht entsinne, lauten ihre Namen Welsington und Hartford. Prügelt die Information aus ihnen heraus und macht danach ihrem kümmerlichen Leben ein Ende.\n\nIch will wissen, wo sich der Großadmiral versteckt!", sourceObjective = "Lordkommandant Arete auf der Todesanhöhe möchte, dass Ihr Informationen aus den Kapitänen Welsington und Hartford herausprügelt.", completion = "Sie haben Landgren wieder erweckt? Dann ist er es, der den Aufenthaltsort des Großadmirals kennt!", sourceObjectiveStatus = "unverified-source-field" }
quests[12841] = { id = 12841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Handel der Alten", description = "Ja, es muss der kleine grüne Gefangene sein, den Ihr meint... Eventuell können wir uns gegenseitig helfen.\n\nMit Gewalt kriegt Ihr den Goblin hier nicht raus, zumindest nicht lebendig.\n\nBei meinen Leuten bin ich als Yrkvinn die Illusionistin bekannt. Wie Ihr sehen könnt, haben mich die Hyldnir gefangen genommen.\n\nHätte ich meine Runen, dann könnte ich dafür sorgen, dass Ihr Euch hier ungesehen bewegen könnt. Tiefer im Berg findet Ihr eine Aufseherin namens Syra, die in den Minen patrouilliert. Sie hat meine Runen. Nehmt sie ihr ab, dann reden wir weiter.", sourceObjective = "Lok'lira die Greisin in der Verlassenen Mine möchte, dass Ihr Yrkvinns Runen von Aufseherin Syra holt.", progress = "Meine Runen, {name}? Habt Ihr sie?", completion = "Ich war mir nicht sicher, ob Ihr zurückkommen würdet. Der Gedanke daran, was aus mir werden würde, wenn ich zu lange hier bliebe, machte mir schon Angst.", sourceObjectiveStatus = "unverified-source-field" }
quests[12842] = { id = 12842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runen schmieden: Vorbereitung auf den Kampf", description = "Das Zeichen des Krieges ist für immer in Eure Seele gebrannt, Todesritter. Ihr habt die dunkle Kunst des Runenschmiedens erlernt und könnt nun Runen der Macht in Eure Waffen prägen.\n\nBereitet Euch auf den Kampf vor. Kehrt zu einer der Runenschmieden hier im Herzen von Acherus zurück und bedient Euch der neugewonnenen Kunst, um Eure Waffe mit einer Rune der Macht zu versehen!\n\nKehrt zu mir zurück, sobald Eure Klinge vor dunkler Energie leuchtet!", sourceObjective = "Instrukteur Razuvious in der Schwarzen Festung befiehlt Euch, mithilfe Eurer Fertigkeit 'Runen schmieden' eine beliebige Rune in Eure runenbeschriebene Seelenklinge zu prägen.\n\nIhr könnt die Prägung auf Eurer Waffe jederzeit durch eine andere ersetzen, solange Ihr Euch in der Nähe einer Runenschmiede befindet.", progress = "Verschwendet nicht meine Zeit, {name}. Wir stehen am Rande einer Apokalypse!", completion = "Merkt Euch diese Worte, {class}: Die Runenschmiede ist ein Instrument der Geißel. Es gibt sie nur in Acherus, Naxxramas und im Herzen der Eiskrone! Ihr könnt Eure Waffen nur an einer Runenschmiede mit Prägungen versehen.\n\nKehrt noch oft zurück, um all Eure Waffen mit Runen zu versehen. Ein {class} muss auf alles vorbereitet sein, das sich ihm in den Weg zu stellen wagt!", sourceObjectiveStatus = "unverified-source-field" }
quests[12843] = { id = 12843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie haben unsere Männer!", description = "Ihr müsst uns helfen! Wir führten gerade eine Expedition in die Berge durch, um einen Übertragungsturm aufzustellen, als wir angegriffen wurden.\n\nSie sahen aus wie Vrykul, nur dass ihre Haut blau und eisbedeckt war... und es waren nur Frauen! Sie nahmen alle Männer der Expedition mit und ließen uns Frauen gehen. Bitte, {name}! Wir vermuten, dass sie in Sifreldar, dem Dorf oberhalb von K3, festgehalten werden.", sourceObjective = "Gretchen Zischelfunken möchte, dass Ihr nach Sifreldar geht und 5 Goblingefangene befreit.", completion = "Ihr habt es geschafft! Unsere Männer sind zurück!", sourceObjectiveStatus = "unverified-source-field" }
quests[12844] = { id = 12844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausrüstungsbergung", description = "Bitte, {name}. Als die Hyldnir unsere Männer entführten, nahmen sie auch unsere gesamte Ausrüstung mit. Es ist natürlich viel wichtiger, dass wir unsere Männer wiederbekommen, aber wenn Ihr auf Ausrüstungsgegenstände stoßen solltet, wäre ich Euch sehr dankbar, wenn Ihr sie uns zurückbringen könntet.\n\nIhr findet ihr Dorf direkt über uns im Norden.", sourceObjective = "Gretchen Zischelfunken möchte, dass Ihr 8 Teile der K3-Ausrüstung aus Sifreldar holt, das nördlich des K3 liegt.", progress = "Was macht unsere Ausrüstung, {name}?", completion = "Danke, {name}! Mal sehen, was wir mit diesen Teilen noch anfangen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[12846] = { id = 12846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst keinen Goblin zurück", description = "Alle unsere Männer sind zurück... dank Euch, {name}! Nun... alle bis auf einen.\n\nMein Bruder Zeev ist laut den anderen immer noch da oben. Offenbar gibt es dort eine Art Mine, in der die Gefangenen arbeiten müssen. Geht dorthin und seht nach, ob Ihr etwas herausfinden könnt.", sourceObjective = "Findet den Eingang zu den Verlassenen Minen im Norden von Sifreldar und sucht nach Hinweisen auf Zeev Zischelfunkens Aufenthaltsort.", completion = "Ihr gehört definitiv nicht zu den Hyldnir... warum seid Ihr also hier? Ah... Ihr sucht bestimmt nach dem neuen Gefangenen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12847] = { id = 12847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zweite Chancen", description = "Ich hörte, sie hätten einen Erzbischof in ihrer Kathedrale, aber ich hatte ja keine Ahnung, dass sie Landgren wiedererweckt und befördert haben! Die Kathedrale wird schwer bewacht und hat nur einen Eingang, also werdet Ihr Hilfe brauchen.\n\nWir müssen immer noch erfahren, wo sich der Großadmiral aufhält, doch dieses Mal gehen wir kein Risiko ein!\n\nNehmt dieses Gerät. Damit seid Ihr in der Lage, für mich ein Portal zu beschwören, sobald Ihr den Erzbischof getötet habt.\n\nIch hole mir meine Antworten direkt von seiner unterworfenen Seele! Wir werden Großadmiral Westwind finden!", sourceObjective = "Tötet Erzbischof Landgren und beschwört anschließend Aretes Tor in Gegenwart seiner Leiche. Sprecht mit Lordkommandant Arete im Hafen des Ansturms, sobald er sein Verhör mit dem Geist des Erzbischofs beendet hat.", progress = "Ja?", completion = "Verborgene Höhlen auf der Rückseite der Insel. Wie überaus interessant.\n\nNun, wenigstens weiß ich jetzt, wo sich alle meine vermissten Spione befinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12848] = { id = 12848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der endlose Hunger", description = "Schon bald, {class}, wird sich der unaufhörliche Hunger Eurer bemächtigen - und wenn dies geschieht, werdet Ihr gewaltige Schmerzen erleiden. Es gibt nur ein Heilmittel gegen das Leid: Der Hunger muss gestillt werden.\n\nIch gebe Euch den Schlüssel, der Eure Erlösung sein wird.\n\nDiejenigen, die der dunklen Bruderschaft unwürdig sind, werden ans Herz von Acherus gekettet. Befreit mithilfe des Schlüssels einen unwürdigen Initianden. Erlaubt ihm, seine Ausrüstung zu tragen und mit Euch um seine Freiheit zu kämpfen. Tötet: und der Schmerz wird aufhören. Versagt: und Ihr werdet für alle Ewigkeit leiden müssen.\n\nLebt oder sterbt - die Wahl liegt bei Euch.", sourceObjective = "Instrukteur Razuvious in der Schwarzen Festung befiehlt Euch, einen unwürdigen Initianden zu befreien und ihn kaltblütig umzubringen!\n\nEntweder ist es Euer oder ihr Leben!", progress = "Zwei Leben, ein Schlüssel... Enttäuscht mich nicht, {name}.", completion = "Wie erwartet: Mein auserwählter Ritter hat den Sieg davongetragen! Ihr seid nun bereit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12849] = { id = 12849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Blutes, des Frosts und der unheiligen Kraft", sourceObjective = "In den Hallen des Befehls findet Ihr die Schulen des Bluts, des Frosts und der unheiligen Kraft. Jede dieser Schulen hat einen Lehrer, der Euch mit Wissen der verschiedenen dunklen Künste versorgen kann.\n\nIch, Lord Thorval, bin der Direktor der Schule des Blutes. Lady Alistra herrscht über die Schule der unheiligen Kraft und der Erzlich Amal'thazad über die des Frosts.\n\nIhr müsst jedes Mal wieder hierherkommen, wenn Ihr mehr Macht erlangt habt, und trainieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[12850] = { id = 12850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch bei Geißelkommandant Thalanor", description = "Geißelkommandant Thalanor erwartet Eure Ankunft. Ihr findet ihn auf dem Überhang direkt südöstlich unserer derzeitigen Position. Meldet Euch bei ihm und verlangt nach einem Geißelgreifen, der Euch dann zur Todesbresche bringen wird.\n\nPrinz Valanar wird unten auf Euch warten.\n\nLeidet wohl, <Bruder/Schwester>!", sourceObjective = "Meldet Euch beim Geißelkommandanten Thalanor auf dem Balkon auf der ersten Ebene der Schwarzen Festung.", completion = "Der Krieg hat begonnen, {class}! Ich werde Euch meinen besten Greifen zur Verfügung stellen - er wird Euch zur Todesbresche bringen. Chaos, Tod und Zerstörung! Dies alles werdet Ihr einläuten - und noch vieles mehr!", sourceObjectiveStatus = "unverified-source-field" }
quests[12851] = { id = 12851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eiskalte Jagd", description = "Die Prüfung wartet, Frau!\n\nBesitzt Ihr das Herz einer Kriegerkönigin? Oder das einer jammernden Näherin?\n\nHabt Ihr einmal Krieg geschmeckt, werdet Ihr die Antwort wissen.\n\nIhr könnt Eure Mutter anlügen, Eure Schwestern und sogar Euch selbst, doch das Schlachtfeld fördert immer die wahre Natur zutage.\n\nWenn Ihr Eure Vorbereitungen abgeschlossen habt, setzt Euch auf Eiszahn und reitet in die Schlacht. Von seinem Rücken aus müsst Ihr den Regen des Todes auf unseren Feind darniederprasseln lassen!", sourceObjective = "Brijana in Brunnhildar möchte, dass Ihr Eiszahn benutzt und 7 Frostworge und 15 Frostriesen im Uralten Wintertal tötet.", progress = "Habt Ihr die Schlacht überlebt, {name}?", completion = "Vielleicht besitzt Ihr wirklich das Herz einer Kriegerin.\n\nDie Zeit wird es zeigen...", sourceObjectiveStatus = "unverified-source-field" }
quests[12852] = { id = 12852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Admiral aufgespürt", description = "Als Hochgeneral Abbendis in Neuherdweiler konfrontiert wurde, schützte sich der Großadmiral selbst vor seiner Flucht mit einer undurchdringlichen Magiesphäre.\n\nIch bin besonders erfahren im Zunichtemachen von Magie.\n\nNehmt dies, um es gegen ihn in der Versteckten Senke einzusetzen, wenn er seine Sphäre erneut herbeiruft. Ich wünschte, ich könnte dabei sein, um seinen Gesichtsausdruck zu sehen.\n\nErledigt ihn.", sourceObjective = "Lordkommandant Arete möchte, dass Ihr Euch um Großadmiral Westwind kümmert. Kehrt danach zum Lordkommandanten auf die Todesanhöhe zurück.", completion = "MAL'GANIS?!\n\n<Der Lordkommandant lacht hemmungslos.>\n\nDie Narren wurden schon wieder von Dämonen überwältigt und jetzt sind sie vernichtet!\n\nIch vertraue darauf, dass mein liebster {class} lange genug bei uns bleibt, um dabei zu helfen, den Rest von ihnen auszuschalten? Vielleicht kann Euch etwas hiervon überzeugen?", sourceObjectiveStatus = "unverified-source-field" }
quests[12853] = { id = 12853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luxusreise!", description = "Hallo, <Kumpel/Süße>!\n\nMögt Ihr Spannung und Explosionen?! Wer mag das nicht? Ich kenne genau den richtigen Ort für Euch. Unten bei K3, dem Luxusziel schlechthin, erfinden sie immer neue innovative Sachen und Wege, wie man andere Sachen in die Luft jagen kann! Klingt spannend, was? Falls Ihr bei dem Spaß mitmachen wollt, dann macht Euch noch heute auf den Weg dorthin und sprecht mit Jeer Funksockel!\n\nObligatorische Ausschlussklausel: Zur Teilnahme an oben angedeuteter \"Spannung\" kann unter Umständen körperliche Arbeit vonnöten sein.", sourceObjective = "Sprecht mit Jeer Funksockel am K3 in den Sturmgipfeln.", completion = "Willkommen in K3!\n\nWir sind hier, um zu diesen Gipfeln vorzudringen und einen guten Anteil dieser erstaunlichen Titanenmaschinen in die Finger zu bekommen. Jedoch haben wir in dieser Hinsicht relativ wenig Fortschritte gemacht. Gnolle, Schneebolde, Magnatauren... es ist genug für jedermann da... geschweige denn, dass wir irgendeinen unserer Flieger in der Luft halten können, ohne dass ihre Motoren gleich einfrieren.\n\nJedoch gibt es genug Arbeit zu tun - Ihr helft mit, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[12854] = { id = 12854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Branns Spuren", description = "Nach der Entdeckung von Branns Tagebuch in den Grizzlyhügeln fanden wir nur noch eine einzige Nachricht von Brann. Eine mysteriöse Notiz tauchte im Hauptquartier der Forscherliga auf, ohne Hinweis auf ihren Ursprung. Sie besagte nur, dass wir Brann in seinem Lager treffen und ihm bei seiner Suche helfen sollten.\n\nMeiner Meinung nach müsste sich das Lager nordöstlich von hier befinden, jenseits von Bors Atemstrom und am Fuße einiger Ruinen vom Pfad der Titanen.", sourceObjective = "Beschafft die in Sackleinen gewickelte Notiz aus Branns Lager und bringt sie zu Archäologe Andorin in der Eisfestung.", progress = "Habt Ihr Branns Lager gefunden?", completion = "<Archäologe Andorin blickt Euch erwartungsvoll an.>\n\nIhr solltet eigentlich mit Brann zurückkehren, nicht mit einem Stück Papier. Was ist hier los?", sourceObjectiveStatus = "unverified-source-field" }
quests[12855] = { id = 12855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Täter ausschnüffeln", description = "Der Tonfall von Branns Notiz lässt vermuten, dass er etwas mit der Notiz vergraben wollte, möglicherweise eine Art Bündel. Seid Ihr sicher, dass Ihr nicht mehr gefunden habt?\n\nGut, dann müsst Ihr einen der Frosthunde mitnehmen, die die Frosterben zum Fährtenlesen nutzen. Bringt ihn zum zerstörten Lager und lasst ihn Branns Spur aufnehmen.\n\nEr sollte Euch zumindest dorthin führen, wo Ihr seine verschwundenen Habseligkeiten finden könnt, und mit etwas Glück sogar zu Brann selbst.", sourceObjective = "Nutzt das Frosthundhalsband im Verlassenen Lager um herauszufinden, wer Branns Habseligkeiten an sich genommen hat. Wenn Ihr sie finden konntet, setzt das Kommunikationsgerät ein und sprecht mit wem auch immer Ihr Kontakt bekommt.", progress = "Wer seid Ihr?", completion = "Ihr... Ihr seid kein Mitglied der Forscherliga, so weit ich weiß. Aber Ihr habt den Kommunikator gefunden, daher müssen sie Euch geschickt haben. Gut, das ist fast das, was ich erhofft hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[12856] = { id = 12856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaltherzig", description = "Einen ehrenhaften Tod auf dem Schlachtfeld zu finden, bringt uns allen Ruhm; in einem Eisblock eingefroren zu sein und auf ewig verspottet zu werden, tut dies nicht...\n\nIhr sollt zur Stadt der Frostriesen Dun Niffelem fliegen, die gleich östlich des Uralten Wintertals liegt, und unsere gefangenen Protodrachen befreien. Mit ihrer Hilfe werdet Ihr dann die gefrorenen Fesseln unserer Schwestern lösen und sie sicher nach Hause bringen können.\n\nNehmt Euch jedoch vor den Keulen der Riesen in Acht, Schwester, wenn Ihr nicht zu den Gefangenen zählen wollt.", sourceObjective = "Befreit 3 gefangene Protodrachen und 9 gefangene Brunnhildar.", progress = "War Eure Mission erfolgreich, Schwester?", completion = "Eure Mühen scheinen sich gelohnt zu haben, Schwester.\n\nIhr habt den Brunnhildar zu Ruhm verholfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12857] = { id = 12857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Rachmähnes Flosse", description = "Von Häuptling Zornklaue:\n\nGetreuer Seelöwe von Häuptling Zornklaue Rachmähne hat Hand gebissen, die es füttern wollte. Zornklaue sagt, dass Rachmähne zu nichts nutzt wegen Drakurutrolle. Häuptling Zornklaue sehr traurig sein, dass er bitten muss, dass Rachmähne getötet wird und seine Flosse als Beweis zurückgebracht wird.\n\nIhr finden Rachmähne im Südosten bei Zornklauensee.\n\nHäuptling Zornklaue leid tun, wegen schlechtem Geschreibe. Das erste Mal, dass ich eines dieser Dinger benutze und Häuptling Zornklaue ist Wolvar, nicht Menschenwesen.", sourceObjective = "Beschafft Rachmähnes Flosse und bringt sie zu Häuptling Zornklaue in der Lichtbresche in Zul'Drak.", progress = "Armer Rachmähne. Er war Geschenk von Schwager.", completion = "<Häuptling Zornklaue weint.>\n\nHatte Rachmähne schon, seit er ein kleiner Heuler. Trauriger Tag für Zornklaue. Zuerst Troll hat Zornklaue angegriffen, dann er machen Rachmähne schlecht. Zornklaue nie mehr mit Troll handeln, nie mehr!", sourceObjectiveStatus = "unverified-source-field" }
quests[12858] = { id = 12858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Puzzleteile", description = "Dem Licht sei Dank, dass jemand meine Nachricht erhalten hat. Nun, da ich vor den Eisenzwergen sicher bin, muss ich Euch erneut um Eure Hilfe bitten. Ich habe einen Hinweis auf Norgannons Schlüsselstein, der den Zugang zu Ulduars Archiven bewacht, jedoch von den Titanen in zwei Stücke geteilt und versteckt wurde.\n\nEines der Stücke, die Hülle des Schlüsselsteins, wird in der Bibliothek des Erfinders an der Nordküste südlich von Ulduar aufbewahrt. Als Erstes müsst Ihr jedoch die Fragmente einer alten Zugangsscheibe von den Wächtern der Bibliothek beschaffen.", sourceObjective = "Sucht 6 Fragmente der Scheibe des Erfinders und setzt sie damit wieder zusammen.", progress = "Konntet Ihr die Scheibe zusammensetzen?", completion = "Wunderbar! Da wir die Scheibe jetzt haben, müsst Ihr damit das Gewölbe des Erfinders öffnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12859] = { id = 12859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Allerneueste: Feuer noch immer heiß!", description = "Trolle greifen Zornklauenbau an und schmeißen Zornklaue raus! Doch es kommt noch schlimmer: Trolle brennen jetzt Dorf! Das sehr schlecht. Häuptling hat Schamanen der Zornklauen namens Moky befohlen, Feuer zu untersuchen. Ergebnisse sehr überraschend! Feuer noch immer heiß und kann Sachen anzünden.\n\nWerdet Ihr den Zornklauen helfen und das Feuer ausmachen? Moky hat speziellen Feuerlöscher der Zornklauen für Euch. Benutzt speziellen Feuerlöscher, um Feuer im Zornklauenbau gen Südosten zu löschen. Muss manchmal oft sprühen, damit Feuer ausgeht, doch Löscher immer Wasser haben! Zornklauenmagie sehr stark!", sourceObjective = "Schamanenältester Moky in der Lichtbresche in Zul'Drak möchte, dass Ihr mithilfe des Feuerlöschers der Zornklauen 15 Hüttenfeuer im Zornklauenbau löscht.", completion = "Es ist seltsam, weil ich weiß, dass Ihr Feuer ausgemacht, doch Feuer brennen noch immer. Vielleicht dieses Ding doch nicht so gut, was? Doch Moky Euch für Eure Arbeit bezahlen! Hoffentlich Trolle brennen auch!", sourceObjectiveStatus = "unverified-source-field" }
quests[12860] = { id = 12860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daten schürfen", description = "Diese Scheibe, die Ihr zusammengebaut habt... sie ist leer! Dieser gerissene Mimir muss die Informationen irgendwo anders versteckt haben. Seht Euch in der Bibliothek des Erfinders um, sind dort irgendwelche Datenbanken?\n\nVielleicht ist es das, was Ihr mit der Scheibe machen müsst. Versucht, sie in der Nähe einer dieser Datenbanken einzusetzen. Vielleicht kann man darauf die Informationen speichern. Meldet Euch erneut bei mir, wenn Ihr das ausprobiert habt, und lasst mich wissen, was Ihr herausfinden konntet. In der Zwischenzeit werde ich versuchen, die andere Hälfte des Archivschlüssels zu finden.", sourceObjective = "Nutzt die Scheibe des Erfinders, um 7 Teile der versteckten Daten aus den Datenbanken zu beschaffen.", progress = "Habt Ihr die Scheibe ausprobiert? Was habt Ihr gefunden?", completion = "<Brann sieht die Scheibe in Eurer Hand an.>\n\nIch weiß nicht, ob darauf etwas gespeichert ist oder nicht! Ihr müsst mir sagen, was passiert ist.\n\n<Ihr beschreibt den Datenwiederherstellungsprozess.>\n\nEs hat also funktioniert? Zumindest kann man sich darauf verlassen, dass Mimir systematisch vorgeht. Nach allem, was ich gehört habe, könnte ich das über die anderen Bewahrer jedoch nicht behaupten...", sourceObjectiveStatus = "unverified-source-field" }
quests[12861] = { id = 12861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Trolle sind durchgedreht!", description = "Drakuru... Ihr wisst, wer dieser Troll ist? Ich denke, dass böse Trolle von Troll namens Drakuru kontrolliert werden. Sie nennen sich Drakurutrolle - deswegen weiß ich das. Nun Ihr sehen, wieso ich Häuptling der Zornklauen. Klügster aller Wolvar!\n\nDoch das nicht der Grund, weshalb ich mit Euch jetzt sprechen. Böse Trolle gekommen und Zornklauen aus Bau geschmissen. Doch Zornklauen, die nicht weglaufen, werden jetzt als Gefangene in Dorf gehalten. Ihr gehen zu Zornklauenbau im Südosten und befreit gefangene Zornklauen. Tötet Trolle für Schlossöffner. Ihr vielleicht töten viele Trolle für viele Schlossöffner.", sourceObjective = "Häuptling Zornklaue in der Lichtbresche in Zul'Drak möchte, dass Ihr mithilfe der \"Schlossöffner\" von Drakuru, welche die verschiedenen Drakurutrolle bei sich tragen, 8 gefangene Zornklauen befreit.", completion = "Zornklaue Euch danken, {name}. Doch Zornklauenbau wahrscheinlich für immer verloren und Freundschaft mit Trolle auch für immer verloren... und wenn ich denken, mir einfallen, dass Rachmähne auch für immer verloren. Auch Schwager weg. Hrm, Ihr haben Häuptlings Frau gesehen? Ich glaube, sie auch weg.\n\nVielleicht Ihr jetzt gehen. Häuptling ein wenig deprimiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[12862] = { id = 12862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn alles andere versagt", description = "Also... also ich denke nicht, dass wir in diesen Bergen gut Fuß fassen werden.\n\nGlaubt mir, ich bin sicherlich niemand, der schnell aufgibt... doch wenn ich an gefrorene Motoren, gemeine Vrykulweiber, territoriale Möchtegerndrachen und das halbe Dutzend anderer Widerlinge in der Gegend denke, dann muss ich wirklich sagen: daraus wird nichts.\n\nLasst Euch davon jedoch nicht entmutigen! Nur weil wir nicht Fuß fassen können, heißt das noch lange nicht, dass wir Euch nicht dorthin bekommen werden... Reisen ohne Wiederkehr sind ziemlich einfach, wenn man die Sache nur richtig angeht.\n\n<Ricket deutet mit einem Nicken in Richtung einiger in der Nähe befindlicher Raketen.>", sourceObjective = "Sprecht mit Ricket, um mithilfe von Rickets D16-angetriebenem Lieferungsgerät tiefer in das Gebiet der Sturmgipfel vorzudringen.", completion = "Au! Das sah schmerzhaft aus. Aber es war ein ziemlich beeindruckender Auftritt, Bursche!\n\nWillkommen in der Eisfestung! Seid Ihr hier, um uns zu helfen, einen Weg nach Eiskrone zu finden?", sourceObjectiveStatus = "unverified-source-field" }
quests[12863] = { id = 12863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Danksagung", description = "Ah! Danke, dass Ihr gekommen seid, <Kamerad/Fräulein>.\n\nAngesichts Eurer großen Augen und zitternden Hände würde ich vermuten, dass Ihr noch nicht lange hier seid. Da wäre es wohl angebracht, dass Ihr unsere freundlichen Gastgeber kennenlernt!\n\nWir haben einige zusätzliche Heilvorräte... ehrlich gesagt, hatten wir nicht erwartet, derart bequem unterzukommen. Geht voraus, gebt Glorthal dort drüben diese Kiste und helft ihm, wenn's geht. Wir wollen ja nicht, dass sie uns für undankbar halten, wo sie uns doch mit derart offenen Armen empfangen haben.", sourceObjective = "Bringt Glorthal Steifbart in der Eisfestung die Kiste mit Heilvorräten.", progress = "Hallo.", completion = "Heilvorräte? Vielen Dank! Ich weiß zwar ehrlich gesagt nicht genau, was ich damit anfangen soll, aber sie werden uns gewiss nützlich sein.\n\nEs freut mich, Euch kennenzulernen... Euer Volk ist wirklich sehr unterschiedlich. Wir bekommen hier oben nicht sehr oft Besuch - und es ist schön, mal ein paar neue Gesichter zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12864] = { id = 12864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisste Späher", description = "Da Ihr schon mal hier seid: Es gibt da etwas, bei dem ich Eure Hilfe gebrauchen könnte.\n\nEinige unserer Späher sind schon seit geraumer Zeit nicht mehr zurückgekehrt. Die Gipfel sind eine unwirtliche Gegend... doch die Jungs wissen, was sie tun.\n\nGeht nach Osten... sie sollten sich entlang des Tals namens Bors Atem und in der Nähe von Bors Sturz befinden... in dieser Richtung jedenfalls. Solltet Ihr irgendeinen von ihnen finden, dann muss ich sofort davon erfahren. Wir haben einige Feinde in der Gegend - falls irgendwer von denen ein wenig dreist werden sollte. Besser zu viel vorgewarnt als zu wenig.", sourceObjective = "Glorthal in der Frostfestung hat darum gebeten, im Tal namens Bors Atem und bei Bors Sturz nach Anzeichen für die vermissten Späher der Frosterben zu suchen.", completion = "Wenn ein Späher so lange nicht zurückkommt... dann ist so etwas zu erwarten. Waren es die Harpyien?\n\nKönig Sturmherz lässt uns das ganze Jahr hart trainieren... er hat uns zu sehr guten Kämpfern gemacht. In Zeiten wie diesen verstehe ich, weshalb dies nötig ist. Er ist der weiseste und stärkste Anführer, den ich bis jetzt unter meinesgleichen gesehen habe... lasst Euch von seiner samtweichen Haut nicht täuschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12865] = { id = 12865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treue Gefährten", description = "Frischfleisch! Schön, Euch kennenzulernen! Ich hätte da etwas Arbeit für Euch, falls Ihr Zeit haben solltet.\n\nIm Osten liegen die Fußmarschen... eine ziemlich unwirtliche Gegend, doch es gibt dort ziemlich viele grasende Rhinozerosse. Unsere Vögel haben Geschmack an ihrem Fleisch gefunden, doch auf die Jagd zu gehen, ist bei all den in der Gegend nistenden Protodrachen immer etwas gefährlich für sie.\n\nFalls Ihr Lust habt, dann geht dorthin und besorgt ein wenig Rhinozerosfleisch, bringt es zurück zu den Gipfeln über uns und verfüttert es an die Adler, die dort nisten.", sourceObjective = "Fjorlin Frostbraue in der Eisfeste möchte, dass Ihr 8 Stück frisches Rhinozerosfleisch beschafft und es an die Sturmspitzenadler auf den Gipfeln über der Stadt verfüttert.", completion = "Schönen Dank... und ich bin mir sicher, dass die Adler auch ziemlich dankbar sind. Sie sind mächtige Verbündete und solange sie Euch wohlgesonnen sind, wird es Euch gut ergehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12866] = { id = 12866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Aggressoren Einhalt gebieten", description = "Verdammte Harpyien. Ich kann mich schon gar nicht mehr daran erinnern, wie oft wir die Viecher schon zu Kleinholz verarbeitet haben... und nach jedem Kampf geben sie für eine Weile Ruhe. Ich hatte gedacht, dass sie es dieses Mal verstanden hätten.\n\nDoch anscheinend nicht.\n\nIhr Gedächtnis mag vielleicht ein wenig kurz sein, doch wenn man genug von ihnen totschlägt, lassen sie einen in Ruhe. Würdet Ihr hinunter in die Täler gen Norden und Osten gehen und einen Großteil von ihnen beseitigen?", sourceObjective = "Glorthal Steifbart in der Eisfestung möchte, dass Ihr 8 Frostfederkreischerinnen und 8 Frostfederhexen tötet.", completion = "Es ist Drecksarbeit, ich weiß, doch wir sind Euch dafür dankbar. Was war nun noch mal der Name, den der Späher genannt hat... Sirana?", sourceObjectiveStatus = "unverified-source-field" }
quests[12867] = { id = 12867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Babydiebe", description = "Wenn Ihr noch vor ein paar Wochen nach oben geblickt hättet, hättet Ihr Dutzende dieser wunderschönen Adler durch die Lüfte gleiten sehen. Jetzt sieht man nur noch ein paar, wenn überhaupt. Sie bleiben jetzt fast die ganze Zeit bei ihren Nestern, weil die Harpyien einige ihrer Eier gestohlen haben.\n\nDie Harpyien haben Geschmack am Fleisch der Adler gefunden, wie es scheint... Die kranken Miststücke kümmern sich lange genug um die Eier, bis diese ausschlüpfen, um sich dann an den Jungen gütlich zu tun. Geht zu den Tälern im Norden oder Osten und findet die Eier... Bringt sie hierher und ich werde sie wieder zurück in die Nester legen.", sourceObjective = "Fjorlin Frostbraue in der Eisfeste möchte, dass Ihr 15 Eier eines Sturmspitzenadlers zurückbringt.", progress = "Wir werden uns um dieses Harpyienproblem kümmern... Die Adler werden schon bald wieder frei durch die Lüfte segeln können.", completion = "Sehr gut, {name}. Ihr macht Euch schnell Freunde.\n\nWenn Ihr bald wieder vorbeischaut, dann wird sich mit Sicherheit einer finden lassen, der Euch auf ihm reiten lässt... Sie sollten jetzt wissen, dass man Euch vertrauen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[12868] = { id = 12868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sirana Eisschrei", description = "Diese Sirana Eisschrei scheint diejenige zu sein, die die Harpyien zu noch mehr Aggressivität anstachelt. Ich vermute, dass sie ihre Angriffe bald einstellen werden, wenn wir ihr den Garaus machen.\n\nEiner unserer Sturmreiter behauptet, sie am Gipfel nordwestlich von hier gesehen zu haben. Findet das Weib und macht ihm ein Ende, ein für alle Mal.", sourceObjective = "Glorthal Steifbart in der Eisfestung möchte, dass Ihr Sirana Eisschrei tötet.", completion = "Es ist also vollbracht. Vielen Dank.\n\nIch habe mit Fjorlin gesprochen - er sagte, dass seine Männer die Harpyien unter Kontrolle halten werden. Solange wir sie im Auge behalten, werden sie nicht so schnell wieder den Mut haben, meine Leute anzugreifen.\n\nMir ist klar, dass das keine sehr angenehme Aufgabe war - nehmt dies als Zeichen meiner Anerkennung.", sourceObjectiveStatus = "unverified-source-field" }
quests[12869] = { id = 12869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu weit getrieben", description = "Ihr seid mit Loken dort gewesen, nicht wahr? Die Eisenzwerge haben Veranus, die Brutmutter der Protodrachen, gefangen genommen. Die Drachen scheinen nicht im Mindesten froh über die Situation zu sein... sie sind sehr aggressiv geworden.\n\nSie sind ins Sturmspitzengebiet eingedrungen und werden von den Adlern mit allen Mitteln bekämpft. Ihr wisst, auf welcher Seite wir stehen... Sie haben schon immer zu uns gehalten - es ist Zeit, den Gefallen zu erwidern.\n\nKönig Sturmherz hat mir diesen Hammer hinterlassen. Macht von ihm gut Gebrauch und seht zu, dass ich ihn wieder zurückbekomme.", sourceObjective = "Fjorlin Frostbraue in der Eisfestung möchte, dass Ihr auf einem Sturmspitzenadler 16 Sturmgipfelwyrms in den Fußmarschen niederstreckt.", progress = "Die Situation ist völlig außer Kontrolle geraten.", completion = "So wie ich das sehe, sind die Drachen nicht so leicht zu entmutigen. Schaut morgen wieder hier vorbei, falls Ihr Zeit haben solltet, um uns zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12870] = { id = 12870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Relikte", description = "Seid gegrüßt!\n\nBevor Ihr Eure große Suche, Euer großes Abenteuer antretet, könnte Ich Euch um einen kleinen Gefallen bitten, <Kamerad/Fräulein>?\n\nIn diesen Bergen gibt es lauter kostbare Relikte und Schmuckstücke... Dieser Ort ist für die Liga wie ein wahrgewordener Traum. Ich wäre Euch sehr dankbar, wenn Ihr Schätze dieser Art zu mir bringen könntet, falls Ihr über welche stolpern solltet. Für die Unannehmlichkeiten könnt Ihr sogar etwas von meinem Bier haben! Glaubt mir, <Kamerad/Fräulein>, das ist ein gutes Geschäft!", sourceObjective = "Bringt 10 Relikte von Ulduar zu Rork Spitzkinn in die Eisfestung.", progress = "Habt Ihr ein paar dieser Relikte gefunden?", completion = "Wunderschön! Gut gemacht habt Ihr das.\n\nKippen wir uns einen hinter die Birne! Lasst uns diesen glorreichen Fund feiern!", sourceObjectiveStatus = "unverified-source-field" }
quests[12871] = { id = 12871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe von der Forscherliga", description = "Interessant. Ich kann keine Schließmechanismen auf der Schale erkennen. Das lässt mich darauf schließen, dass man mehr als nur das andere Teil finden muss, um den Schlüsselstein zusammenzufügen.\n\nBringt die Schale zurück zum Expeditionsleiter Lagnus in der Eisfestung. Sobald er dann erst einmal seine Scheu überwunden hat, sollte er anhand der Schale herausfinden können, wie der Kern aussieht. Vielleicht können sie auch die Frostzwerge dazu bringen, bei der Suche zu helfen.\n\nIch werde versuchen herauszufinden, wie sich die zwei Teile zusammenfügen lassen. Wir werden uns wiedersehen, wenn wir beide etwas weiter gekommen sind.", sourceObjective = "Bringt Norgannons Schale zu Lagnus in die Eisfestung.", progress = "Hallo!", completion = "Bei Muradins Bart! Ist das hier das, von dem ich denke, dass es das ist?! Brann hat sich diesmal wirklich selbst übertroffen... wie auch Ihr in dem Fall! Die Jungs Zuhause werden das niemals glauben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12872] = { id = 12872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Norgannons Schale", description = "Scheibe des Erfinders wird aufgeladen.\n\nProzess abgeschlossen.\n\nNotfallprotokoll Gamma in Bearbeitung.\n\nLadevorgang von Notfallprotokoll abgeschlossen. Bitte zum Aktivieren von Archivar Mechaton, den Wächter von Norgannons Schale, aufgeladene Scheibe verwenden. Scheibe wird von Archivar Mechaton freigegeben, sobald Eure Identität verifiziert wurde.\n\nEuch ein angenehmes Jahrtausend.", sourceObjective = "Beschafft Euch Norgannons Schale von Archivar Mechaton.", progress = "Steht nicht nur so da, zeigt mir die Schale!", completion = "Das ist sie! Das ist die erste Hälfte von Norgannons Schlüsselstein. Gut gemacht, {name}. Wenn ich wieder in Eisenschmiede bin, werde ich Euch als Ehrenmitglied der Forscherliga vorschlagen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12873] = { id = 12873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der König der Frosterben", description = "Auf jeden Fall... Ich weiß ganz genau, wie der Kern aussieht. Falls ihn irgendeiner der Frosterben gesehen haben sollte, dann wird ihm die Beschreibung mit Sicherheit bekannt vorkommen.\n\nWir haben keine Zeit zu verlieren, lasst uns also gleich zur Sache kommen. Geht zu König Sturmherz und erbittet seine Hilfe... Er wird sicherlich jemanden kennen, der uns helfen kann, den Kern zu finden. Und seid freundlich zu ihm - in dieser Gegend wird er sehr respektiert.", sourceObjective = "Sprecht mit Yorg Sturmherz in der Eisfestung.", completion = "Norgannons Kern? Noch nie davon gehört. Kann jedoch gut sein, dass ich jemanden kenne, der es hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[12874] = { id = 12874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eifer der Frosterben", description = "Ich wäre ja durchaus bereit, Reisenden in Not Unterkunft zu bieten, aber ich möchte mich auch nur ungern in Eure Angelegenheiten einmischen.\n\nIch sag Euch was... meine Leute sind ehrliche und aufrichtige Krieger. An dem Tag, an dem ein Frosterbe zum Mann wird, muss er sich im Kampf beweisen. Er muss uns zeigen, dass er sich nicht von Größe einschüchtern lässt.\n\nBeweist mir, dass Ihr genauso stark und wild seid wie meine Männer, dann werde ich dafür sorgen, dass sie Euch ein Ohr schenken oder Euch ihre Klinge zur Verfügung stellen. Sprecht an der Klippe im Süden mit Fjorlin, er wird Euch auf die Probe stellen.", sourceObjective = "Yorg Sturmherz in der Eisfestung hat Euch gebeten, mit Fjorlin Frostbraue zu sprechen und Euch der Herausforderung zu stellen.", progress = "Ihr seid zurück. Wart Ihr siegreich?", completion = "Ha! Ich bin beeindruckt... vielleicht fließt doch etwas Frosterbenblut durch Eure Adern? Ihr steht jedoch zu Euren Worten, und genau das wollte ich wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12875] = { id = 12875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein erfahrener Führer", description = "Ich weiß nicht, wo sich dieser Kern versteckt, das war Euch doch klar? Aber ich habe gesagt, dass ich Euch helfe, und das werde ich auch.\n\nEs gibt da einen Einsiedler namens Drom Frostgriff, der in einer Höhle nördlich von hier lebt... unten im Tal. Wir haben uns ein wenig von den Titanen entfernt, da es nur noch so wenige gibt, aber Drom ist den alten Wegen treu geblieben... Er behält ihre wichtigsten Plätze im Auge und unterhält sich häufig mit dem Bewahrer Creteus.\n\nIhr könnt ihn vermutlich im hinteren Teil seiner Höhle antreffen... sagt ihm, dass ich Euch schicke, dann wird er Euch helfen.", sourceObjective = "Macht Drom Frostgriff ausfindig.", completion = "<Drom hustet ein wenig Blut aus.>\n\nNorgannons Kern, sagt Ihr? Ich habe einige Tage damit verbracht, mehr darüber herauszufinden, aber das scheint eines der Relikte zu sein, die noch immer gut beschützt sind. Vermutlich aus gutem Grund.\n\nWenn König Sturmherz Euch hergeschickt hat, dann muss er etwas Nobles in Euch sehen... und ich werde mich dem Wunsch meines Königs nicht widersetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12876] = { id = 12876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unwillkommene Gäste", description = "Unsere Späher haben im Tal nördlich von hier Eisenzwerge gesichtet. Ich hab' zufällig mitgekriegt, dass König Sturmherz Euch ausschickt, um Drom zu besuchen, und ehrlich gesagt mach' ich mir wegen denen ein bisschen Sorgen.\n\nFalls Ihr auf Eurem Weg auf Eisenzwerge stoßt, zeigt keine Gnade und erledigt sie schnell für mich, in Ordnung? Ich glaub' nicht, dass sie schon wissen, wo genau wir sind oder wie man hierher kommt, und ich will, dass das auch so bleibt.", sourceObjective = "Fjorlin Frostbraue in der Eisfestung möchte, dass Ihr 10 Sturmgeschmiedete Eindringlinge tötet.", completion = "Schlechte Neuigkeiten, Kamerad. Diese Eisenzwerge scheinen immer mehr zu werden... wir haben sie über die ganzen Berge verstreut gesehen. Das riecht nach Krieg.\n\nHabt Dank dafür, dass Ihr Euch um dieses Pack gekümmert habt... wir haben dadurch etwas mehr Zeit gewonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12877] = { id = 12877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der einsame Wächter", description = "Ich habe den Kern nie gefunden... doch ich habe oft mit dem Hüter Creteus gesprochen und das, was er gesagt oder besser: das, was er nicht gesagt hat, hat ihn verraten. Ihr findet Creteus auf der anderen Seite der Berge gen Osten in den Fußmarschen, wo er über die Maschine der Schöpfer Wache hält. Es kann gut sein, dass sich der Kern dort befindet, doch zuerst müsst Ihr Creteus' Gunst erlangen.\n\nDie Eisenzwerge sind hier gewesen und haben nach etwas gesucht... es ist gut möglich, dass sie nach dem Kern gesucht haben. Sie haben mir meinen Ring weggenommen. Findet ihren Anführer, erlangt meinen Ring zurück und legt diesen dann Creteus vor, damit er weiß, dass ich Euch geschickt habe.", sourceObjective = "Beschafft Frostgriffs Siegelring von einem der Eisenzwergüberwacher und bringt ihn zu Creteus in den Fußmarschen.", progress = "Hallo, {race}.\n\nEs erfreut mich, zu sehen, dass Ihr Euch dazu entschlossen habt, meine Bekanntschaft nicht mit der Klinge, sondern mit der Zunge zu machen. Meinen Erfahrungen nach scheint dies in letzter Zeit eine immer seltenere Eigenschaft unter Euresgleichen zu sein.", completion = "Droms Ring? Dass er Euch nicht selbst vorgestellt hat, lässt mich darauf schließen, dass es ihm nicht gut geht. Tut mir leid, das zu hören. Drom ist ein nobler Zwerg, wenn auch ein neugieriger.\n\nNun denn, weshalb seid Ihr hierher gekommen?", sourceObjectiveStatus = "unverified-source-field" }
quests[12878] = { id = 12878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das versteckte Relikt", description = "Während Eurer Abwesenheit wurde mir das Privileg einer Unterhaltung mit dem Zwerg Brann Bronzebart zuteil. Er gab mir zu verstehen, dass seine Aufgabe die Suche nach dem Schlüsselstein sei. Es stimmt mich zufrieden, dass seine Absichten zufriedenstellend sind... Dieser Zwerg, so glaube ich, könnte das Wesen sein, für das der Schlüsselstein geschaffen wurde.\n\nNorgannons Kern befindet sich im Eisigen Grab gen Südosten. Seine Bewacher sind uralte Wesen aus Eis. Sie werden Euch nicht willkommen heißen. Besiegt die Wächter und beschafft den Schlüsselstein. Ihr habt meinen Segen, {race}.", sourceObjective = "Creteus in den Fußmarschen hat Euch Informationen zukommen lassen, mit deren Hilfe Ihr Norgannons Kern finden könnt. Macht Euch auf den Weg dorthin.", completion = "<Die Truhe öffnet sich. Luft entweicht und erfüllt die Kammer mit einem modrigen Geruch, als läge dort etwas, das schon seit unzähligen Jahren hier gewesen ist. Norgannons Kern liegt auf dem Boden der Truhe, von den Jahren unberührt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12879] = { id = 12879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorn des Frosterbenkönigs", description = "<Als Ihr den Kern aus der Kiste nehmt, hört Ihr donnernde Schritte im Gang, die sich Euch nähern. In der Ferne ist leise der Klang eines Kampfes zu vernehmen.>", sourceObjective = "Bringt Norgannons Kern zu Creteus in die Fußmarschen.", progress = "Jemand nutzt die Seelenschmiede, um diese Armee zu erschaffen... Ulduar ist nicht mehr sicher. {race}, konntet Ihr den Kern finden?", completion = "Jemand nutzt die Seelenschmiede, um diese Armee zu erschaffen... Ulduar ist nicht mehr sicher.\n\n{race}, ich freue mich, dass Ihr vor diesen Monstrositäten zum Kern gelangen konntet.", sourceObjectiveStatus = "unverified-source-field" }
quests[12880] = { id = 12880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Meisterforscher", description = "Zum Kombinieren des Schlüsselsteins benötigt Ihr Norgannons Bindung - ein Gerät, das sich in der Maschine des Schöpfers in der großen Grube neben uns befindet. Brann müsste inzwischen mit der anderen Hälfte des Schlüsselsteins da unten sein. Ich habe ihn in Bezug auf den Gebrauch des Geräts instruiert. Er erwartet Euch.\n\nIch werde tun, was ich kann, um die Eisenzwerge abzulenken, aber ich weiß nicht, wie lange ich sie aufhalten kann. König Sturmherz wird in Kürze mit ein paar seiner Männer in der Eisfestung eintreffen, um bei der Verteidigung zu helfen. Bitte beeilt Euch, {race}.", sourceObjective = "Bringt Norgannons Kern zu Brann Bronzebart in die Maschine der Schöpfer.", progress = "Hallöchen, Kamerad! Schön, Euch zu sehen. Habt Ihr ihn gefunden?", completion = "Ihr seid brillant! Wirklich brillant. Das ist wahrlich ein glorreicher Tag.\n\nSchnell, gebt mir den Kern, bevor die Zwerge hier auftauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12881] = { id = 12881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gebrüder Bronzebart" }
quests[12882] = { id = 12882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Relikte", description = "Willkommen auf den Gipfeln.\n\nIch habe eine einfache Bitte an Euch, bevor Ihr Euren großen Ausflug antretet - wo auch immer dieser hinführen mag. In diesen Bergen verstreut gibt es uralte Ulduarschätze und -relikte. Die meisten befinden sich höchstwahrscheinlich im Besitz der verschiedenen empfindsamen Wesen dort.\n\nBringt jeden dieser Schätze zu mir zurück und ich werde Euch angemessen belohnen. Ich habe viele Sorten Starkbier - vielleicht werde ich Euch sogar mittrinken lassen.", sourceObjective = "Bringt 10 Relikte von Ulduar zu Olut Bierbauch bei der Absturzstelle Grom'ash.", progress = "Konntet Ihr die Relikte, von denen ich sprach, finden?", completion = "Die werden reichen! Herzlichen Dank. Ein Humpen für Eure Müh'?", sourceObjectiveStatus = "unverified-source-field" }
quests[12883] = { id = 12883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle von Drakuru", description = "Die Diener vernehmen den Ruf Eures Meisters! Der Lichkönig wird Drakuru die volle Kontrolle über die Armeen der Geißel in Zul'Drak geben. Uns wurde befohlen, alles zu töten.\n\nALLES MUSS STERBEN!\n\nWir werden die Leichen auf dem Todesfeld sammeln und sie dann zu Prinz Navarius in Zeramas schicken, damit sie dort in Diener der Geißel verwandelt werden! Nichts wird verschwendet, solange Drakuru ein Auge aufhält!\n\nBald werden wir das Blut der Propheten trinken und stärker werden, als jemals zuvor! Zul'Drak und Gundrak werden an die Geißel fallen!", sourceObjective = "Bringt Drakurus Befehle zu Kreuzfahrerlord Lantinga in der Lichtbresche in Zul'Drak.", progress = "Drakuru, hm? Ich habe den Namen schon einmal gehört...", completion = "Wenn dies derselbe Drakuru ist, wie der aus der Feste Drak'Tharon, dann... dann werden wir Hilfe von außerhalb benötigen.\n\nIn der Nähe sind Todesritter von Acherus stationiert. Sie folgen offensichtlich derselben Spur der Verwüstung, welche die Geißel hinterlassen hat, wie der Argentumkreuzzug. Da die Hälfte unserer Armee an der Argentumwache benötigt wird, um dort gegen die verrückt gewordenen Drakkaritrolle zu kämpfen, werden wir uns mit den Rittern der Schwarzen Klinge zusammentun müssen.\n\n<Lantinga murmelt vor sich hin.>\n\nIch hatte gehofft, dass ich diese Gauner nach der Sache bei der Kapelle des hoffnungsvollen Lichts nie wieder sehen müsste...", sourceObjectiveStatus = "unverified-source-field" }
quests[12884] = { id = 12884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schwarze Wacht", description = "Westlich von hier auf der anderen Seite der zerstörten Straßen und Gebäude liegt die Schwarze Wacht - ein Lager der Todesritter.\n\n<Kreuzfahrerlord Lantinga rollt die Schriftrolle mit Drakurus Befehlen wieder zusammen.>\n\nNehmt diese Befehle und liefert sie bei Stefan Vadu ab; er ist der leitende Todesritter in der Schwarzen Wacht. Lasst ihn wissen, dass der Argentumkreuzzug sich um Prinz Navarius kümmern wird und dass sie sich um Drakuru kümmern werden müssen.\n\nSeid vorsichtig, {name}. Der Weg zur Schwarzen Wacht wimmelt nur so von Dienern der Geißel.", sourceObjective = "Liefert Drakurus Befehle bei Stefan Vadu in der Schwarzen Wacht in Zul'Drak ab.", progress = "Was habt Ihr denn da, {race}?", completion = "<Stefan liest sich das Schreiben durch, zerknüllt es und wirf es ins Feuer.>\n\nNichts Neues. Der Argentumkreuzzug ist wieder einmal etwas zu langsam. Wir haben diesen Drakuru schon seit den Grizzlyhügeln verfolgt. Er ist zur Vernichtung bestimmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12885] = { id = 12885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verbannten von Ulduar", description = "Die Sturmgipfel sind faszinierend, aber hier findet Ihr mehr als bloß Titanenruinen. Jeder, der hier lebt, muss die Bedrohung durch Loken und seine Diener ertragen.\n\nEr hat seine Lieblingsdiener, die Eisenzwerge, auf einen brutalen Feldzug gegen alle Kreaturen aus Stein geschickt und die Irdenen aus Ulduar verbannt, die in Bergfels' Zuflucht an einem Berghang westlich der Bibliothek des Erfinders Unterschlupf fanden. Die dortigen Eisenzwerge setzen Bergfels und seinen Brüdern jedoch ordentlich zu. Findet sie und helft ihnen, {name}.", sourceObjective = "Sprecht mit Bergfels dem Steinformer in Bergfels' Zuflucht.", completion = "Ihr kennt also Brann Bronzebart, wie? Er ist unser engster Verbündeter unter denen, die aus Fleisch sind. Wir sind Blutsbrüder im Kampf gegen Loken und seinen Anhängern, im Kampf um Ulduar.", sourceObjectiveStatus = "unverified-source-field" }
quests[12886] = { id = 12886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Drakkensryd", description = "Das ist es, Ihr habt alle Aufgaben des Hildarthings bestanden... alle bis auf eine. Ihr seid unter den besten und wildesten unserer Schwestern aufgewachsen.\n\nDie letzte Aufgabe steht nun bevor. Der Drakkensryd - die wahre Prüfung des Werts und Kampfgeistes einer Hyldnir. Dort gibt es nur Euch, Euren Reitdrachen, eine Kettenharpune und einige Eurer Schwestern, mit denen Ihr um die Vorherrschaft kämpfen werdet.\n\nVerschont niemanden, dies wird nicht geduldet.", sourceObjective = "Verwendet die Hyldnirharpune, um 10 Drachenreiterinnen des Hildarthings im Tempel der Stürme zu besiegen.", progress = "Fort mit Euch!", completion = "Sif... bist du das?", sourceObjectiveStatus = "unverified-source-field" }
quests[12887] = { id = 12887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts als Spaß und Spiele", description = "Die Ritter der Schwarzen Klinge wollen die Geißelbasis im Nordwesten einnehmen, die man das Schattengewölbe nennt. Ich habe einen Kontaktmann in der Gruppe, der um Hilfe gebeten hat.\n\nDer erste Schritt ist, den Lichkönig zu blenden. Er nutzt ein Gerät namens Okular, das über den Türmen des Gewölbes schwebt, um das Gebiet zu überwachen.\n\nUnsere Zwerge haben etwas geschaffen, das sich dagegen einsetzen lässt. Wenn das 'Auge' zerstört ist, findet Baron Splitter auf dem Gelände des Gewölbes. Er wird so tun, als stünde er noch immer unter der Kontrolle des Lichkönigs.", sourceObjective = "Zerstört das Okular und erstattet danach Baron Splitter im Schattengewölbe Bericht.", progress = "Das Okular steht noch! Thassarian war ein Narr, Euch zu trauen.\n\nWer immer Ihr auch seid, kehrt nicht zurück, bevor es zerstört ist. Ich darf hier nicht enttarnt werden!", completion = "Vielleicht können wir jetzt wirklich etwas bewegen. Aber lasst Euch nicht täuschen, der Lichkönig kann immer noch durch seine Diener der Geißel 'sehen'.\n\nDarum seid Ihr hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[12888] = { id = 12888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SCHROTT-E", description = "Mit dieser Karte erhält der Benutzer Zugriff auf die Steuerkonsole des Schrottbots genannt SCHROTT-E. Möglich sind Wartung des Roboters und Umprogrammierung seiner Direktiven.\n\nSCHROTT-E scheint dem Inneren der Bibliothek des Erfinders zugewiesen worden zu sein. Die Karte zeigt eine Liste aller defekten Komponenten und ausgefallenen Systeme des Bots. Mit den entsprechenden Teilen kann er jedoch wieder funktionstüchtig gemacht werden.", sourceObjective = "Bringt die Zugriffskarte für SCHROTT-E sowie 4 Handvoll Kobaltbolzen und 5 überladene Kondensatoren zu SCHROTT-E in die Bibliothek des Erfinders.", progress = "<Ihr öffnet die Zugangsklappe von SCHROTT-E.>", completion = "<Ihr beginnt, die auf der Zugriffskarte angegebenen Reparaturen auszuführen. Als sie beendet sind, schließt Ihr die Zugangsklappe und schaltet den Stromschalter ein.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12889] = { id = 12889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prototypenkonsole", description = "Bezeichnung: SCHROTT-E.\n\nDirektive: Instandhaltung von Konsolen und Datenbanken der Bibliothek des Erfinders in Hüter Mimirs Abwesenheit.\n\nZeit seit letztem Instandhaltungszyklus: 489 Tage.\n\nStatus der schematischen Daten: unbekannt.\n\nAktuelle Aufgaben: Reparatur der Prototypenkonsole.", sourceObjective = "Benutzt die Prototypenkonsole in der Bibliothek des Erfinders.", completion = "Ihr untersucht den Bildschirm der Prototypenkonsole. Mindestens einer von Mimirs Bauplänen scheint die lange Zeit zwischen den Instandhaltungszyklen überstanden zu haben. Den angezeigten Diagrammen und Anweisungen der Bauplandatei nach zu urteilen, könntet Ihr den abgebildeten Mechagnom mit Leichtigkeit selbst zusammenbauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12890] = { id = 12890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn Größe von Bedeutung wäre..." }
quests[12891] = { id = 12891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich habe da eine Idee, aber zuerst...", description = "Als ich im, äh, Dienste des Lichkönigs stand, bedienten wir uns oft eines Geräts namens \"Herrschaftsstab\", mit dem wir dafür sorgten, dass einige der intelligenteren Diener der Geißel nicht aus der Reihe tanzten.\n\nIhr müsst mir dabei assistieren, einen neuen zu konstruieren.\n\nZu Eurem Glück sind alle notwendigen Komponenten verfügbar: eine Kultistenrute, ein Monstrositätenhaken, ein Spukseil und eine Handvoll Geißelessenz.\n\nDies sollte nicht allzu schwierig werden, {class}.", sourceObjective = "Baron Splitter im Schattengewölbe hat Euch gebeten, eine Kultistenrute, einen Monstrositätenhaken, ein Spukseil und 5 Geißelessenzen zu besorgen.", progress = "Wenn es Euch gelungen ist, die Dinge zu besorgen, um die ich Euch gebeten habe, baue ich das Gerät - mit ein paar Modifikationen zu unseren Gunsten - und dann sind wir im Geschäft.", completion = "Schnell, gebt sie mir und bleibt außer Sichtweite!\n\nDie Rute, der Haken und das Seil sind miteinander kombiniert in ihrem Nutzen sehr selbsterklärend. Ich brauche das Ergebnis nur mit den Essenzen zu durchziehen und dann werden wir fortfahren können.\n\nIn seiner Bauweise mag es zwar banal sein, in seiner Anwendung ist es jedoch außergewöhnlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[12892] = { id = 12892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts als Spaß und Spiele", description = "Die Ritter der Schwarzen Klinge wollen die Geißelbasis im Nordwesten einnehmen, die man das Schattengewölbe nennt. Ich stehe mit einem von ihnen in Kontakt, der uns um Hilfe gebeten hat.\n\nDer erste Schritt wird es sein, dem Lichkönig die Sicht zu rauben. Er verwendet zur Überwachung des Gebiets ein Gerät namens \"Okular\", das über den Türmen des Gewölbes schwebt.\n\nUnsere Goblins haben etwas konstruiert, das Ihr dagegen einsetzen könnt. Nachdem das \"Auge\" zerstört ist, müsst Ihr Baron Splitter auf dem Gelände des Gewölbes finden. Er gibt vor, immer noch unter der Kontrolle des Lichkönigs zu stehen.", sourceObjective = "Zerstört das Okular und erstattet Bericht bei Baron Splitter im Schattengewölbe.", completion = "Womöglich sind wir nun imstande, wirklich etwas zu unternehmen. Lasst Euch jedoch nicht täuschen, der Lichkönig kann immer noch durch seine Geißeldiener \"sehen\".\n\nAus diesem Grund seid Ihr hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[12893] = { id = 12893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreit Euren Geist", description = "Ekel, Lady Nachtwald und der Springer würden im Kampf gegen den Lichkönig exzellente Waffen abgeben, wenn sie von seinem Willen befreit werden könnten. Genau das ist der Zweck des Herrschaftsstabs.\n\nIhr findet sie auf den Hängen im Osten und Westen des Gewölbes sowie auf der mittleren Ebene des Gewölbes über uns. Der Stab muss auf die drei Leichen angewandt werden.\n\nFliegt nun. Wir werden sie auf unsere Seite holen!", sourceObjective = "Baron Splitter im Schattengewölbe möchte, dass Ihr den Herrschaftsstab auf die Leichen von Ekel, Lady Nachtwald und dem Springer anwendet.", completion = "Wir werden diese drei gut gebrauchen können, wenn wir endlich das Gewölbe einnehmen.\n\nWo wir gerade dabei sind...", sourceObjectiveStatus = "unverified-source-field" }
